			{id=5646,title="Explosive Brew",body="If a Hopper reaches its target, it hops madly then explodes. The explosion inflicts $114291s1 Fire damage to players within $114291A1 yards and knocks them down.",difficultyIDs={1,2,3,4}},
			{id=5647,title="Bopper",body="The large Boppers carry a heavy hammer.",difficultyIDs={1,2,3,4}},
			{id=5648,title="Big Ol' Hammer",body="When Boppers die, they drop their Big Ol' Hammers. Players can pick up the Hammer to gain three charges of the Smash! ability.",difficultyIDs={1,2,3,4}},
			{id=5649,title="Smash!",body="Slam the Big Ol' Hammer into the ground and knock up all nearby virmen, destroying all Hoppers and Hoplings within $111666A1 yards and dealing heavy damage to Boppers.",difficultyIDs={1,2,3,4}},
		},
	},
	[670]={
		encounterID=670,
		instanceID=302,
		order=3,
		name="Yan-Zhu the Uncasked",
		lore="In a desperate attempt to save the family brewery, Uncle Gao set about concocting what he believed would be the ultimate ale, a full-bodied elixir of depthless flavor. Yet his bold experiment resulted in a bitter and extremely volatile alemental creature, dubbed Yan-Zhu the Uncasked.",
