		sections={
			{id=5595,title="Brew Bolt",body="If there are no players near Yan-Zhu, he will begin casting Brew Bolts. Inflicts $114548s1 Frost damage and increases magic damage taken by the target by $114548s2% for $114548d. This effect stacks.",difficultyIDs={1,2,3,4}},
			{id=5650,title="Brewmastery: Wheat",body="Uncle Gao's crazy experiments grant Yan-Zhu one of two wheat brew abilities.",difficultyIDs={1,2,3,4}},
			{id=5651,title="Bloat",body="Yan-Zhu infuses a random player with an excessive quantity of brew. This Bloat causes brew to gush from their ears for $106546d, inflicting $106560s1 Frost damage and knocking back targets in a 10-degree cone on either side of the bloated player.",difficultyIDs={1,2,3,4}},
			{id=5652,title="Blackout Brew",body="The heavy Blackout Brew inflicts $106851s1 Frost damage to all players and applies 3 stacks of Blackout Brew. Stacks can be removed by moving and jumping. If Blackout Brew reaches 10 stacks, the Brew stuns the player for $106857d.",difficultyIDs={1,2,3,4}},
			{id=5596,title="Brewmastery: Ale",body="Uncle Gao's new fermentation procedures grant Yan-Zhu one of two ale brew abilities.",difficultyIDs={1,2,3,4}},
			{id=5653,title="Bubble Shield",body="Yan-Zhu covers himself with 8 small bubbles. Each bubble grants Yan-Zhu 10% damage reduction. This effect stacks.",difficultyIDs={1,2,3,4}},
			{id=5654,title="Yeasty Brew Alemental",body="Yan-Zhu summons forth Yeasty Brew Alementals to aid him.",difficultyIDs={1,2,3,4}},
			{id=5655,title="Ferment",body="The Yeasty Brew Alemental fires a fermentation beam towards Yan-Zhu the Uncasked, but players may intercept the beam and receive its effect by standing between the two Alementals. The fermentation restores $114451s1% of health and mana every 1 sec. to the affected target.",difficultyIDs={1,2,3,4}},
			{id=6634,title="Brew Bolt",body="Yeasty Brew Alementals can cast a less powerful version of Brew Bolt, inflicting $116155s1 Frost damage.",difficultyIDs={1,2,3,4}},
			{id=5598,title="Brewmastery: Stout",body="Uncle Gao has modified the family recipe, granting Yan-Zhu one of two stout brew abilities.",difficultyIDs={1,2,3,4}},
			{id=5656,title="Carbonation",body="Yan-Zhu fills the room with Carbonation for $115003d. The Carbonation inflicts $114386s1 Frost damage every $115003t1 sec. to enemies that are close to the ground and prevents them from attacking or casting spells due to acute asphyxiation.\n\nIn addition, Carbonation causes Fizzy Bubbles to spawn.",difficultyIDs={1,2,3,4}},
			{id=5657,title="Fizzy Bubble",body="Clicking on a Fizzy Bubble grants a player the ability to fly for $114459d.",difficultyIDs={1,2,3,4}},
			{id=5658,title="Wall of Suds",body="Yan-Zhu periodically summons forth walls of sudsy brew. The onrushing brew inflicts $114466s1 Frost damage every $114467t1 seconds to players that stand within the wall and stuns them for $114466d.",difficultyIDs={1,2,3,4}},
			{id=5659,title="Sudsy",body="The sudsy nature of Yan-Zhu grants players the ability to jump extra high.",difficultyIDs={1,2,3,4}},
		},
	},
