	[673]={
		encounterID=673,
		instanceID=312,
		order=1,
		name="Gu Cloudstrike",
		lore="Before the escape of the sha, Gu Cloudstrike was entrusted with training the elite Shado-Pan spellcasters. Now this formerly gentle and reserved pandaren revels in unleashing his astounding powers, with devastating consequences. He has asserted control over the mystical Azure Serpent, and his students are helpless in the wake of Cloudstrike's lethal attacks.",
		dungeonEncounterID=1303,
		uiMapID=443,
		pin={x=0.6498,y=0.6915},
		difficultyIDs={1,2,8,24},
		npcIDs={56747},
