		},
		sections={
			{id=5621,title="Stage One: Let Me Show You My Power!",body="Gu Cloudstrike calls for the Azure Serpent to help him defeat the intruders."},
			{id=5629,title="Invoke Lightning",body="Gu Cloudstrike inflicts $106984s1 Nature damage to a random player, inflicting an additional $107202s1 Nature damage to all players within $107202A1 yards of the target."},
			{id=5630,title="Static Field",body="The Azure Serpent creates a Static Field at the location of a random player, inflicting $106932s1 Nature damage to all players within $106932a1 yards of the point of impact. The Static Field then persists for $106941d, inflicting an additional $128889s1 Nature damage every $106941t1 sec."},
			{id=5624,title="Stage Two: Charge Me With Your Power!",body="Gu Cloudstrike enters a meditative state, becoming immune to all damage. The Azure Serpent moves in to attack."},
			{id=5631,title="Charging Soul",body="The Azure Serpent shields Gu Cloudstrike, making him immune to all damage."},
			{id=5633,title="Magnetic Shroud",body="The Azure Serpent casts a Magnetic Shroud onto every player. The Shroud absorbs $107140s1 healing cast on each player and inflicts $107140s2 Nature damage every $107140t2 sec. The Shroud overloads when healing on a player exceeds its capacity, removing the Magnetic Shroud. The overload then heals all other players within $107174A1 yards for $107174s1 healing divided by the number of players within range."},
			{id=5632,title="Lightning Breath",body="The Azure Serpent unleashes Lightning Breath within a 45 degree cone in front of him, inflicting $102572s1 Nature damage every $102573t1 sec. for $102573d."},
			{id=5627,title="Stage Three: Do Not Fail Me!",body="After the players defeat the Azure Serpent, Gu Cloudstrike rejoins the fight."},
			{id=5634,title="Overcharged Soul",body="Periodically inflicts Nature damage to nearby enemies, frequency proportional to missing health."},
		},
	},
