		sections={
			{id=5670,title="Titan Gas",body="Titan Gas fills the room, inflicting $116782s1 Frost damage every $116779t1 sec. to all players and energizing both players and constructs, increasing melee damage dealt."},
			{id=5678,title="Emperor's Rage",body="The smallest Terracotta warriors, the Emperor's Rage strike quickly with dual axes and often formed the forward lines in Lei Shin's mechanical armies."},
			{id=5730,title="Focused Assault",body="Every Emperor's Rage fixates on a random player, attacking only that player until the player dies or the Rage can no longer attack them."},
			{id=5731,title="Unarmored",body="The Emperor's Rage wear very little armor, and all types of crowd control effects work against them."},
			{id=5676,title="Emperor's Courage",body="The Emperor's Courage carry a polearm to harry opponents and form a powerful defensive wall with shields and armor."},
			{id=5732,title="Focused Defense",body="The Emperor's Courage comes to the aid of Jan-xi or Qin-xi by fixating on a tank, attacking only that player until the player dies or the Courage can no longer attack them."},
			{id=5733,title="Impeding Thrust",body="The Impeding Thrust of the Emperor's Courage inflicts $117485s1% normal melee damage and reduces the target's movement speed by $117485s2% for $117485d. Stacks up to $117485U times."},
			{id=5734,title="Half Plate",body="The Emperor's Courage wear armor protecting the front of their bodies. The Half Plate blocks or deflects any damage dealt by players to the front of the Emperor's Courage, but they remain susceptible to movement impairing effects."},
			{id=5677,title="Emperor's Strength",body="The heavily-armored Emperor's Strength strike earth-shaking blows with their massive two-handed hammers."},
			{id=5735,title="Energizing Smash",body="The Emperor's Strength smash the ground in front of them, inflicting $116550s2 Physical damage to players within 10 yards of the strike zone and stunning them for $116550d. The radius of the effect increases by 1 yard after each use of Energizing Smash."},
			{id=5736,title="Full Plate",body="The Emperor's Strength wear heavy armor that grants them immunity to all crowd control effects."},
			{id=5726,title="Jan-xi and Qin-xi",body="Jan-xi and Qin-xi activate after 90 seconds and share their health pool."},
			{id=5672,title="Devastating Combo",body="Jan-xi and Qin-xi perform a devastating combination of five attacks.$[!5,6\n\nIn Heroic Difficulty, the Devastating Combo consists of ten attacks.$]"},
			{id=5673,title="Devastating Arc",body="Jan-xi and Qin-xi strike a $116835a1 yard hemispherical area to the left, right, or in front of them. These Devastating Arc attacks inflict $116835s1 Physical damage and reduce the target's armor by $116835s2% for $116835d. Stacks up to $116835U times. The immense power of these attacks ignore any player effects that grant damage immunity."},
			{id=5729,title="Stomp",body="Jan-xi and Qin-xi stomp the ground, inflicting $116969s2 Physical damage to all players within $116969A1 yards and stunning them for $116969d. The immense power of this attack ignores player effects that grant damage immunity."},
			{id=5728,title="Magnetic Armor",body="Jan-xi and Qin-xi magnetize their current targets for $116818d. If a magnetized player moves more than 16 yards away from the constructs, a strong magnetic force pulls them back."},
			{id=5727,title="Opportunistic Strike",body="Avoiding attacks in a Devastating Combo causes the player to gain a Growing Opportunity. If a player avoids all of the attacks in a Devastating Combo, they gain the Opportunistic Strike ability for $116808d, which inflicts $116809s1 Physical damage."},
			{id=5674,title="Titan Spark",body="When any construct dies, it releases a Titan Spark.",difficultyIDs={5,6}},
			{id=5737,title="Focused Energy",body="A newly created Titan Spark fixates on a player, attacking only that player until the player dies or the Spark can no longer attack them.",difficultyIDs={5,6}},
			{id=5738,title="Energy of Creation",body="When a Titan Spark dies or gets close to any player, it releases the Energy of Creation. The Energy inflicts $116805s1 Nature damage to all players within $116805A1 yards and energizes any constructs, increasing their attack speed by $116805s2% for $116805d. This effect stacks.",difficultyIDs={5,6}},
		},
	},
