		sections={
			{id=5691,title="Amethyst Guardian",body="The Amethyst Guardian gains energy when within $115792A1 yards of another Guardian. The Guardian uses this energy to cast Amethyst Overload. If no other Guardian is within range, it instead gains the Solid Stone effect.$[!1,3\n\nIn 10 player Normal Difficulty, a rotating set of three of the four guardians are present each week.$]$[!5\n\nIn 10 player Heroic Difficulty, a rotating set of three of the four guardians are present each week.$]$[!7\n\nIn Raid Finder Difficulty, a rotating set of three of the four guardians are present each week.$]"},
			{id=5692,title="Amethyst Pool",body="The Amethyst Guardian creates a pool that inflicts $130774s2 Shadow damage every $130774t1 sec. to enemies who enter the area. Lasts $116235d."},
			{id=5768,title="Amethyst Overload",body="Upon reaching full energy the guardian overloads, inflicting $115844s1 Shadow damage to all enemies and interrupting Amethyst Petrification. The Overload does not free fully petrified enemies."},
			{id=5769,title="Amethyst Petrification",body="The Guardian attempts to turn its enemies to amethyst, reducing the Shadow damage they take by $115864s1% but progressively slowing their movement speed. Enemies who reach $115861u stacks of Petrification turn to stone and cannot move or act."},
			{id=5771,title="Cobalt Guardian",body="The Cobalt Guardian gains energy when within $115792A1 yards of another Guardian. The Guardian uses this energy to cast Cobalt Overload. If no other Guardian is within range, it instead gains the Solid Stone effect.$[!1,3\n\nIn 10 player Normal Difficulty, a rotating set of three of the four guardians are present each week.$]$[!5\n\nIn 10 player Heroic Difficulty, a rotating set of three of the four guardians are present each week.$]$[!7\n\nIn Raid Finder Difficulty, a rotating set of three of the four guardians are present each week.$]"},
			{id=5772,title="Cobalt Mine",body="Launches a charged cobalt shard at a player's location. After a $129426s1 sec arming time, any player within $129428A1 yds will detonate the shard, inflicting $116281s1 Arcane damage and rooting all players within $116281A1 yds for $116281d."},
			{id=5775,title="Cobalt Overload",body="Upon reaching full energy the guardian overloads, inflicting $115840s1 Arcane damage to all enemies and interrupting Cobalt Petrification. The Overload does not free fully petrified enemies."},
			{id=5776,title="Cobalt Petrification",body="The Guardian attempts to turn its enemies to cobalt, reducing the Arcane damage they take by $115864s1% but progressively slowing their movement speed. Enemies who reach $115861u stacks of Petrification turn to stone and cannot move or act."},
			{id=5773,title="Jade Guardian",body="The Jade Guardian gains energy when within $115792A1 yards of another Guardian. The Guardian uses this energy to cast Jade Overload. If no other Guardian is within range, it instead gains the Solid Stone effect.$[!1,3\n\nIn 10 player Normal Difficulty, a rotating set of three of the four guardians are present each week.$]$[!5\n\nIn 10 player Heroic Difficulty, a rotating set of three of the four guardians are present each week.$]$[!7\n\nIn Raid Finder Difficulty, a rotating set of three of the four guardians are present each week.$]"},
			{id=5777,title="Jade Shards",body="The Jade Guardian fires shards of jade in all directions, inflicting $116223s1 Nature damage to all players."},
			{id=5780,title="Jade Overload",body="Upon reaching full energy the guardian overloads, inflicting $115842s1 Nature damage to all enemies and interrupting Jade Petrification.  The Overload does not free fully petrified enemies."},
			{id=5781,title="Jade Petrification",body="The Guardian attempts to turn its enemies to jade, reducing the Nature damage they take by $115864s1% but progressively slowing their movement speed. Enemies who reach $115861u stacks of petrification turn to stone and cannot move or act."},
			{id=5774,title="Jasper Guardian",body="The Jasper Guardian gains energy when within $115792A1 yards of another Guardian. The Guardian uses this energy to cast Jasper Overload. If no other Guardian is within range, it instead gains the Solid Stone effect.$[!1,3\n\nIn 10 player Normal Difficulty, a rotating set of three of the four guardians are present each week.$]$[!5\n\nIn 10 player Heroic Difficulty, a rotating set of three of the four guardians are present each week.$]$[!7\n\nIn Raid Finder Difficulty, a rotating set of three of the four guardians are present each week.$]"},
			{id=5778,title="Jasper Chains",body="The Jasper Guardian chains two enemy targets together. While the targets are over $130395m1 yds apart the chains inflict $130395M3 Fire damage, increased by $130395s2% for each second they remain apart. The chains will break if the targets remain apart for $130395u total seconds."},
			{id=5783,title="Jasper Overload",body="Upon reaching full energy the guardian overloads, inflicting $115843s1 Fire damage to all enemies and interrupting Jasper Petrification. The Overload does not free fully petrified enemies."},
			{id=5784,title="Jasper Petrification",body="The Guardian attempts to turn its enemies to jasper, reducing the Fire damage they take by $115864s1% but progressively slowing their movement speed. Enemies who reach $115861u stacks of petrification turn to stone and cannot move or act."},
			{id=6562,title="Shared Abilities",body="All four guardians have access to these abilities."},
			{id=5785,title="Solid Stone",body="When no other stone guards are nearby the Guardian reverts to stone form. While in this form it takes $115745s1% reduced damage but cannot gain energy."},
			{id=6528,title="Rend Flesh",body="The Guardian rends the flesh of the target, causing $125206s1 Physical damage every $125206t1 sec. Lasts $125206d."},
			{id=6563,title="Power Down",body="When the guardians reach 75% and 40% remaining health, one of them will power down all Energized Tiles in the room to prevent players from using the energy.",difficultyIDs={5,6}},
			{id=5694,title="Encounter Area",difficultyIDs={5,6}},
			{id=5695,title="White Floor Tiles",body="These tiles absorb the energy from Living Amethyst, Living Cobalt, Living Jade, and Living Jasper when a player stands on them. Each tile absorbs one charge of energy. For each tile currently energized in the room, every player gains a stack of Energized Tiles.",difficultyIDs={5,6}},
			{id=5786,title="Energized Tiles",body="The energy of the living stone flows through the room tiles, empowering players and permanent pets and increasing damage dealt by $116541s1% and Spirit by $116541s2%. This effect stacks.",difficultyIDs={5,6}},
			{id=5696,title="Living Amethyst Crystal",body="The energy that powers the Amethyst Guardian forms into a crystal. Players who interact with this crystal gain the Living Amethyst effect.",difficultyIDs={5,6}},
			{id=5761,title="Living Amethyst",body="$116322u charges of the energy that animates the Amethyst Guardian tear though your body. Each charge inflicts $116322s1 Shadow damage every $116322t1 sec. Players drain the energy charges into white floor tiles to energize them.",difficultyIDs={5,6}},
			{id=5762,title="Living Cobalt Crystal",body="The energy that powers the Cobalt Guardian forms into a crystal. Players who interact with this crystal gain the Living Cobalt effect.",difficultyIDs={5,6}},
			{id=5763,title="Living Cobalt",body="$116199u charges of the energy that animates the Cobalt Guardian tear though your body. Each charge inflicts $116199s1 Arcane damage every $116199t1 sec. Players drain the energy charges into white floor tiles to energize them.",difficultyIDs={5,6}},
			{id=5764,title="Living Jade Crystal",body="The energy that powers the Jade Guardian forms into a crystal. Players who interact with this crystal gain the Living Jade effect.",difficultyIDs={5,6}},
			{id=5765,title="Living Jade",body="$116301u charges of the energy that animates the Jade Guardian tear though your body. Each charge inflicts $116301s1 Nature damage every $116301t1 sec. Players drain the energy charges into white floor tiles to energize them.",difficultyIDs={5,6}},
			{id=5766,title="Living Jasper Crystal",body="The energy that powers the Jasper Guardian forms into a crystal. Players who interact with this crystal gain the Living Jasper effect.",difficultyIDs={5,6}},
			{id=5767,title="Living Jasper",body="$116304u charges of the energy that animates the Jasper Guardian tear though your body. Each charge inflicts $116304s1 Fire damage every $116304t1 sec. Players drain the energy charges into white floor tiles to energize them.",difficultyIDs={5,6}},
		},
	},
	[682]={
		encounterID=682,
		instanceID=317,
		order=3,
		name="Gara'jal the Spiritbinder",
		lore="Leader of the Zandalar trolls' assault on the vaults, Gara'jal is determined to crack open this trove of ancient mystery and bring back whatever arcane power and knowledge he can find. Gifted with dark talents and surrounded by a loyal cadre of Zandalar mystics, he has broken through the outer walls and will not rest until the vaults belong to him.",
		dungeonEncounterID=1434,
		uiMapID=472,
		pin={x=0.7787,y=0.3449},
		difficultyIDs={3,4,5,6,7},
		npcIDs={60143},
