		sections={
			{id=5742,title="Spirit Totem",body="Gara'jal the Spiritbinder periodically summons a Spirit Totem at a random location."},
			{id=6206,title="Cross Over",body="Spirit Totems cause the nearest $116166I players within $116166A1 yards to cross over to the spirit world when they are destroyed. The process of Crossing Over leaves the victim with $116161m1% of their current health.",difficultyIDs={3,4,5,6}},
			{id=6207,title="Cross Over",body="Players use Spirit Totems to cross over into the spirit world. Players exist in the spirit world for $116260d before returning to the real world and gain the ability Return Soul.",difficultyIDs={7}},
			{id=6655,title="Return Soul",body="Return Soul causes the player to return their soul to their body in the real world.",difficultyIDs={7}},
			{id=5743,title="The Spirit World",body="Players crossing over to the Spirit World must return to the real world within $116161d or die.",difficultyIDs={3,4,5,6}},
			{id=5760,title="Frail Soul",body="Returning to the real world from the Spirit World inflicts players with a Frail Soul for $117723d. Attempting to cross into the Spirit World with a Frail Soul kills the player.",difficultyIDs={5,6}},
			{id=5744,title="Spiritual Innervation",body="Healing a player in the Spirit World energizes their soul with Spiritual Innervation. The effect of Spiritual Innervation varies depending on the class and specialization of the healed player, and the effect grows as the player continues to receive heals."},
			{id=6656,title="Revitalized Spirit",body="When a player in the Spirit World is healed to full, their spirit is revitalized. Players with Revitalized Spirit gain the Return Soul ability.",difficultyIDs={3,4,5,6}},
			{id=6657,title="Return Soul",body="Return Soul causes the player to return their soul to their body in the real world.",difficultyIDs={3,4,5,6}},
			{id=5739,title="Shadowy Minion",body="Shadowy Minions only exist in the Spirit World, but damage players in the real world with Spiritual Grasp."},
			{id=5740,title="Spiritual Grasp",body="A Shadowy Minion reaches into the real world with a Spritual Grasp, inflicting $115982s1 Shadow damage on a random player in the real world."},
			{id=5741,title="Shadow Bolt",body="A Shadowy Minion fires a bolt at a random player in the Spirit World, inflicting $122118s1 Shadow damage.",difficultyIDs={3,4,5,6}},
			{id=5753,title="Voodoo Dolls",body="Gara'jal the Spiritbinder fixates on his current target, turning that player and 2 other players into Voodoo Dolls. A Voodoo Doll copies $116000m1% of their damage received to all other Voodoo Dolls in the raid. The Voodoo Doll effect persists until either the victim perishes or Gara'jal the Spiritbinder banishes his fixated target to the Spirit World.\n\nPlayers turned into Voodoo Dolls cannot enter the Spirit World.$[!4,6,7\n\nIn 25 player raids, Gara'jal chooses 3 other players from the raid to turn into Voodoo Dolls.$]"},
			{id=5756,title="Banishment",body="Gara'jal the Spiritbinder banishes his current target to the Spirit World. While in the Spirit World, a Severer of Souls assaults the victim.\n\n$[!3,4 In Normal Difficulty the Severer of Souls is only visible to the banished victim.$]\n$[!5,6 In Heroic Difficulty, three Severers of Souls attack. One of these Severers of Souls is only visible to the banished victim. The other two are visible to the raid.$]"},
			{id=5757,title="Severer of Souls",body="Severers of Souls attempt to tear apart the soul of Banished victims."},
			{id=5758,title="Soul Sever",body="If players do not defeat every Severer of Souls within $116278d, the Banished victim dies.",difficultyIDs={3,4,5,6}},
			{id=6698,title="Shadowy Attacks",body="Gara'jal will periodically use the following attacks instead of his normal melee attacks:\n\n- Sweeping Kick\n- Hammer Fist\n- Right Cross\n- Left Hook\n\nThese attacks inflict Shadow damage to the target and bypass any absorption effects."},
			{id=5759,title="Frenzy",body="Gara'jal the Spiritbinder Frenzies when he reaches 20% remaining health, gaining $117752m1% melee haste and inflicting $117752m2% additional damage.\n\nGara'jal the Spiritbinder also stops summoning Spirit Totems."},
			{id=6813,title="Final Destination",body="After 6 minutes Gara'jal goes berserk and casts the spell Final Desination. Final Destination instantly kills all players.",difficultyIDs={3,4,5,6}},
			{id=6814,title="Final Destination",body="After 15 minutes Gara'jal goes berserk and casts the spell Final Desination. Final Destination instantly kills all players.",difficultyIDs={7}},
		},
	},
