			{itemID=89979,diffs={7},faction=-1},
		},
		sections={
			{id=5818,title="Sha Corruption",body="Killing a member of the Protectors causes Sha Corruption to explode from their bodies and possess the remaining Protectors. Sha Corruption heals each Protector to their maximum health, increases their damage done by $117052s1%, and grants them additional abilities."},
			{id=5789,title="Protector Kaolan"},
			{id=5790,title="Touch of Sha",body="Protector Kaolan corrupts a player, inflicting $117519s1 Shadow damage every $117519t1 seconds until players defeat Protector Kaolan."},
			{id=5791,title="Defiled Ground",body="Protector Kaolan uses this ability after gaining a single dose of Sha Corruption.\n\nProtector Kaolan desecrates the land beneath a player's location for the remainder of the fight, inflicting $117989s1 Shadow damage every second and increasing damage taken from Defiled Ground by $118091s2% for $118091d. This effect stacks."},
			{id=5792,title="Expel Corruption",body="Protector Kaolan uses this ability after gaining two doses of Sha Corruption.\n\nProtector Kaolan expels a mass of corruption at his location for the remainder of the fight, inflicting $117955s1 Shadow damage to all players within $117955A1 yards every $117943t1 seconds. The damage of Expelled Corruption decreases as a player stands farther away from the source of corruption."},
			{id=5793,title="Elder Regail"},
			{id=5801,title="Lightning Bolt",body="Elder Regail hurls a bolt of lightning at his current target, inflicting $117187s1 Nature damage."},
			{id=5802,title="Lightning Prison",body="Elder Regail imprisons 2 players in a field of lightning and stuns them. The Lightning Prison causes each player to inflict $117436s2 Nature damage every second to all players within $117398A1 yards.$[!4,6\n\nIn 25 player Difficulty, Elder Regail imprisons 3 players.$]"},
			{id=5804,title="Lightning Storm",body="Elder Regail uses this ability after gaining a single dose of Sha Corruption.\n\nElder Regail summons a Lightning Storm, creating several waves of lightning strikes. The first wave strikes at Elder Regail's location and then successive waves strike in a ring around him at 20, 40, 60 and 80 yards. Each strike inflicts $118003s1 Nature damage to all players within $118003A1 yards of Lightning Storm's impact."},
			{id=5805,title="Overwhelming Corruption",body="Elder Regail uses this ability after gaining two doses of Sha Corruption.\n\nCorruption overwhelms Elder Regail, inflicting $117353s1 Shadow damage to all players every $117351t1 seconds and increases their damage taken from Overwhelming Corruption by $117353s2%. This effect stacks."},
			{id=5794,title="Elder Asani"},
			{id=5819,title="Water Bolt",body="Elder Asani hurls a bolt of water at a random player's location, inflicting $117163s1 Nature damage to all players within $117163A1 yards of the targeted location."},
			{id=5820,title="Cleansing Waters",body="Elder Asani summons a globe of Cleansing Waters at a Protector's location. When the globe reaches the ground, it heals all targets within $117283A1 yards for $117283s1% of their total health every second. Targets also receive $117283s2% additional healing from all sources for $117283d."},
			{id=5821,title="Corrupted Waters",body="Elder Asani uses this ability after gaining a single dose of Sha Corruption.\n\nElder Asani summons a globe of Corrupted Water that empowers all Protectors, granting them $117230s1% melee and casting speed until destroyed."},
			{id=5822,title="Purified",body="Destroying the Corrupted Waters grants all players within $117235A1 yards the Purified effect, increasing melee, ranged and spell casting speed by $117235s1% for $117235d."},
			{id=5823,title="Overwhelming Corruption",body="Elder Asani uses this ability after gaining two doses of Sha Corruption.\n\nCorruption overwhelms Elder Asani, inflicting $117353s1 Shadow damage to all players every $117351t1 seconds and increases their damage taken from Overwhelming Corruption by $117353s2%. This effect stacks."},
			{id=5824,title="Minion of Fear",body="Minions of Fear pour from the Terrace of Endless Spring, pursuing the Protector with the lowest remaining health.",difficultyIDs={5,6}},
			{id=5825,title="Corrupted Essence",body="When a Minion of Fear dies, it infects the 2 closest players with Corrupted Essence, increasing their damage done by $118191s1% for $118191d. This effect stacks up to $118191U times.\n\nIf Corrupted Essence ever reaches $118191U stacks, the player replaces the Corrupted Essence effect with the Essence of Fear.$[!4,6\n\nIn 25 player Difficulty, Corrupted Essences infect the 5 closest players.$]",difficultyIDs={5,6}},
			{id=5826,title="Essence of Fear",body="The Essence of Fear inflicts $118198s1 Shadow damage to all players within $118198A1 yards.",difficultyIDs={5,6}},
			{id=5833,title="Greater Corrupted Essence",body="When a Minion of Fear reaches a Protector, it fills them with Greater Corrupted Essence, increasing their damage done by $117905s1% for $117905d. This effect stacks up to $117905U times.\n\nIf Greater Corrupted Essence ever reaches $117905U stacks, the Protector replaces the Greater Corrupted Essence effect with the Greater Essence of Fear.",difficultyIDs={5,6}},
			{id=5834,title="Greater Essence of Fear",body="The Greater Essence of Fear inflicts $118186s1 Shadow damage to all players and horrifies them for $118186d.",difficultyIDs={5,6}},
		},
	},
	[685]={
		encounterID=685,
		instanceID=312,
		order=3,
		name="Sha of Violence",
		lore="Bloodthirsty, ruthless, and savage, the Sha of Violence is unfettered within the Shado-Pan Monastery. Feeding on the Horde and Alliance's brutality, the entity gleefully ravages the monks who struggle to impede the monstrous onslaught.",
		dungeonEncounterID=1305,
		uiMapID=443,
		pin={x=0.4259,y=0.293},
