			{itemID=81184,diffs={},faction=-1},
			{itemID=81185,diffs={},faction=-1},
		},
		sections={
			{id=5810,title="Disorienting Smash",body="The Sha smashes the target, inflicting $106872s1 Shadow damage and causing it to wander confused for up to $106872d. Any damage taken while confused removes the effect."},
			{id=5811,title="Smoke Blades",body="The Sha attacks nearby enemies in a smoky whirlwind, inflicting $106827s1% weapon damage every $106826t1 sec. and reducing the critical strike chance of affected targets by $106827s2%. Abilities and spells used by the afflicted targets reduce the duration of this effect by 5 seconds. Afflicted targets gain Parting Smoke when this effect is removed."},
			{id=6574,title="Parting Smoke",body="The curtain of smoke parts, briefly revealing a weak point on the Sha of Violence. The player's next attack or spell used within $127576d will critically strike for $127576s2% more damage than usual."},
			{id=5812,title="Sha Spike",body="The Sha summons an erupting spike at the location of a random player, inflicting $106827s1 Shadow damage and knocking targets back. As the spike returns to the ground, a Volatile Energy emerges to attack the caster's enemies for $106827d."},
			{id=5813,title="Enrage",body="The Sha enrages at low health, increasing its attack speed by $38166s1% for $38166d."},
		},
	},
	[686]={
		encounterID=686,
		instanceID=312,
		order=4,
		name="Taran Zhu",
		lore="The Sha of Hatred has tainted Taran Zhu, the Shado-Pan's pragmatic and mighty leader. Once devoted to protecting his beloved home, Zhu now burns with seething hatred for all life, twisting his perception of everything--and everyone--around him.",
		dungeonEncounterID=1306,
		uiMapID=443,
		pin={x=0.7212,y=0.475},
		difficultyIDs={1,2,8,24},
		npcIDs={56884},
		displayIDs={41121},
		loot={
			{itemID=143990,diffs={1,2,24},faction=-1},
			{itemID=143962,diffs={1,2,24},faction=-1},
			{itemID=143981,diffs={1,2,24},faction=-1},
			{itemID=143986,diffs={1,2,24},faction=-1},
			{itemID=143979,diffs={1,2,24},faction=-1},
			{itemID=144103,diffs={1,2,24},faction=-1},
			{itemID=144133,diffs={1,2,24},faction=-1},
			{itemID=144109,diffs={1,2,24},faction=-1},
			{itemID=144132,diffs={1,2,24},faction=-1},
			{itemID=144108,diffs={1,2,24},faction=-1},
			{itemID=144215,diffs={1,2,24},faction=-1},
		},
		sections={
			{id=5827,title="Hatred",body="The Sha of Hatred possessing Taran Zhu touches the minds of the players. Their hatred grows over time and further increases if any of Taran's attacks strike them. The Sha of Hatred afflicts the players that reach full hatred with Haze of Hate and they must Meditate to remove the effect."},
			{id=5828,title="Haze of Hate",body="Hatred overwhelms you. Although your Physical damage is increased by $107087s1%, your chance to hit is reduced by $107087s2% and your healing done is reduced by $107087s3%."},
			{id=5829,title="Meditate",body="Meditate to clear your mind of the Haze of Hate. You cannot move or act while meditating."},
			{id=5814,title="Rising Hate",body="Taran Zhu projects Sha energy at several targets, inflicting $107357s1 Shadow damage."},
			{id=5830,title="Ring of Malice",body="Taran Zhu surrounds himself with a ring of shadows for $131521d. The ring inflicts $131522s1 damage every $131521t1 sec. to enemies it touches. The Ring of Malice also reduces the caster's movement by $131521s3%."},
			{id=5815,title="Sha Blast",body="Taran Zhu inflicts $114999s1 Shadow damage to his current target, and knocking it back. Taran Zhu may only use this ability while Ring of Malice is active."},
			{id=5817,title="Gripping Hatred",body="Taran Zhu summons a powerful manifestation of hatred near him that pulls players toward and poisons the ground beneath it."},
			{id=5816,title="Grip of Hate",body="The Gripping Hatred harnesses the unholy energy that surrounds and binds all matter, drawing enemy targets within $115010A1 yards toward it."},
			{id=5832,title="Pool of Shadows",body="Shadows pool on the ground around the Gripping Hatred, inflicting $112918s1 Shadow damage every $112929t1 sec. to nearby enemies."},
		},
	},
	[687]={
		encounterID=687,
		instanceID=317,
		order=4,
		name="The Spirit Kings",
		lore="Ancient records tell of these legendary rulers, powerful mogu who carved an empire from the very rock of Pandaria. Their names still cause the land to tremble: Zian of the Endless Shadow, Meng the Demented, Qiang the Merciless, and Subetai the Swift. Some say their spirits lurk in the vaults, lost in ghostly memories of battle and glory.",
