		sections={
			{id=5871,title="Spirit Bolt",body="Feng the Accursed unleashes a volley of Spirit Bolts, inflicting $118530s1 Shadow damage to 3 random players.$[!4,6\n\nIn 25 Player and 25 Player Heroic Difficulty, Feng the Accursed hits 8 random players with Spirit Bolts.$]"},
			{id=5890,title="Strength of Spirit",body="Every time Feng absorbs a Mogu Champion Spirit, his damage dealt increases by $116363s1% for the remainder of the encounter.",difficultyIDs={5,6}},
			{id=5873,title="Essence of the Mogu Champions",body="Around 95%, 66%, and 33% remaining life, Feng siphons the essence out of a pre-selected statue of Mogu Champions past, gaining their boon. $[!5,6\n\nIn Heroic Difficulty, Feng siphons from the statue nearest to him around 100%, 75%, 50%, and 25%.$]"},
			{id=5874,title="Spirit of the Fist"},
			{id=6694,title="Lightning Lash",body="Feng's lightning charged fists zap his current target, inflicting normal damage as Nature plus $131788s1 Nature damage every $131788t1 sec for $131788d."},
			{id=5875,title="Lightning Fists",body="Feng slams a lightning-charged fist into the ground, causing a shockwave to pulse in front of him. The shockwave inflicts $116374s1 Nature damage and stuns those caught in its path.",difficultyIDs={3,4,7}},
			{id=6625,title="Lightning Fists",body="Feng slams a lightning-charged fist into the ground, inflicting $116295s3 Nature damage and causing three shockwaves to pulse in front of him. The shockwave inflicts $116374s1 Nature damage and stuns those caught in its path.",difficultyIDs={5,6}},
			{id=5876,title="Epicenter",body="Feng channels a violent earthquake that inflicts Nature damage. The quake inflicts more damage towards its epicenter, and reduces players' chance to hit by $116040s2%."},
			{id=5879,title="Spirit of the Spear"},
			{id=5885,title="Flaming Spear",body="Feng's fiery spear sears the flesh of his current target, inflicting $116942s2% of his normal melee attack as Fire damage. The fire then inflicts an additional $116942s1 Fire damage every $116942t1 sec. for $116942d."},
			{id=5886,title="Wildfire Spark",body="Feng the Accursed targets a random player then engulfs them with a Wildfire Spark. The Spark explodes after $116784t1 seconds, igniting a Wildfire at their location. The Wildfire then spreads out and inflicts $116973s1 Fire damage every $116717t1 sec. to any player standing within the fire."},
			{id=5887,title="Draw Flame",body="Feng attempts to absorb the Wildfire and cause his melee swings to inflict $116816s1 additional Fire damage to all enemies."},
			{id=5880,title="Spirit of the Staff"},
			{id=6695,title="Arcane Shock",body="Feng's arcane-infused staff shocks his current target, inflicting normal damage as Arcane plus $131790s1 Arcane damage every $131790t1 sec for $131790d."},
			{id=5888,title="Arcane Velocity",body="Feng channels an Arcane storm, inflicting $116365s1 Arcane damage every $116364t1 sec. to all enemies. The bolts from the storm inflict increasing damage to targets as they stand further away from Feng."},
			{id=5889,title="Arcane Resonance",body="Feng charges random players with Arcane Resonance, inflicting $116434s1 Arcane damage to the target's nearby allies within $116434A1 yards. Each additional affected player amplifies the damage done to them all by $116434s1."},
			{id=5877,title="Spirit of the Shield",difficultyIDs={5,6}},
			{id=6696,title="Shadowburn",body="Feng burns his current target's soul, inflicting normal damage as Shadow plus $131792s1 Shadow damage every $131792t1 sec for $131792d.",difficultyIDs={5,6}},
			{id=5884,title="Siphoning Shield",body="Feng's cursed shield draws the souls of 10 random enemies to it, healing him for $118071s2% of his life per absorbed soul.",difficultyIDs={6}},
			{id=5891,title="Siphoning Shield",body="Feng's cursed shield draws the souls of 5 random enemies to it, healing him for $118071s3% of his life per absorbed soul.",difficultyIDs={5}},
			{id=5892,title="Chains of Shadow",body="Feng strikes a random player with a Chain of Shadow that arcs to another nearby player. The Chain affects up to $118783x1 targets, inflicting diminishing Shadow damage to each successive target.",difficultyIDs={5,6}},
			{id=5881,title="Stolen Essences of Stone",body="Players assuming the tank role gain access to the leftover essence shards from the awakened statues."},
			{id=5882,title="Nullification Barrier",body="Players with this Stolen Essence of Stone may channel a Nullification Barrier around themselves for $115817d. The Barrier negates any harmful magical effects cast on players standing inside the Barrier.\n\nThe barrier will also nullify harmful effects in the world such as Wildfire and Lightning Charge.",difficultyIDs={3,4,7}},
			{id=6718,title="Nullification Barrier",body="Players with this Stolen Essence of Stone may channel a Nullification Barrier around themselves for $115817d. The Barrier negates any harmful magical effects cast on players standing inside the Barrier.\n\nThe barrier will also nullify harmful effects in the world such as Wildfire, Shadow Shields or Images, and Lightning Charge.",difficultyIDs={5,6}},
			{id=5883,title="Shroud of Reversal",body="A player with this Stolen Essence of Stone may extend a Shroud of Reversal around an ally, allowing the player to mimic the effects of the next harmful ability that strikes the ally."},
		},
	},
	[690]={
		encounterID=690,
		instanceID=321,
		order=2,
		name="Gekkan",
		lore="As the mogu clans battle for supremacy, the cunning Gekkan leads his fearsome saurok raiding party into the palace's fabled treasure caches. Loyalty is not usually ascribed to these ruthless reptilian beings, but Gekkan's courage and tactical brilliance inspire a sense of honor in his soldiers.",
		dungeonEncounterID=2129,
		uiMapID=454,
		pin={x=0.4479,y=0.7591},
		difficultyIDs={1,2,8,24},
		npcIDs={61243},
		displayIDs={41920},
		loot={
			{itemID=143992,diffs={1,2,24},faction=-1},
			{itemID=144147,diffs={1,2,24},faction=-1},
			{itemID=144149,diffs={1,2,24},faction=-1},
			{itemID=144148,diffs={1,2,24},faction=-1},
			{itemID=144146,diffs={1,2,24},faction=-1},
		},
		sections={
			{id=5911,title="Reckless Inspiration",body="Gekkan inspires one of his subordinates, increasing haste by $118988s2% and rendering them immune to long duration crowd control effects, but also increasing damage taken by $118988s3%. This effect stacks.\n\nIn addition, whenever a member of Gekkan's entourage dies, Gekkan will cast Reckless Inspiration on himself."},
			{id=5917,title="Inspiring Cry",body="On death, Gekkan utters a final rallying cry, granting Reckless Inspiration to all remaining members of his entourage."},
			{id=5915,title="Gekkan's Entourage",body="Gekkan always travels with four Saurok trained in different styles of combat."},
			{id=5918,title="Glintrok Ironhide"},
			{id=5919,title="Iron Protector",body="The Glintrok Ironhide's Iron Protector reduces the damage taken by allies within $118960A1 yards by $118960s1%."},
			{id=5920,title="Glintrok Skulker"},
			{id=5921,title="Shank",body="The Glintrok Skulker shanks a player, inflicting $118963s1% weapon damage and stunning the target for $118963d."},
			{id=5922,title="Glintrok Oracle"},
			{id=5923,title="Cleansing Flame",body="The Glintrok Oracle's Cleansing Flame heals all allies within $118940A1 yards for $118940s1."},
			{id=6492,title="Fire Bolt",body="The Glintrok Oracle unleashes a Fire Bolt at his current target, inflicting damage equivalent to its melee swing as Fire damage."},
			{id=5924,title="Glintrok Hexxer"},
			{id=5925,title="Hex of Lethargy",body="The Glintrok Hexxer hexes the target, inflicting $118903s1 Shadow damage and reducing spell casting speed by $118903s2% for $118903d. Stacks up to $118903U times."},
			{id=6491,title="Dark Bolt",body="The Glintrok Hexxer unleashes a Dark Bolt at his current target, inflicting damage equivalent to its melee swing as Shadow damage."},
		},
	},
