		sections={
			{id=5937,title="Seethe",body="The Sha of Anger projects seething anger at his current target if no players stand within his melee attack range. Seethe inflicts $119487s1 Shadow damage and increases Shadow damage taken by the player by $119487s2% for $119487d."},
			{id=5938,title="Endless Rage",body="The anger brought by the Alliance and Horde to Pandaria flows through the Sha of Anger, erupting forth as a shower of Sha energy. Each missile inflicts $119446s2 Shadow damage to players within $119446a2 yards of the impact point and summons forth an Ire and a cloud of Bitter Thoughts."},
			{id=5940,title="Ire",body="A manifestation of anger summoned by the Sha of Anger's Endless Rage."},
			{id=5939,title="Bitter Thoughts",body="The cloud of Bitter Thoughts prevents all players within $119610A1 yards from either attacking or casting spells. The cloud persists for $119446d."},
			{id=5941,title="Stage One: Growing Anger",body="The Sha of Anger's rage grows over 50 seconds."},
			{id=5942,title="Growing Anger",body="The Sha of Anger infects $119622s1 players with angry thoughts. After $119622d, infected players display Aggressive Behavior."},
			{id=5943,title="Aggressive Behavior",body="The affected player erupts with anger, causing the player and all allies within $119626A1 yards to fall under the control of the Sha of Anger for $119626d. Increases damage dealt by $119626s2% and maximum health by $119626s4%. Aggressive Behavior is removed if the player falls below $119626s6% remaining health."},
			{id=5944,title="Stage Two: Unleashed Wrath",body="Upon reaching 100 rage, the Sha of Anger unleashes its wrath upon its enemies. This phase lasts until the Sha of Anger's rage reaches 0."},
			{id=5945,title="Unleashed Wrath",body="The Sha of Anger unleashes pent-up rage for $119488d. The Unleashed Wrath inflicts $119489s1 Shadow damage to $119488s1 random targets every $119488t1 seconds."},
		},
	},
	[692]={
		encounterID=692,
		instanceID=324,
		order=3,
		name="General Pa'valak",
		lore="The pragmatic General Pa'valak does not fear the pandaren or their allies, and he does not differentiate between using his own might and that of his mantid armies to defeat his enemies. Victory is the only honor he seeks, and Pa'valak will not tolerate failure should his minions fall short of their goal.",
		dungeonEncounterID=1447,
		uiMapID=457,
		pin={x=0.5531,y=0.4628},
		difficultyIDs={1,2,8},
		npcIDs={61485},
		displayIDs={43120},
		loot={
			{itemID=144167,diffs={1,2,24},faction=-1},
			{itemID=144168,diffs={1,2,24},faction=-1},
			{itemID=144169,diffs={1,2,24},faction=-1},
			{itemID=144170,diffs={1,2,24},faction=-1},
