			{itemID=100963,diffs={},faction=-1},
			{itemID=100964,diffs={},faction=-1},
		},
		sections={
			{id=5955,title="Blade Rush",body="General Pa'valak throws his sword at a random player's location, inflicting $124290s1 Physical damage to all players within $124290A1 yards on impact. Once the sword lands General Pa'valak then charges to it, inflicting $124317s1 Physical damage to all players within $124317A1 yards and knocking them back."},
			{id=5956,title="Tempest",body="General Pa'valak unleashes a tempest, inflicting $119875s1 Nature damage to all players within $119875A1 yards and negating the next $119875s2 points of healing on the target."},
			{id=5946,title="Call Reinforcements",body="When General Pa'valak reaches 65% and 35% remaining health, he shields himself in a Bulwark and summons reinforcements."},
			{id=5947,title="Bulwark",body="General Pa'valak surrounds himself in a shield, absorbing $119476s1 damage."},
			{id=5948,title="Aerial Bombardment",body="General Pa'valak summons Sik'thik Amber-Sappers to bomb players."},
			{id=5949,title="Siege Explosive",body="Sik'thik Amber-Sappers drop Siege Explosives that arm themselves after 3 seconds. Then after an additional 3 seconds pass they explode for $119703s1 Fire damage in a $119703A1 yard radius. The explosion causes players to take $119703s2% additional damage for $119703d. This effect stacks."},
			{id=5950,title="Throw Explosive",body="Players may attempt to throw Siege Explosives back at enemy Mantid before they arm. Thrown Explosives inflict $119395s1 Fire damage to all Mantid within $119395A1 yards of the targeted area and increase their damage taken by $119395s2% for $119395d. This effect stacks."},
			{id=5951,title="Ground Assault",body="General Pa'valak summons waves of Sik'thik Soldiers to defend him in battle."},
			{id=5952,title="Sik'thik Soldier"},
			{id=5953,title="Serrated Blade",body="Sik'thik Soldiers slice a player, inflicting $119840s1 Physical damage every $119840t1 seconds for $119840d. This effect stacks."},
		},
	},
