			{id=5957,title="Sap Puddle",body="The Sap Puddle grows over time, inflicting $119941s1 Nature damage over $119941t1 sec to enemies who touch it. Touching the Sap Puddle also causes it to shrink in size."},
			{id=5960,title="Sap Residue",body="When a player touches the Sap Puddle, it causes the Residue to attach to them. Sap Residue inflicts $119941s1 Nature damage over $119941t1 sec. The effect stacks."},
			{id=5958,title="Summon Sap Globule",body="Vizier Jin'bak summons three Sap Globules from the tree."},
			{id=6494,title="Sap Globule",body="Sap Globules try to congeal with the Sap Puddle, increasing its size."},
			{id=5959,title="Detonate",body="Vizier Jin'bak attempts to detonate the Sap Puddle, inflicting damage based on the size of the Sap Puddle."},
		},
	},
	[698]={
