		sections={
			{id=5970,title="Ground Slam",body="Xin slams the ground in front of him, inflicting $119684s2 Physical damage and decreasing the armor of enemies in a $119684A1 yard cone in front of him by $119684s1% for $119684d. This effect stacks."},
			{id=5973,title="Circle of Flame",body="Xin animates a staff from his arsenal. The staff circles a random enemy in flame, detonating once the circle completes. The explosion inflicts $119590s1 Fire damage and knocks enemies into the air."},
			{id=6236,title="Inciting Roar",body="Xin cries out a bellowing roar, activating the arsenal of his choice and inflicting $122959s1 damage to all enemies."},
			{id=5971,title="Whirlwinding Axes",body="Xin animates the axes in his arsenal. These axes inflict $119374s1 Physical damage to enemies within $119374A1 yards, knocking them back."},
			{id=5972,title="Blade Trap",body="At 66% remaining health, Xin activates his sword traps. The stream of blades inflict $119311s1 Physical damage every $119315t1 sec. to those caught in the path."},
			{id=5974,title="Death From Above!",body="At 33% remaining health, Xin activates every last weapon in his arsenal. The mounted crossbows on the wall inflict $120142s1 Physical damage on a random player every $120143t1 sec."},
