	[708]={
		encounterID=708,
		instanceID=321,
		order=0,
		name="Trial of the King",
		lore="Ming the Cunning, Kuai the Brute, and Haiyan the Unstoppable have journeyed to the palace with their clans, vying to prove their worth to their king. Yet these mogu factions are plagued with bitter rivalries. Violence threatens to flood the palatial grounds unless the bickering clans can find a way to test their strength without coming to blows with one another.",
		dungeonEncounterID=1442,
		uiMapID=453,
		pin={x=0.4019,y=0.7043},
		difficultyIDs={1,2,8,24},
		npcIDs={61442,61444,61445},
		displayIDs={42058,42059,42060},
		loot={
			{itemID=144020,diffs={1,2,24},faction=-1},
			{itemID=144021,diffs={1,2,24},faction=-1},
			{itemID=144145,diffs={1,2,24},faction=-1},
			{itemID=144143,diffs={1,2,24},faction=-1},
			{itemID=144144,diffs={1,2,24},faction=-1},
		},
		sections={
			{id=6015,title="Kuai the Brute",body="Clan Gurthan favors the use of fist weapons and prizes their Quilen companions."},
			{id=6016,title="Mu'Shiba",body="Mu'Shiba is Kuai the Brute's loyal companion and ceases fighting after the players defeat his master."},
			{id=6017,title="Ravage",body="Mu'Shiba tackles a random player to the ground then Ravages them. Ravage inflicts $119949m1 Physical damage every second for $119948d. Defeating Mu'Shiba ends this effect early."},
			{id=6018,title="Shockwave",body="Kuai the Brute sends a shockwave along the ground in front of him. The shockwave launches any player hit into the air. Players suffer Physical damage based on how far they fall."},
			{id=6019,title="Ming the Cunning",body="The Harthak are masters of wind and lightning based magic."},
			{id=6020,title="Whirling Dervish",body="Ming the Cunning summons a Whirling Dervish that randomly moves around the arena, inflicting $120087m1 Nature damage and knocking back all players in its path."},
			{id=6021,title="Magnetic Field",body="Ming the Cunning rapidly spins in place, creating a Magnetic Field that pulls nearby creatures into its vortex. Creatures in the vortex suffer $120101m1 Nature damage every $120100t2 sec."},
			{id=6022,title="Lightning Bolt",body="Ming the Cunning inflicts $123654m1 Nature damage to his current target."},
			{id=6023,title="Haiyan the Unstoppable",body="The Kargesh are strong warriors who favor large weapons and fire magic."},
			{id=6024,title="Conflagrate",body="Haiyan the Unstoppable lights a random player on fire in a huge gout of flame. The Conflagration inflicts $120201m1 Fire damage every $120201t1 sec and disorients the victim. When Conflagrate ends, the flames jump to any nearby creature."},
			{id=6025,title="Meteor",body="Haiyan the Unstoppable hurls a fiery boulder at a random player. When the meteor lands, it inflicts $120196m1 Fire damage in a $120196A1 yard radius divided evenly among all players in the area of effect."},
			{id=6026,title="Traumatic Blow",body="Haiyan the Unstoppable inflicts $123655m1% of his weapon damage as Physical damage to his current target. The victim receives $123655m2% less healing for the next $123655d."},
		},
	},
	[709]={
		encounterID=709,
		instanceID=320,
		order=4,
		name="Sha of Fear",
		lore="The Sha of Fear is the physical manifestation of terror in Pandaria. Imprisoned by the legendary pandaren emperor Shaohao long ago, the entity has been newly strengthened by rising conflict across the island.",
		dungeonEncounterID=1431,
		uiMapID=456,
		pin={x=0.3085,y=0.4932},
		difficultyIDs={3,4,5,6,7},
		npcIDs={60999},
		displayIDs={45065},
		loot={
