	[726]={
		encounterID=726,
		instanceID=317,
		order=5,
		name="Elegon",
		lore="Dedicated to the advancement of their empire, the mogu salvaged and repurposed titan technology to generate untold power in the depths of this ancient complex. Why these energies have been focused into the cold will of a celestial dragon is a mystery that lies at the very heart of the vaults.",
		dungeonEncounterID=1500,
		uiMapID=473,
		pin={x=0.207,y=0.5115},
		difficultyIDs={3,4,5,6,7},
		npcIDs={60410},
		displayIDs={41399},
		loot={
			{itemID=86130,diffs={3,4},faction=-1},
