		sections={
			{id=6171,title="Energy Vortex",body="An active Energy Vortex transforms any player or creature who stands in it, granting a small taste of the Titan's true power. $[!5,6\n\nIn Heroic Difficulty, the Energy Vortex prevents targeting into or out of the Energy Vortex.$]"},
			{id=6172,title="Touch of the Titans",body="Contact with the Energy Vortex transforms the target into celestial form, increasing all damage done by $117870s1% and healing received by $117870s2%."},
			{id=6173,title="Overcharged",body="The Energy Vortex periodically inflicts players with Overcharge, causing them to take $117878s1% additional damage. This effect stacks.",difficultyIDs={3,4,5,6}},
			{id=6174,title="Stage One: Entering Defensive Mode",body="Elegon activates the Energy Vortex, attacking with Celestial Breath and calling for Celestial Protectors to help defend the Engine of Nalak'sha.\n\nStage One ends at 85% and 50% remaining health."},
			{id=6184,title="Celestial Breath",body="Elegon's breath inflicts $124947s1 Arcane damage every $117960t1 seconds for $117960d to players within a $124947a1 yard long 60 degree cone."},
			{id=6177,title="Materialize Protector",body="When Elegon has more than 50% remaining health, he summons a Celestial Protector to attack the players."},
			{id=6178,title="Celestial Protector",body="A construct of pure energy, the Celestial Protector serves as primary defense for the Engine of Nalak'sha."},
			{id=6179,title="Phasing",body="The Celestial Protector exists in a state of flux, held together by the immense power of the Energy Vortex. When the Protector has over 25% remaining health and exists outside the bounds of the Energy Vortex, players inflict 90% less damage to it."},
			{id=6182,title="Arcing Energy",body="The Celestial Protector inflicts $117945s1 Arcane damage to two random players and applies Closed Circuit to each target.$[!2,4\n\nIn 25 player Difficulty, Arcing Energy targets five random players.$]$[!5\n\nIn 10 player Heroic Difficulty, Arcing Energy targets three random players.$]$[!6\n\nIn 25 player Heroic Difficulty, Arcing Energy targets seven random players.$]$[!7\n\nIn Looking for Raid Difficulty, Arcing Energy targets four random players.$]"},
			{id=6183,title="Closed Circuit",body="After being hit by the Arcing Energy, the Closed Circuit reduces the healing received by the target by $117949s1% for $117949d."},
			{id=6185,title="Stability Flux",body="Upon reaching 25% remaining health, the Celestial Protector begins to pulse energy and periodically inflicts $117912s1 Arcane damage on all players."},
			{id=6186,title="Total Annihilation",body="Celestial Protectors explode when near death, inflicting $117914s1 Arcane damage to all players. $[!5\n\nIn Heroic Difficulty, Total Annihilation also applies Destabilizing Energies.\n\nIn Heroic Difficulty, Total Annihilation will trigger Catastrophic Anomaly if it hits no targets.$]$[!6\n\nIn Heroic Difficulty, Total Annihilation also applies Destabilizing Energies.\n\nIn 25 player Heroic Difficulty, Total Annihilation will trigger Catastrophic Anomaly if it hits fewer than three targets.$]"},
			{id=6715,title="Destabilizing Energies",body="Exposure to Total Annihilation causes lasting negative effects, stuns the enemy and inflicts $132222s1 Arcane damage every $132222t1 seconds until the target is healed to 80% of max health.",difficultyIDs={5,6}},
			{id=6716,title="Destabilized",body="When struck by Total Annihilation, powerful waves of energy course through the victim, rendering them more susceptible to the harmful effects of Total Annihilation. Players instantly die if Total Annihilation inflicts additional damage to them.",difficultyIDs={5,6}},
			{id=6564,title="Catastrophic Anomaly",body="With no targets to absorb the excess energy of Total Annihilation, the Engine of Nalak'sha explodes, inflicting $127341s1 Arcane damage to the entire raid.",difficultyIDs={5,6}},
			{id=6565,title="Grasping Energy Tendrils",body="With no targets in melee range, Elegon grabs and pulls all enemies to him, inflicting $127362s2 Arcane damage."},
			{id=6192,title="Radiating Energies",body="When Elegon reaches 50% remaining health, he becomes dangerously unstable. Elegon periodically inflicts $122741s1 Arcane damage to all players who are within the Energy Vortex, and $118313s1 Arcane damage to all players who are outside it."},
			{id=6175,title="Stage Two: Primary Power Offline",body="Elegon attempts to reactivate the Engine of Nalak'sha by creating Energy Charges to energize the Empyreal Focuses. If players destroy all Energy Charges in a wave, Elegon will continue to create more Energy Charges. The creation process permanently weakens his physical form.\n\nStage Two ends once an Energy Charge leaves the Energy Vortex."},
			{id=6187,title="Draw Power",body="Elegon attempts to restart the Engine of Nalak'sha by constructing six Energy Charges from his own body, permanently increasing all damage taken by $119387s1%. This effect stacks."},
			{id=6189,title="Energy Charge",body="A small part of Elegon himself, the Energy Charge contains enough Arcane energy to restart The Engine of Nalak'sha."},
			{id=6191,title="High Energy",body="With each successive cast of Draw Power, the created Energy Charge gains an additional $118118m1% movement speed. This effect stacks."},
			{id=6190,title="Discharge",body="Upon reaching zero health, the Energy Charge explodes and inflicts $118299s1 Arcane damage to all players."},
			{id=6176,title="Stage Three: Power Draw Stable",body="Elegon has reactivated The Engine of Nalak'sha, disabling the Energy Vortex and activating all Empyreal Focuses. Elegon shields himself from all damage.\n\nStage Three ends once players destroy all the Empyreal Focuses."},
			{id=6193,title="Empyreal Focus",body="The Focuses activate whenever the Engine of Nalak'sha begins operation, venting energy into the surrounding platform. Damaging all six Empyreal Focuses temporarily disables the Engine of Nalak'sha."},
			{id=6194,title="Energy Conduit",body="The Empyreal Focus vents excess energy, inflicting $116661m1 Arcane damage to all players touching the energy conduit every $116663t sec."},
			{id=6195,title="Overloaded",body="Upon reaching zero health, the Empyreal Focus deactivates and vents excess energy back to Elegon, increasing his damage inflicted by $117204m1% and casting speed by $117204m2%. This effect stacks."},
			{id=6717,title="Linked Focuses",body="An Empyreal Focus will not deactivate until both it and the linked focus are brought to zero health.",difficultyIDs={3,4,5,6}},
			{id=6196,title="Unstable Energy",body="Elegon periodically inflicts $116997s1 Arcane damage to all players."},
			{id=6197,title="Energy Cascade",body="Elegon fires a ball of Titan plasma at the location of random player, inflicting $119722s1 Arcane damage on impact to players within $119722a1 yards and creating a Cosmic Spark."},
			{id=6198,title="Cosmic Spark",body="Small pure energy constructs created by Elegon."},
		},
	},
