		sections={
			{id=6493,title="Afraid",body="Lei Shi grows more afraid as players hurt her. She gains $123181m1% casting speed for each $123181M1 percent of her total health lost."},
			{id=6220,title="Spray",body="Lei Shi casts Spray instead of using melee attacks. Spray causes water to burst from the ground at a player's feet, inflicting $123121s1 Frost damage to all players within 2.5 yards and increasing their Frost damage taken by $123121s2% for $123121d."},
			{id=6221,title="Hide",body="Lei Shi hides from players. Players cannot target her while hiding, but area of effect attacks and spells can still hit her. Lei Shi reveals herself after the players strike her enough times."},
			{id=6222,title="Get Away!",body="Lei Shi channels, releasing sha energy that pushes players away and inflicts $123467s1 periodic Shadow damage. Players who fight the current take half damage. Lei Shi channels for $123461d or until players inflict $123461s1% of her maximum health in damage."},
			{id=6223,title="Protect",body="At 80%, 60%, 40%, and 20% health remaining, Lei surrounds herself with an impenetrable bubble and animates several elementals to protect her. She maintains the bubble until players defeat one of her Animated Protectors."},
			{id=6224,title="Animated Protector",body="When Lei Shi casts Protect, she animates these elementals from the bracers scattered throughout the area. The elementals turn back into water and fall to the ground when the effect ends."},
			{id=6225,title="Scary Fog",body="Sha energy coalesces around several players, inflicting $123705s1 Shadow damage every $123705t1 sec. for $123705d. In addition, players and enemies near an afflicted player take $123712s1% more damage from all sources. This effect stacks. A target may only be afflicted by one Scary Fog at a time.",difficultyIDs={5,6}},
		},
	},
	[737]={
		encounterID=737,
		instanceID=330,
		order=5,
		name="Amber-Shaper Un'sok",
		lore="Eager to please his empress, Un'sok has produced several innovative concoctions. Yet this brilliant young alchemist's proximity to the mantid queen has allowed the sha's negative energies to take root in his mind. Now, Un'sok's overwhelming fear of failure drives him to create increasingly deadlier weapons.",
		dungeonEncounterID=1499,
		uiMapID=475,
		pin={x=0.4411,y=0.7368},
		difficultyIDs={3,4,5,6,7},
		npcIDs={62511},
		displayIDs={43126,44140},
		loot={
			{itemID=86210,diffs={3,4},faction=-1},
			{itemID=86211,diffs={3,4},faction=-1},
			{itemID=86212,diffs={3,4},faction=-1},
			{itemID=86213,diffs={3,4},faction=-1},
			{itemID=86214,diffs={3,4},faction=-1},
			{itemID=86217,diffs={3,4},faction=-1},
			{itemID=89243,diffs={3,4},faction=-1},
			{itemID=86219,diffs={3,4},faction=-1},
			{itemID=89244,diffs={3,4},faction=-1},
			{itemID=89245,diffs={3,4},faction=-1},
			{itemID=89252,diffs={5,6},faction=-1},
			{itemID=86981,diffs={5,6},faction=-1},
			{itemID=89253,diffs={5,6},faction=-1},
			{itemID=86982,diffs={5,6},faction=-1},
			{itemID=89254,diffs={5,6},faction=-1},
			{itemID=86983,diffs={5,6},faction=-1},
			{itemID=86984,diffs={5,6},faction=-1},
			{itemID=86857,diffs={7},faction=-1},
			{itemID=86985,diffs={5,6},faction=-1},
			{itemID=86858,diffs={7},faction=-1},
			{itemID=86986,diffs={5,6},faction=-1},
			{itemID=86859,diffs={7},faction=-1},
			{itemID=86987,diffs={5,6},faction=-1},
			{itemID=86860,diffs={7},faction=-1},
			{itemID=86861,diffs={7},faction=-1},
			{itemID=86862,diffs={7},faction=-1},
			{itemID=86863,diffs={7},faction=-1},
