		sections={
			{id=6328,title="Whirling Blade",body="Wind Lord Mel'jarak hurls his blade at a random player's location, inflicting $121898s1 Physical damage to all players in the blade's path. After the blade reaches its destination, it returns to Wind Lord Mel'jarak. The blade also inflicts $121898s1 Physical damage to all players in its return path."},
			{id=6329,title="Rain of Blades",body="Wind Lord Mel'jarak rains blades down on all players, inflicting $122407s1 Physical damage every $122406t1 seconds for $122406d."},
			{id=6697,title="Wind Bomb",body="When Wind Lord Mel'jarak reaches 75% health remaining, he will begin to hurl a Wind Bomb at a random player's location. When the bomb lands, it inflicts $131830s1 Nature damage to all players within $131830A1 yards. After 3 seconds, the bomb arms itself and will explode for $131842s1 Nature damage in a $131842A1 yard radius if any player comes within $131836A1 yards of it. \n\nAn active Wind Bomb persists for the duration of the encounter or until it detonates."},
			{id=6344,title="Watchful Eye",body="Wind Lord Mel'jarak watches over his swarm, dispelling all forms of crowd control from every warrior if he ever senses that players are incapacitating more than four.\n\nWhen one group of Wind Lord Mel'jarak's swarm falls, he becomes more watchful. He now dispels all forms of crowd control from every warrior if he ever senses players are incapacitating more than two.\n\nWhen a second group of Wind Lord Mel'jarak's swarm falls, he becomes even more watchful, dispelling all forms of crowd control from every warrior if he ever senses players are incapacitating any.$[!5,6\n\nIn Heroic Difficulty, Wind Lord Mel'jarak does not become more watchful and only dispels crowd control effects if players incapacitate more than three warriors.$]"},
			{id=6554,title="Reinforcements",body="When a group of Wind Lord Mel'jarak's swarm falls, he calls for a new group of warriors to replace them. He calls for these reinforcements 45 seconds after a group falls.",difficultyIDs={5,6}},
			{id=6331,title="Recklessness",body="When Wind Lord Mel'jarak sees a group of his warriors fall in battle, he becomes reckless for the remainder of the fight. This increases his damage dealt by $122354s1% and damage taken by $122354s2%. This effect stacks.",difficultyIDs={3,4,7}},
			{id=6555,title="Recklessness",body="When Wind Lord Mel'jarak sees a group of his warriors fall in battle, he becomes reckless for $125873d. This increases his damage dealt by $125873s1% and his damage taken by $125873s2%.",difficultyIDs={5,6}},
			{id=6299,title="The Swarm",body="Wind Lord Mel'jarak fights alongside his most trusted warriors."},
			{id=6332,title="Fate of the Swarm",body="Each group of Mel'jarak's swarm shares health with their fellow swarm members."},
			{id=6333,title="Impaling Spear",body="Up to four players can use the weapon racks left by the Mantid army to gain the Impaling Spear ability.\n\nImpaling Spear stuns a target for $122224d. Any damage dealt directly to the target by a player causes the target to break free."},
			{id=6300,title="Sra'thik Amber-Trapper"},
			{id=6301,title="Amber Prison",body="Sra'thik Amber-Trappers imprison a random player and their allies within $121874A1 yards in amber, stunning them until freed.\n\nPlayers can smash an Amber Prison and free the imprisoned allies inside by interacting with it. Residue afflicts players who destroy Amber Prisons.",difficultyIDs={3,4,5,6}},
			{id=6302,title="Residue",body="Residue prevents a player from destroying Amber Prisons for $122055d.",difficultyIDs={3,4,5,6}},
			{id=8683,title="Amber Prison",body="Sra'thik Amber-Trappers imprison a random player in amber, stunning them until freed.\n\nPlayers can smash an Amber Prison and free the imprisoned allies inside by interacting with it. Residue afflicts players who destroy Amber Prisons.",difficultyIDs={7}},
			{id=8684,title="Residue",body="Residue prevents a player from destroying Amber Prisons for $122055d.",difficultyIDs={7}},
			{id=6303,title="Corrosive Resin",body="Sra'thik Amber-Trappers cover a player in 5 stacks of Corrosive Resin for $122064d, inflicting $122064s1 Nature damage every second per stack. Moving while afflicted by Corrosive Resin removes a stack of Corrosive Resin and creates a Corrosive Resin Pool at the player's location."},
			{id=6304,title="Corrosive Resin Pool",body="Corrosive Resin Pools inflict $122125s1 Nature damage every second to all players within the pool."},
			{id=6305,title="Zar'thik Battle-Mender"},
			{id=6306,title="Mending",body="Zar'thik Battle-Menders mend their allies, healing a group of the swarm for $122147s1% of their maximum health."},
			{id=6307,title="Quickening",body="Zar'thik Battle-Menders quicken all of Mel'jarak's swarm, increasing all damage done and melee attack speed by $122149s1% for $122149d. This effect stacks."},
			{id=6334,title="Kor'thik Elite Blademaster"},
			{id=6335,title="Kor'thik Strike",body="Kor'thik Elite Blademasters focus a single player and strike them in unison, each inflicting $123962s1 Physical damage."},
		},
	},
