		sections={
			{id=6310,title="The Night",body="Tsulong struggles at Night with the Sha's corrupting influence. Bringing Tsulong's remaining health to zero while at Night permanently destroys the Sha's influence over him. When he reaches 100 energy, he temporarily purges the Sha's influence and radiant sunlight turns Night into Day."},
			{id=6311,title="Dread Shadows",body="The Dread Shadows created by the Sha within Tsulong inflict $122768s1 Shadow damage on all players and increases their Dread Shadows damage taken by $122768s2%. This effect stacks."},
			{id=6312,title="Nightmares",body="The Sha within Tsulong projects Nightmares at the location of a random player. The Nightmares inflict $122777s1 Shadow damage and fear players within $122777A1 yards of the impact for $122777d."},
			{id=6313,title="Shadow Breath",body="Tsulong expels out Sha energy in a 30 degree cone in front of him, inflicting $122752s1 Shadow damage and increasing Shadow damage taken by $122752s2% for $122752d. This effect stacks."},
			{id=6314,title="Sunbeam",body="Tsulong's attempts to resist the Sha allow him to protect the players from Dread Shadows. Tsulong summons a Sunbeam onto the battlefield, and the Sunbeam grants immunity to Dread Shadows for players standing within the beam. The protected area of the Sunbeam shrinks over time as more players stand within it."},
			{id=6550,title="The Dark of Night",body="The Dark of Night appears at a random location and moves towards the nearest Sunbeam. The Dark of Night extinguishes a Sunbeam upon reaching it.",difficultyIDs={5,6}},
			{id=6315,title="The Day",body="During the Day, Tsulong gains the upper hand over the Sha corruption. Players may heal and aid Tsulong during the Day, and bringing him to full health while in the Day permanently destroys the Sha's influence over him. When he reaches 100 energy, the Sha corrupts his emotions and Night descends upon the Terrace."},
			{id=6316,title="Embodied Terror",body="Embodied Terrors spawn as the Sha fights to control Tsulong. When players destroy an Embodied Terror, five Fright Spawns burst out."},
			{id=6317,title="Terrorize",body="The Embodied Terror casts Terrorize on both a random player and on Tsulong. The terror inflicts $123018s1% of the player's current health as Shadow damage every $123011t1 sec for $123011d. Tsulong suffers $123012s1% of his total health as Shadow damage every $123012t1 sec. for $123012d."},
			{id=6318,title="Fright Spawn",body="Five Fright Spawns appear when players destroy an Embodied Terror."},
			{id=6319,title="Fright",body="A Fright Spawn unleashes a wave of Fright, inflicting $123036s1 Shadow damage and fear on players within $123036A1 yards for $123036d."},
			{id=6320,title="Unstable Sha",body="Unstable Sha appear around Tsulong and then move towards him, inflicting massive Shadow damage to Tsulong if they reach him."},
			{id=6321,title="Unstable Bolt",body="The Unstable Sha unleashes shadowy energy at a random player, inflicting $122881s1 Shadow damage on the target. The Unstable Bolt also damages the Unstable Sha for $122907s1% of its maximum health."},
			{id=6322,title="Instability",body="If an Unstable Sha reaches Tsulong, it inflicts $123697s2 Shadow damage on Tsulong and disappears."},
			{id=6323,title="Sun Breath",body="Tsulong breathes out solar energy in a 60-degree cone in front of him, inflicting $122855s1 Nature damage to Sha within $122855A1 yards and stunning them for $122855d. The breath also places the Bathed in Light effect on players within its area."},
			{id=6324,title="Bathed in Light",body="The warmth of the Sun instantly restores $122858s2% of a player's total mana and increases their healing done by $122858s1% for $122858d."},
			{id=6551,title="The Light of Day",body="The Light of Day appears at a random location. Interacting with The Light of Day restores mana every $123716t1 sec. and increases healing done by $123716s2% for $123716d. The amount of mana restored increases while the healing done decreases over the duration of the effect.",difficultyIDs={5,6}},
		},
	},
	[743]={
		encounterID=743,
		instanceID=330,
		order=6,
		name="Grand Empress Shek'zeer",
		lore="The ancient Klaxxi order has come to a mournful decision: the tainted grand empress Shek'zeer must be deposed. Traditionally, mantid rulers are displaced in their old age by a carefully chosen successor. However, Shek'zeer's intended replacement is still too young and weak to unseat her, leaving the Klaxxi with no choice but to kill the current empress. If action is not taken against her soon, all of Pandaria may crumble before the mantid's ravenous swarms.",
		dungeonEncounterID=1501,
		uiMapID=475,
		pin={x=0.2679,y=0.7368},
		difficultyIDs={3,4,5,6,7},
		npcIDs={62837},
		displayIDs={42730},
		loot={
			{itemID=86226,diffs={3,4},faction=-1},
