		sections={
			{id=6336,title="Stage One: A Perilous Battle!"},
			{id=6325,title="Dissonance Field",body="The Empress creates a dissonance field which disrupts the sound associated with magic. The dissonance field absorbs nearby magical effects until it runs out of resonance. Once its resonance depletes, the field erupts in a Sonic Discharge.\n\nPlayers casting magical effects inside the dissonance field also deplete it of resonance."},
			{id=6326,title="Sonic Discharge",body="The Sonic Discharge inflicts $123504s1 Physical damage to all players."},
			{id=6666,title="Corrupted Dissonance Field",body="The Sha of Fear corrupts a dissonance field, causing it to inflict $130756s1 Shadow damage to random players until the dissonance field discharges.",difficultyIDs={5,6}},
			{id=6337,title="Eyes of the Empress",body="The Empress gazes deeply into the eyes of her current target, inflicting the target with the Eyes of the Empress effect. This effect stacks up to $123707s1 times. The Empress charms and transforms a player into a Servant of the Empress if the effect reaches maximum stacks."},
			{id=6544,title="Servant of the Empress",body="A player transformed and charmed by the Empress into her servant inflicts $123713s4% more damage and $123713s6% more healing, has $123713s5% increased health, and becomes immune to crowd control effects and snares."},
			{id=6338,title="Dread Screech",body="Grand Empress Shek'zeer lets loose a Dread Screech at two random players, inflicting $123743s1 Physical damage to each player and their nearby allies within $123743A1 yards.$[!4,6,7\n\nIn 25 Player raids, Shek'zeer looses a Dread Screech at five random players.$]"},
			{id=6339,title="Cry of Terror",body="The Empress incites terror on a random player, causing them to inflict $123792s1 Shadow damage to players every $123788t1 sec."},
			{id=6340,title="Stage Two: The Empress Retreats!",body="When the Empress runs out of sha energy, she retreats to her chrysalis and calls for her royal guard. Once she is fully recharged, or all of the Set'thik Windblades are defeated, the empress will emerge from her chamber."},
			{id=6545,title="Band of Valor",body="Members of the Empress' Royal Guard inflict $125422s1% more damage for every other member of the Royal Guard within $125419a1 yards."},
			{id=6478,title="Set'thik Windblade"},
			{id=6479,title="Fixate",body="The Set'thik Windblade fixates on a random player for $124070d."},
			{id=6481,title="Dispatch",body="The Set'thik Windblade periodically shoots blades at random players, inflicting $124080s1 Physical damage."},
			{id=6553,title="Sonic Blade",body="The Set'thik Windblade slashes his current target with a sonic blade, dealing $125886s1% weapon damage and interrupting spellcast."},
			{id=6482,title="Sticky Resin",body="The Set'thik Windblade coats the ground in a sticky resin which clings to players that pass through it, slowing their movement speed by $124097s1% and inflicting $124097s2 Nature damage every $124097t2 second. When resin comes into contact with other resin, it will slide off of the player and back onto the ground. \n\nAmassing enough amber resin into one area causes it to congeal and harden, forming an Amber Trap.",difficultyIDs={3,4,5,6}},
			{id=6552,title="Amber Trap",body="Being encased in amber deals $125822s2% of the encapsulated victim's health every $125822t2 seconds.",difficultyIDs={3,4,5,6}},
			{id=6480,title="Kor'thik Reaver"},
			{id=6483,title="Poison Bomb",body="The Kor'thik Reaver hurls poison bombs at random players, inflicting $124777s1 Nature damage initially and $124777s2 damage every $124777t2 seconds to a random enemy."},
			{id=6484,title="Toxic Slime",body="The Kor'thik Reaver inflicts $124807s2 Nature damage to players in a $124807A1 yard cone in front of it."},
			{id=6485,title="Poison-Drenched Armor",body="The poison-drenched blades of the Kor'thik Reaver seeps into every pore of his current enemy target, causing them to erupt with a toxic substance. The fumes from this poison cause the attacks of nearby friendly players to occasionally deal additional $124833s1 Nature damage."},
			{id=6341,title="Stage Three: Ultimate Corruption!",body="At 30% remaining health, the Sha of Fear breaks the Empress' chrysalis and imbues her with a profound corruption."},
			{id=6343,title="Eyes of the Empress",body="The Empress gazes deeply into the eyes of her current target, inflicting the target with the Eyes of the Empress effect. This effect stacks up to $123707s1 times. The Empress charms and transforms a player into a Servant of the Empress if the effect reaches maximum stacks."},
			{id=6546,title="Servant of the Empress",body="A player transformed and charmed by the Empress into her servant inflicts $123713s4% more damage and $123713s6% more healing, has $123713s5% increased health, and becomes immune to crowd control effects and snares."},
			{id=6547,title="Sha Energy",body="Grand Empress Shek'zeer emits Sha Energy at two random players, inflicting $125464s1 Shadow damage.$[!4,6,7\n\nIn 25 Player raids, Shek'zeer emits Sha Energy at five random players.$]"},
			{id=6486,title="Calamity",body="The Empress inflicts Shadow damage to each player equal to $124845s1% of their current health."},
			{id=6487,title="Consuming Terror",body="The Empress unleashes a Consuming Terror in a $124849A1 yard cone in front of her, inflicting $124849s1 Shadow damage and fearing players within the cone for $124849d."},
			{id=6719,title="Amassing Darkness",body="Grand Empress Shek'zeer weaves shadows at a random player, inflicting $124844s1 Shadow damage. This effect will hit an additional enemy every 2 seconds, until it is eventually hitting all enemy players.",difficultyIDs={4,6,7}},
			{id=6720,title="Amassing Darkness",body="Grand Empress Shek'zeer weaves shadows at a random player, inflicting $124844s1 Shadow damage. This effect will hit an additional enemy every 6 seconds, until it is eventually hitting all enemy players.",difficultyIDs={3,5}},
			{id=6488,title="Visions of Demise",body="The Empress inflicts on two random players a vision of their own demise. The vision reveals itself to the player after $124862d., causing them to suffer in fear and inflict $124868s1 Shadow damage every $124863t2 sec. to all players within $124868A1 yards for $124863d.",difficultyIDs={3,5}},
			{id=6781,title="Visions of Demise",body="The Empress inflicts on five random players a vision of their own demise. The vision reveals itself to the player after $124862d., causing them to suffer in fear and inflict $124868s1 Shadow damage every $124863t2 sec. to all players within $124868A1 yards for $124863d.",difficultyIDs={4,6,7}},
			{id=6489,title="Heart of Fear",body="The Empress unleashes a swirling heart of dark energy, which targets a random player and inflicts Shadow damage in their direction. If a player stands between the heart and a targeted player, then they take the damage instead of the target.",difficultyIDs={5,6}},
		},
	},
