			{id=6345,title="Tempest Slash",body="Blade Lord Ta'yak slashes the air, creating a tornado that inflicts $122853s1 Nature damage and knocks away any enemies in its path."},
			{id=6346,title="Unseen Strike",body="Blade Lord Ta'yak fixes his eyes on a random player and then disappears. He reappears 5 sec. later and inflicts $122994s1 Physical damage split amongst all players in a $122994a1 yard long cone in front of him."},
			{id=6347,title="Wind Step",body="Blade Lord Ta'yak teleports to random player and inflicts a quick strike. The blow causes all targets within $123459A1 yards to bleed for $123180s1 Physical damage every $123180t1 sec. for $123180d1."},
			{id=6348,title="Intensify",body="Blade Lord Ta'yak's fury intensifies during the encounter. Every $123470t1 sec. Ta'yak increases his damage dealt by $123471s1% and his haste by $123471s2%. This effect stacks."},
			{id=6349,title="Overwhelming Assault",body="Blade Lord Ta'yak performs an overwheming attack on his current target, inflicting $123474s1% of a normal melee swing's attack. The attack leaves the target's defenses exposed, increasing the target's damage taken when an Overwhelming Assault lands by $123474s2% for $123474d."},
			{id=6576,title="Blade Tempest",body="Blade Lord Ta'yak rapidly spins his blade, pulling all enemies towards himself and inflicting $125312s1 Physical damage every $125310t1 sec.",difficultyIDs={5,6}},
			{id=6350,title="Storm Unleashed",body="Upon reaching 20% health, Blade Lord Ta'yak traps all players within a mass of tornadoes, moving them to one end of the hall. All players suffer $124783s1 Nature damage every $124785t1 sec. while they are trapped within the tornadoes. This damage increases with Ta'yak's current Intensify level.\n\nTa'yak then assumes a position at the opposite end of the hall, and unleashes a barrage of tornadoes that travel down the hall towards the players. Any player that is caught within a tornado will be picked up and carried away from Ta'yak."},
