			{id=6425,title="Exhale",body="Imperial Vizier Zor'lok selects a random player and screams at them, inflicting Physical damage and stunning them for $122761d. The first player between Imperial Vizier Zor'lok and the initial target suffers additional Physical damage every $122761t1 seconds.",difficultyIDs={3,4,5,6}},
			{id=6579,title="Exhale",body="Imperial Vizier Zor'lok selects a random player and screams at them, inflicting Physical damage for $122761d. The first player between Imperial Vizier Zor'lok and the initial target suffers additional Physical damage every $122761t1 seconds.",difficultyIDs={7}},
			{id=6428,title="Stage One: Her Gifts are Many",body="Imperial Vizier Zor'lok flies to a random platform in the room, then attacks the players from there. When Zor'lok loses 20% of his total health, he changes positions to a different platform. Imperial Vizier Zor'lok gains one ability while at each platform, but loses that ability when he moves to a different platform."},
			{id=6433,title="Pheromones of Zeal",body="The lower section of Imperial Vizier Zor'lok's chamber fills with toxic Pheromones of Zeal. Players in the area suffer $123812m1 damage per second and are silenced for as long as they are in the area of effect."},
			{id=6426,title="Attenuation",body="Imperial Vizier Zor'lok emits a dizzying series of sonic rings that travel outward from him in a spiraling pattern. Sonic rings inflict $122336s1 Physical damage to all targets in their path.$[!5\n\nIn 10 player Heroic Difficulty, Attenuation also sends out Sonic Pulses.  Sonic Pulses inflict $124673s1 Physical damage to all targets in their path.$]$[!6\n\nIn 25 player Heroic Difficulty, Attenuation also sends out Sonic Pulses.  Sonic Pulses inflict $124673s1 Physical damage to all targets in their path.$]"},
			{id=6427,title="Force and Verve",body="Imperial Vizier Zor'lok shouts with pure volume to inflict $122718s1 physical damage to all players every $122713t1 seconds for $122713d.\nPlayers standing in Noise Cancelling zones suffer $122706s1% less damage from this ability."},
			{id=6445,title="Noise Cancelling",body="Before Imperial Vizier Zor'lok begins channeling Force and Verve, he summons Noise Cancelling zones nearby. Standing in these zones reduces the damage of Force and Verve by $122706s1% and reduces the damage from Sonic Rings by $122706s2%. $[!1,3\n\nIn 10 player Difficulty, only four players can benefit from each Noise Cancelling zone at a time.$]$[!2,4\n\nIn 25 player Difficulty, only nine players can benefit from each Noise Cancelling zone at a time.$]$[!5\n\nIn 10 player Heroic Difficulty, only three players can benefit from each Noise Cancelling zone at a time.$]$[!6\n\nIn 25 player Heroic Difficulty, only seven players can benefit from each Noise Cancelling zone at a time.$]"},
			{id=6432,title="Convert",body="Imperial Vizier Zor'lok uses the pure voice of the Empress to sway the allegiance of two players at random, causing them to fight for the Mantid Empire. Convert lasts until the victim reaches 50% health.",difficultyIDs={3,5}},
			{id=6654,title="Convert",body="Imperial Vizier Zor'lok uses the pure voice of the Empress to sway the allegiance of five players at random, causing them to fight for the Mantid Empire. Convert lasts until the victim reaches 50% health.",difficultyIDs={4,6}},
			{id=6797,title="Convert",body="Imperial Vizier Zor'lok uses the pure voice of the Empress to sway the allegiance of three players at random, causing them to fight for the Mantid Empire. Convert lasts until the victim reaches 50% health.",difficultyIDs={7}},
			{id=6429,title="Stage Two: We Will Not Disappoint Her",body="When Imperial Vizier Zor'lok reaches 40% remaining health, he flies to the center of the chamber and inhales the Pheromones of Zeal. Imperial Vizier Zor'lok now uses all of his abilities from Stage One."},
			{id=6434,title="Inhale Pheromones",body="Imperial Vizier Zor'lok inhales all of the Pheromones in the chamber, increasing his damage by $123833s2% and haste by $123833s3%."},
			{id=6577,title="Song of the Empress",body="Whenever Imperial Vizier Zor'lok finishes a transition he will raise his voice in praise to the empress. Failing to engage Imperial Vizier Zor'lok in melee combat will result in him inflicting Physical damage to all players in the zone until they die. Engaging Imperial Vizier Zor'lok in melee combat will end this effect."},
			{id=6566,title="Echoes of Power",body="In Heroic difficulty, Imperial Vizier Zor'lok will leave copies of himself behind at the first two platforms he visits. During stage two of the encounter he will randomly summon Echoes of Power to aid him in battle.\nEchoes of Power inherit one of Imperial Vizier Zor'lok's abilities and will continue to use that power until they are defeated.",difficultyIDs={5,6}},
			{id=6568,title="Echo of Attenuation",body="Echo of Attenuation will use Zor'lok's Attenuation ability as well as fight players in melee combat.",difficultyIDs={5,6}},
			{id=6569,title="Echo of Force and Verve",body="Echo of Force and Verve will use Zor'lok's Force and Verve ability as well as fight players in melee combat.",difficultyIDs={5,6}},
			{id=6578,title="Song of the Empress",body="Any echoes that Imperial Vizier Zor'lok has summoned will use the Song of the Empress any time they are not actively using one of their abilities and they are not engaged in melee combat. As with Imperial Vizier Zor'lok engaging the echoes in melee combat will end this effect.",difficultyIDs={5,6}},
		},
	},
	[814]={
