		sections={
			{id=6869,title="The Quilen Champions",body="Iron Qon battles atop his finest Quilen champions."},
			{id=6875,title="Throw Spear",body="Iron Qon hurls his mighty spear over a random player, inflicting $134926s1 Physical damage on impact."},
			{id=6874,title="Impale",body="Iron Qon impales his target with his spear, inflicting normal melee damage and causing bleeding, which inflicts an additional $134691s1 Physical damage every $134691t1 sec. This effect stacks."},
			{id=6865,title="Ro'shak, the Molten Flare",body="$[!5, 6 In Heroic difficulty, the Iron Qon's Quilen flee at 25% Health. $]"},
			{id=6972,title="Molten Inferno",body="Ro'shak emits molten flame, inflicting $134664s1 Fire damage to all players. This will relieve Ro'shak of 10 Molten Energy."},
			{id=6973,title="Molten Overload",body="When he reaches maximum Molten Energy, Ro'shak overloads and combusts, casting Molten Inferno every $137221t1 sec until he is degraded of molten energy. This effect temporarily increases his damage dealt by $137221s2%."},
			{id=6870,title="Unleashed Flame",body="Ro'shak incinerates the largest cluster of enemies he can find, inflicting $134628s1 Fire damage split evenly among targets within $134628A1 yards. Discharging this flame relieves Ro'shak of 30 Molten Energy.\n\nThere must be at least 3 targets clustered in order to get Ro'shak's attention.",difficultyIDs={3,5}},
			{id=6871,title="Scorched",body="Ro'shak's burning talons leave players Scorched, increasing Fire damage taken by $134647s1% for $134647d.",difficultyIDs={3,5}},
			{id=6974,title="Unleashed Flame",body="Ro'shak incinerates the largest cluster of enemies he can find, inflicting $134628s1 Fire damage split evenly among targets within $134628A1 yards. Discharging this flame relieves Ro'shak of 30 Molten Energy.\n\nThere must be at least 5 targets clustered in order to get Ro'shak's attention.",difficultyIDs={4,6,7}},
			{id=6975,title="Scorched",body="Ro'shak's burning talons leave players scorched, increasing Fire damage taken by $134647s1%.",difficultyIDs={4,6,7}},
			{id=6912,title="Ignite Spear: Burning Cinders",body="Ro'shak spits molten lava at Iron Qon's spear, causing magma to burst forth from the ground, inflicting $137668s2 Fire damage initially and then stacking $137668s1 Fire damage every $137668t1 sec to players who remain within the effect."},
			{id=7777,title="Calling the Stormcaller: Quet'zal",body="In Heroic difficulty, Quet'zal attacks players alongside Ro'shak. He casts Lightning Storm on random players from above.",difficultyIDs={5,6}},
			{id=7780,title="Whirling Winds",body="Quet'zal summons a massive swirl of wind and launches it ahead of him, inflicting $139167s1 Nature damage to all players with which it comes into contact.",difficultyIDs={5,6}},
			{id=6866,title="Quet'zal, the Stormcaller",body="$[!5, 6 In Heroic difficulty, the Iron Qon's Quilen flee at 25% Health. $]"},
			{id=6876,title="Arcing Lightning",body="Quet'zal zaps a random player with Lightning, stunning, absorbing healing effects, and causing them to shock nearby allies for $136193s1 Nature damage. This shock damage effect jumps to nearby allies, causing them to also pulse with electricity.\n\nThey are stunned until another player pulls them out of the storm. If they die while under the effect of Lightning Storm, then Arcing Lightning will zap a random player."},
			{id=6877,title="Windstorm",body="Quet'zal pulls all players into the eye of a rushing windstorm. Players suffer $136577s1 Nature damage every $136577t1 sec until they are able to exit the storm. Damage, healing, and absorption effects cast while inside the windstorm are decreased by $136577s2%.\n\nOnce the storm is over, some rushing winds will linger."},
			{id=6878,title="Rushing Winds",body="Rushing winds attract players into the storm, inflicting $135583s1 Nature damage every $135583t1 sec to those who stand within."},
			{id=6913,title="Strike Spear: Storm Cloud",body="Quet'zal calls lightning down on Iron Qon's spear, causing a rolling storm cloud that electrifies players for $137669s2 Nature damage. \n\nThis effect stacks, and players who receive $137669s3 stacks become fully electrified and are stunned for $137669d."},
			{id=7778,title="Breaking the Ice: Dam'ren",body="In Heroic difficulty, Dam'ren attacks players alongside Quet'zal. He freezes and shatters random players from above.",difficultyIDs={5,6}},
			{id=7781,title="Frost Spike",body="Dam'ren commands frost spikes from the ground beneath random players, inflicting $139180s1 Frost damage and knocking enemy targets within $139180A1 yards into the air.",difficultyIDs={5,6}},
			{id=6867,title="Dam'ren, the Frozen Sage",body="$[!5, 6 In Heroic difficulty, the Iron Qon's Quilen flee at 25% Health. $]"},
			{id=6914,title="Dead Zone",body="Dam'ren directionally shields himself. Players standing within the Dead Zone created by this shield cause all incoming and outgoing attacks to miss."},
			{id=7861,title="Frozen Resilience",body="Dam'ren is protected with a sheen of ice which reflects $135144s2% of damage taken back at the attacker.",difficultyIDs={3,4,5,6}},
			{id=7862,title="Frozen Resilience",body="Dam'ren is protected with a sheen of ice which reflects $135144s3% of damage taken back at the attacker.",difficultyIDs={7}},
			{id=6915,title="Freeze",body="Dam'ren freezes a random player. After 1-5 sec, Dam'ren will then Shatter them, inflicting $135146s1 Frost damage to all enemies."},
			{id=6916,title="Freeze Spear: Frozen Blood",body="Dam'ren strikes Iron Qon's spear with ice, freezing the ground around it. Coming into contact with the frozen ground inflicts $137664s2 Frost damage instantly and slows the player's movement, melee, ranged, and casting speeds by $137664s1%. This effect stacks while standing within the area of frozen blood."},
			{id=7779,title="Spark of the Molten Flare: Ro'shak",body="In Heroic difficulty, Ro'shak attacks players alongside Dam'ren. He casts Unleashed Flame on the largest clump of enemies he can find. If he cannot find a clump of enemies, he instead casts it on a random target.",difficultyIDs={5,6}},
			{id=6868,title="Iron Qon's Last Stand",body="Having lost his prime quilen mounts, Iron Qon faces you himself. In addition to his previous attacks, he gains new abilities."},
			{id=6917,title="Fist Smash",body="Having no spear in hand, Iron Qon smashes the ground violently, inflicting $136147s1 Physical damage to all players every $136146t1 sec for $136146d."},
			{id=6918,title="Rising Anger",body="Iron Qon becomes increasingly angry, increasing damage done by $136323s1% per stack."},
			{id=6919,title="Ignite Cyclone",body="Iron Qon ignites a random cyclone, causing it to burn all players for $136925s1 Fire damage every $136159t4 sec."},
			{id=6920,title="Freeze Cyclone",body="Iron Qon freezes a random cyclone, causing it to entomb players in ice on contact. The player will take damage equal to $136892s2% of their maximum health every $136892t2 sec."},
		},
	},
