		sections={
			{id=6879,title="Hard Stare",body="Durumu focuses his gaze on his current target and inflicts $133765s1% weapon damage as Physical damage on them. Victims of this attack suffer a Serious Wound and an Arterial Cut."},
			{id=6880,title="Serious Wound",body="Victims of Serious Wound receive $133767s1% less healing per application."},
			{id=6881,title="Arterial Cut",body="Victims of Arterial Cut suffer $133768s1 Physical damage every second until they are restored to full health."},
			{id=6890,title="Gaze",body="If Durumu has no valid melee targets he instead Gazes at all players, inflicting $134029s1% weapon damage as Physical damage."},
			{id=6882,title="Disintegration Beam",body="Durumu will focus his gaze into a beam of pure destruction directly in front of him. Players who are caught in the beam are killed instantly. While focusing this beam Durumu will slowly turn in either direction and his Cross-Eye will create a maze of Eye Sores across the platform."},
			{id=6883,title="Cross-Eye",body="Durumu's Cross-Eye creates a maze of Eye Sores across the platform whenever he channels his Disintegration Beam."},
			{id=6901,title="Eye Sore",body="Eye Sores inflict $134755s1 Arcane damage to victims within their area of effect every second."},
			{id=7858,title="Mind Daggers",body="Any currently active eyes other than the Cross-Eye will inflict $139107s1 Arcane damage to random players in the raid.\n\n$[!3,5 In 10-Player difficulties 1 player is chosen at random.$]$[!4,6,7 In 25-Player difficulties 3 players are chosen at random.$]"},
			{id=6889,title="Walls of Ice",body="Durumu summons three walls of ice to impede players as they attempt to move around the platform. The individual sections of each ice wall have their health linked and will shatter when any section has been sufficiently damaged.",difficultyIDs={5,6}},
			{id=6891,title="Light Spectrum",body="Durumu spawns a Blue Eye, Red Eye, and a Yellow Eye to cast three color beams targeting random players in the raid.  Once the initial beam completes, the Blue Eye and Red Eye focus a cone on their inital target for the duration of the Light Spectrum sequence.  The Yellow Eye ignores its initial target and instead moves its cone in one randomly chosen direction. \n\n$[!3,4,5,6 Players in each cone split damage equally and will gradually suffer more damage the longer they are within the cone's area of effect.$]$[!7 In Raid Finder Difficulty, each cone inflicts damage to all players within it.$]\n\nEach cone reveals a specific creature that is normally invisible.\n\n$[!3,4,5,6 These cones persist until players have found and vanquished all Crimson Fogs.$]$[!7 In Raid Finder Difficulty, these cones persist until players have found and vanquished one fog beast of each color.$]\n\n$[!5,6 In Heroic Difficulty, if players fail to complete the Light Spectrum sequence within 80 seconds Durumu will Obliterate the raid.$]"},
			{id=7819,title="Infrared Light",body="If no players are in the Red Eye's cone, the Eye will inflict $133733s1 Fire damage to all players. Otherwise all players within the Red Eye's cone suffer $133732s1 Fire damage every 2 seconds.",difficultyIDs={7}},
			{id=7811,title="Infrared Light",body="If no players are in the Red Eye's cone, the Eye will inflict $133733s1 Fire damage to all players. Otherwise all players within the Red Eye's cone split $133732s1 Fire damage equally every 2 seconds.",difficultyIDs={3,4,5,6}},
			{id=7820,title="Bright Light",body="If no players are in the Yellow Eye's cone, the Eye will inflict $133739s1 Nature damage to all players. Otherwise all players within the Yellow Eye's cone suffer $133738s1 Nature damage every 2 seconds.",difficultyIDs={7}},
			{id=7812,title="Bright Light",body="If no players are in the Yellow Eye's cone, the Eye will inflict $133739s1 Nature damage to all players. Otherwise, all players within the Yellow Eye's cone split $133738s1 Nature damage equally every 2 seconds.",difficultyIDs={3,4,5,6}},
			{id=7821,title="Blue Rays",body="If no players are in the Blue Eye's cone, the Eye will inflict $133678s1 Frost damage to all players. Otherwise all players within the Blue Eye's cone suffer $133677s1 Frost damage every 2 seconds.",difficultyIDs={7}},
			{id=7813,title="Blue Rays",body="If no players are in the Blue Eye's cone, the Eye will inflict $133678s1 Frost damage to all players. Otherwise all players within the Blue Eye's cone split $133677s1 Frost damage equally every 2 seconds.",difficultyIDs={3,4,5,6}},
			{id=6892,title="Crimson Fog",body="Crimson Fogs are only revealed by the Red Eye's Infrared Light."},
			{id=6894,title="Caustic Spike",body="Crimson Fogs cast Caustic Spike at random players while revealed by the Infrared cone of the Red Eye. Caustic Spike inflicts $136154s1 Physical damage to the victim."},
			{id=6893,title="Crimson Bloom",body="If a Crimson Fog leaves the Red Eye's Infrared cone it will cast Crimson Bloom. Crimson Bloom inflicts $136122s1 Fire damage to all players."},
			{id=6895,title="Amber Fog",body="Amber Fogs are only revealed by the Yellow Eye's Bright Light.",difficultyIDs={5,6,7}},
			{id=6896,title="Amber Retaliation",body="Amber Fogs will cast Amber Retaliation once for every 10% health lost. Amber Retaliation inflicts $136175s1 Nature damage to all players within the cone of Bright Light."},
			{id=6897,title="Burst of Amber",body="If an Amber Fog leaves the area of Yellow Eye's Bright Light it will cast Burst of Amber. Burst of Amber inflicts $136123s1 Nature damage to all players."},
			{id=6898,title="Azure Fog",body="Azure Fogs are only revealed by Blue Eye's Blue Rays."},
			{id=6899,title="Icy Grasp",body="Azure Fogs inflict increasing Frost damage to all players in the cone of Blue Rays while revealed by the Blue Eye's cone of Blue Rays."},
			{id=7804,title="Flash Freeze",body="If an Azure Fog leaves the area of Blue Eye's Blue Rays it will explode for $136124s1 Frost damage to all players.",difficultyIDs={7}},
			{id=7805,title="Flash Freeze",body="If an Azure Fog leaves the area of Blue Eye's Blue Rays it will explode for $136124s1 Frost damage to all players.  Azure Fogs will also cast this spell whenever they are slain.",difficultyIDs={3,4,5,6}},
			{id=6900,title="Biting Chill",body="When players destroy an Azure Fog, it will respawn in a random location on the platform.",difficultyIDs={3,4,5,6}},
			{id=6884,title="Mind's Eye",body="Durumu summons a Mind's Eye that casts Force of Will periodically."},
			{id=6905,title="Force of Will",body="The Mind's Eye focuses intently on a random player, knocking back any players who remain in the Eye's gaze when Force of Will finishes casting.",difficultyIDs={3,4,5,6}},
			{id=7859,title="Force of Will",body="The Mind's Eye focuses intently on a random player, knocking down any players who remain in the Eye's gaze when Force of Will finishes casting.",difficultyIDs={7}},
			{id=6885,title="Hungry Eye",body="Durumu summons a Hungry Eye that casts Life Drain on players."},
			{id=6906,title="Life Drain",body="The Hungry Eye focuses its gaze on a random player and begins to draw out their life force, stunning them for $133795d. Life lost from the victim is added to Durumu's health pool.\n\nThe longer the Hungry Eye is allowed to focus on any given player the more life will be drawn from the victim. Hungry Eyes drain the life of the closest player between it and the initial target."},
			{id=6886,title="Evil Eye",body="Durumu's Evil Eye periodically casts Dark Parasite on players.",difficultyIDs={5,6}},
			{id=6907,title="Dark Parasite",body="Dark Parasites course through the victim, inflicting Shadow damage every second. The amount of damage increases the longer the parasite is allowed to infect its host.\n\nDispelling the parasites from the victim causes the parasites to morph into a Dark Plague.",difficultyIDs={5,6}},
			{id=6908,title="Dark Plague",body="When Dark Parasites are cleansed they morph into a Dark Plague. Dark Plague's duration is equal to the duration remaining when Dark Parasites was cleansed and will spawn a Wandering Eye every 3 seconds.",difficultyIDs={5,6}},
			{id=6909,title="Wandering Eye",body="Wandering Eyes are spawned from victims of Dark Plague and will attack a random player.",difficultyIDs={5,6}},
			{id=6910,title="Devour",body="Wandering Eyes inflict $134010s1 Shadow damage to their chosen host every two seconds. Any damage the Wandering Eye suffers is copied to the host.",difficultyIDs={5,6}},
			{id=6887,title="Appraising Eye",body="Durumu will summon an Appraising Eye that casts Lingering Gaze on players."},
			{id=6911,title="Lingering Gaze",body="The Appraising Eye lobs a shadowy missile at two random players. When the missile lands it explodes for $133793s2 Shadow damage to all within $133793A2 yards and will create a zone that will persist until the end of the encounter. Players entering this zone suffer $140495s1 Shadow damage every second and are slowed $134040s2%.",difficultyIDs={3,5}},
			{id=7750,title="Lingering Gaze",body="The Appraising Eye lobs a shadowy missile at five random players.  When the missile lands it explodes for $133793s2 Shadow damage to all within $133793A2 yards and will create a zone that will persist until the end of the encounter. Players entering this zone suffer $140495s1 Shadow damage every second and are slowed $134040s2%.",difficultyIDs={4,6}},
			{id=7751,title="Lingering Gaze",body="The Appraising Eye lobs a shadowy missile at three random players.  When the missile lands it explodes for $133793s2 Shadow damage to all within $133793A2 yards and will create a zone that will persist until the end of the encounter. Players entering this zone suffer $140495s1 Shadow damage every second.",difficultyIDs={7}},
			{id=7865,title="Obliterate",body="Durumu will kill all players if he has not been defeated within 10 minutes.\n\n$[!5,6 In Heroic Difficulty, Durumu will use Obliterate if players fail to complete the Light Spectrum sequence within 80 seconds.$]"},
		},
	},
