		sections={
			{id=7078,title="Triple Puncture",body="A brutal tri-horned strike that inflicts $136767s1 Physical damage and increases the damage taken from Triple Puncture by $136767s2% for $136767d. This effect stacks."},
			{id=7079,title="Double Swipe",body="Horridon swings his massive head and tail to and fro, inflicting $136740s1 Physical damage to players in a $136740a1-yard cone in front of and behind himself. This effect happens twice."},
			{id=7080,title="Charge",body="Horridon charges at a random player, performing a Double Swipe once he reaches their location."},
			{id=7093,title="Dire Call",body="Horridon emits a powerful roar, inflicting $137458s2 Physical damage and increasing the melee attack speed of all allies by $137458s1%. The power of the Dire Call also summons forth a Direhorn Spirit.",difficultyIDs={5,6}},
			{id=7866,title="Direhorn Spirit",body="Horridon's Dire Call awakens a Direhorn Spirit.",difficultyIDs={5,6}},
			{id=7868,title="Dire Fixation",body="The Direhorn Spirit will fixate on a player. Only the fixated player can see or interact with the Direhorn Spirit.",difficultyIDs={5,6}},
			{id=7867,title="Weak Link",body="The Direhorn Spirit's link to Pandaria is weak. Any attack made against a Direhorn Spirit will knock it back.",difficultyIDs={5,6}},
			{id=7081,title="The Farraki",body="War-God Jalak will first call upon the aid of the Farraki tribe."},
			{id=7096,title="Sul'lithuz Stonegazer",body="Once called to action, Sul'lithuz Stonegazers pour from the Farraki tribal door until it is destroyed."},
			{id=7108,title="Stone Gaze",body="The Stonegazer gazes at the target, stunning them for $136708d."},
			{id=7097,title="Farraki Skirmisher",body="Once called to action, Farraki Skirmishers pour from the Farraki tribal door until it is destroyed."},
			{id=7098,title="Farraki Wastewalker",body="A total of three Farraki Wastewalkers will jump down from the arena stands once the Farraki are called to action."},
			{id=7109,title="Blazing Sunlight",body="The Wastewalker calls upon the scorching sunlight of Tanaris to inflict $136719s1 Fire damage instantly and $136719s2 Fire damage every $136719t2 sec for $136719d."},
			{id=7110,title="Sand Trap",body="Summons a Sand Trap, which inflicts $136723s1 Nature damage to nearby enemies every $136724t1 sec and grows in size over time."},
			{id=7082,title="The Gurubashi",body="War-God Jalak will call upon the Gurubashi tribe to enter the arena second."},
			{id=7099,title="Gurubashi Bloodlord",body="Once called to action, Gurubashi Bloodlords pour from the Gurubashi tribal door until it is destroyed."},
			{id=7111,title="Rending Charge",body="The Bloodlord charges at an opponent and strikes them, causing them to bleed for $136654s1 Physical damage every $136654t1 sec for $136654d."},
			{id=7100,title="Gurubashi Venom Priest",body="A total of three Gurubashi Venom Priests will jump down from the arena stands once the Gurubashi are called to action."},
			{id=7112,title="Venom Bolt Volley",body="The Gurubashi Venom Priest unleashes a spray of vile toxins that inflicts $136587s1 Nature damage to all enemies instantly, and $136587s2 Nature damage every $136587t2 sec for $136587d. This effect stacks."},
			{id=7113,title="Venomous Effusion",body="The Gurubashi Venom Priest can summon a Venomous Effusion."},
			{id=7114,title="Venom Bolt Volley",body="The Venomous Effusion unleashes a spray of vile toxins that inflicts $136587s1 Nature damage to all enemies instantly, and $136587s2 Nature damage every $136587t2 sec for $136587d. This effect stacks."},
			{id=7115,title="Living Poison",body="When a Venomous Effusion is created, a pool of Living Poison forms beneath it. Living Poison inflicts $136646s1 Nature damage to enemies within $136646A1 yards every $136645t1 sec and wanders around."},
			{id=7083,title="The Drakkari",body="War-God Jalak will call upon the Drakkari tribe to enter the arena third."},
			{id=7101,title="Risen Drakkari Warrior",body="Once called to action, Risen Drakkari Warriors pour from the Drakkari tribal door until it is destroyed."},
			{id=7116,title="Uncontrolled Abomination",body="The foul necromantic magics that animated the last remnants of the Drakkari tribe left them bereft of intelligence and purpose, causing the Risen Drakkari to attack random targets."},
			{id=7117,title="Deadly Plague",body="Risen Drakkari spread a Deadly Plague when they strike players, inflicting $136710s1 Shadow damage every $136710t1 sec for $136710d."},
			{id=7102,title="Risen Drakkari Champion",body="Once called to action, Risen Drakkari Champions pour from the Drakkari tribal door until it is destroyed."},
			{id=7118,title="Uncontrolled Abomination",body="The foul necromantic magics that animated the last remnants of the Drakkari tribe left them bereft of intelligence and purpose, causing the Risen Drakkari to attack random targets."},
			{id=7119,title="Deadly Plague",body="Risen Drakkari spread a Deadly Plague when they strike players, inflicting $136710s1 Shadow damage every $136710t1 sec for $136710d."},
			{id=7103,title="Drakkari Frozen Warlord",body="A total of three Drakkari Frozen Warlords will jump down from the arena stands once the Drakkari are called to action."},
			{id=7120,title="Mortal Strike",body="A powerful blow inflicts $136670s1% weapon damage and leaves the player wounded, reducing the effectiveness of any healing received by $136670s2% for $136670d."},
			{id=7121,title="Frozen Orb",body="Summons an orb of frozen power that shoots a bolt of frost at a nearby enemy target every $136572t1 sec, inflicting $136573s1 Frost damage and slowing movement speed by $136573s2% for $136573d."},
			{id=7084,title="The Amani",body="War-God Jalak will call upon the Amani tribe to enter the arena last."},
			{id=7104,title="Amani'shi Protector",body="Once called to action, Amani'shi Protectors pour from the Amani tribal door until it is destroyed."},
			{id=7105,title="Amani'shi Flame Caster",body="Once called to action, Amani'shi Flame Casters pour from the Amani tribal door until it is destroyed."},
			{id=7122,title="Fireball",body="Hurls a ball of fire at a random player, inflicting $136465s1 Fire damage."},
			{id=7106,title="Amani Warbear",body="A total of three Amani Warbears will jump down from the arena stands once the Amani are called to action."},
			{id=7123,title="Swipe",body="The warbear swipes with its claws, inflicting $136463s1 Physical damage to players in a $136463A1-yard cone."},
			{id=7107,title="Amani'shi Beast Shaman",body="Amani'shi Beast Shaman ride atop the powerful Amani Warbears and can be attacked once the Warbear has fallen."},
			{id=7124,title="Chain Lightning",body="The Beast Shaman calls upon the spirits of the storms to inflict $136480s1 Nature damage to a player. Chain Lightning can jump to another player within 5 yards, affecting $136480x1 total targets and increasing damage by 50% per jump."},
			{id=7125,title="Hex of Confusion",body="Hexes a player for $136512d, giving them a 50% chance to injure themselves for $136513s1 Physical damage when casting a spell or using an ability."},
			{id=7126,title="Lightning Nova Totem",body="Places a Lightning Nova totem that emits a pulse of lightning every $136489t1 sec, inflicting $136490s1 Nature damage to enemies within $136490A1 yards."},
			{id=7085,title="The Zandalari",body="War-God Jalak and his faithful Zandalari Dinomancers will come to the aid of Horridon during the battle."},
			{id=7086,title="Zandalari Dinomancer",body="Zandalari Dinomancers will jump down into the arena periodically."},
			{id=7090,title="Dino-Mending",body="The dinomancer channels a beam of healing energy at Horridon, healing $136797s2% of Horridon's maximum health every $136797t2 sec."},
			{id=7091,title="Dino Form",body="At 50% health, the dinomancer transforms into a powerful Devilsaur, increasing Physical damage dealt by $137237s2% but preventing the dinomancer from casting Dino-Mending."},
			{id=7092,title="Orb of Control",body="When the Zandalari Dinomancer transforms, it drops its Orb of Control. A player can interact with the orb to temporarily dominate Horridon's mind, forcing the beast to charge into a tribal door. Destroying a tribal door prevents additional members of that tribe from entering the arena."},
			{id=7094,title="Headache",body="Charging into a tribal door gives Horridon a terrible headache, stunning him for $137294d."},
			{id=7095,title="Cracked Shell",body="Horridon's shell cracks after ramming into a door, increasing damage taken by $137240s2%. This effect stacks up to 4 times."},
			{id=7087,title="War-God Jalak",body="After all four tribes have been called, or when Horridon has been damaged below 30% health, War-God Jalak himself will enter the arena."},
			{id=7088,title="Bestial Cry",body="War-God Jalak unleashes a savage cry, inflicting $136817s1 Physical damage to all players and increasing damage dealt by War-God Jalak by $136817s2%. This effect stacks."},
			{id=7089,title="Rampage",body="War-God Jalak's death causes Horridon to go on a rampage, increasing damage dealt by $136821s1% and attack speed by $136821s2%."},
		},
	},
