		sections={
			{id=6947,title="Primordial Strike",body="Primordius claws at his current target, inflicting $136037s1 Physical damage to all players in a $136037A1-yard cone."},
			{id=6948,title="Malformed Blood",body="The heavily-mutated blood within Primordius spreads to his current target, inflicting $136050s2 Nature damage every $136050t2 sec and causing the afflicted player's attacks to Congeal Blood, inflicting additional Nature damage to Living Fluids and Viscous Horrors. This effect lasts $136050d and stacks."},
			{id=7829,title="Mutated Abomination",body="Primordius is heavily mutated and resists attacks from non-mutated creatures. Damage taken from non-Fully Mutated players is reduced by $140544s1%."},
			{id=6949,title="Evolution",body="When Primordius is mutated by enough Living Fluids, Mutagenic Pools, and his natural mutation rate, he evolves. Evolution increases all damage dealt by Primordius by $136209s1% and grants him a new mutation. This effect stacks. Primordius can only have 3 mutations at any time.$[!5,6\n\nIn Heroic Difficulty, Primordius can have 4 mutations.$]"},
			{id=6950,title="Mutation: Ventral Sacs",body="Sacs located around Primordius's frill periodically erupt, inflicting $136211s1 Nature damage to all players every $136210t1 sec."},
			{id=6951,title="Mutation: Gas Bladder",body="A volatile mutation that allows Primordius to spray Caustic Gas, inflicting $136216s2 Nature damage split evenly between all players within a $136216A1-yard radius."},
			{id=6952,title="Mutation: Acidic Spines",body="Primordius fires Acidic Spines at players every $136218t1 sec, inflicting $136220s1 Nature damage to all players within $136220A1 yards of the targets."},
			{id=6953,title="Mutation: Pathogen Glands",body="Allows Primordius to spray a Volatile Pathogen at a player, inflicting $136231s1 Nature damage every $136228t1 sec. for $136228d."},
			{id=6954,title="Mutation: Metabolic Boost",body="A hyperactive metabolism allows Primordius to use abilities more often and increases attack speed by $136245s2%."},
			{id=6955,title="Mutation: Erupting Pustules",body="Pustules erupt every $136246t1 sec, showering the area with corrosive blood that inflicts $136247s1 Nature damage within $136247A1 yards of the impact."},
			{id=6956,title="Living Fluid",body="Living fluid seeps from the pools surrounding Primordius's lair and these oozes slowly make their way to Primordius."},
			{id=6957,title="Mutate Primordius",body="If a Living Fluid reaches Primordius, it is absorbed, increasing Primordius's current mutation level."},
			{id=6958,title="Mutagenic Pool",body="When a Living Fluid dies, it leaves behind a Mutagenic Pool that can mutate Primordius or players."},
			{id=6959,title="Mutate Primordius",body="When Primordius steps on a Mutagenic Pool, it is absorbed, increasing Primordius's current mutation level."},
			{id=6960,title="Mutate Player",body="When a player steps on a Mutagenic Pool, it is absorbed, inflicting $136178s2 Nature damage and causing a helpful mutation. If $136178s1 mutations are present, the mutation will be a harmful mutation. $[!3,4,5,6\n\nIf a mutated player is dispelled, all mutations are removed.$]"},
			{id=6961,title="Helpful Mutation: Thick Bones",body="The player's bones become thick and powerful, increasing all stats by $136184s1%."},
			{id=6962,title="Harmful Mutation: Fragile Bones",body="The player's bones become thin and brittle, reducing all stats by $136185s1%."},
			{id=6963,title="Helpful Mutation: Clear Mind",body="The player's mind becomes clear and focused, increasing Mastery by $136186s1%."},
			{id=6964,title="Harmful Mutation: Clouded Mind",body="The player's mind becomes clouded and unfocused, reducing Mastery by $136187s1%."},
			{id=6965,title="Helpful Mutation: Improved Synapses",body="The player's neural synapses fire more quickly, increasing Haste by $136182s1%."},
			{id=6966,title="Harmful Mutation: Dulled Synapses",body="The player's neural synapses fire more slowly, reducing Haste by $136183s1%."},
			{id=6967,title="Helpful Mutation: Keen Eyesight",body="The player's eyesight becomes exceptionally keen, increasing Critical Strike chance by $136180s1%."},
			{id=6968,title="Harmful Mutation: Impaired Eyesight",body="The player's eyesight becomes exceptionally poor, reducing Critical Strike chance by $136181s1%."},
			{id=7830,title="Fully Mutated",body="When a player acquires 5 helpful mutations, they become Fully Mutated, allowing full damage to be dealt to Primordius. Additional mutations after this point will be harmful."},
			{id=7831,title="Volatile Pool",body="When a Living Fluid dies, it will rarely leave behind a Volatile Pool that can mutate Primordius or Players."},
			{id=7832,title="Mutate Primordius (Volatile)",body="When Primordius steps on a Volatile Pool, it is absorbed, increasing Primordius' current mutation level to its maximum and healing Primordius for $140509s3% of his maximum health."},
			{id=7833,title="Mutate Player (Volatile)",body="When a player steps on a Volatile Pool, it inflicts $140508s2 Nature damage and causes a harmful mutation every 1 sec. If a mutated player is dispelled, all mutations are removed."},
			{id=6969,title="Viscous Horror",body="A heavily-mutated creature made of the same fluid that spawned Primordius.",difficultyIDs={5,6}},
			{id=6970,title="Black Blood",body="The Viscous Horror spreads its mutated blood to its current target, inflicting $137000s2 Nature damage every $137000t2 sec and causing the afflicted player's attacks to coat the enemy in Black Blood, inflicting $137000s1 additional Nature damage to Primordius. This effect lasts $137000d and stacks.",difficultyIDs={5,6}},
			{id=6971,title="Deadly Mutagen",body="If a Viscous Horror gets close to Primordius, the mixture of mutative energies will cause it to explode, inflicting $136995s1 Nature damage to all players.",difficultyIDs={5,6}},
		},
	},
