		sections={
			{id=7006,title="One Body, Many Heads",body="When one of Megaera's heads is destroyed, her body takes damage equal to the head's maximum health and two heads regrow in its place."},
			{id=7132,title="Concealing Fog",body="Megaera's body and distant heads are shrouded by thick, swirling fog and are unable to be attacked directly."},
			{id=7807,title="Rampage",body="Megaera begins to Rampage for 20 seconds whenever one of her heads is cut off, inflicting $139548s1 Elemental damage to all players every second. The damage dealt by a particular element is increased by $139458s1% for each additional head of that element that is present."},
			{id=7809,title="Hydra Frenzy",body="Whenever one of Megaera's heads is killed, the heads remaining outside of the Concealing Fog are healed to full and attack $139942s1% faster. This effect stacks."},
			{id=7162,title="Elemental Blood of Megaera",body="As Megaera grows new heads of a given type, her elemental blood increases the damage inflicted by all heads of the same type by $139586s1% for each additional head of that type. This effect stacks."},
			{id=7808,title="Megaera's Rage",body="Megaera's heads outside of the Concealing Fog will begin to spit at their target when they have no targets within melee range. This effect inflicts $139765s1 Elemental damage to all enemies within $139765A1 yards upon impact."},
			{id=6998,title="Flaming Head"},
			{id=7000,title="Cinders",body="Megaera's Flaming Heads use this ability when they are within the Concealing Fog.\n\nFlaming Heads ignite a random player, inflicting $139822s1 Fire damage and an additional $139822s2 Fire damage every $139822t2 sec for $139822d.  In addition, players afflicted with Cinders will cause Icy Ground to melt when they come into contact with it.\n\nWhen Cinders is removed, a pool of flames is created at the target's location that persist for $139834d. The pool inflicts $139836s2 Fire damage every $139835t1 sec. to all players within $139836A1 yards.$[!5,6\n\nIn Heroic Difficulty, Cinders creates a pool of flames at the target's location every 3 seconds.$]"},
			{id=7001,title="Ignite Flesh",body="Megaera's Flaming Heads breathe flames on all players in front of her, inflicting $137730s1 Fire damage every second for $137729d. Players hit by Ignite Flesh burn for $137731s1 additional Fire damage every second for $137731d. This effect stacks."},
			{id=7002,title="Frozen Head"},
			{id=7008,title="Torrent of Ice",body="Megaera's Frozen Heads use this ability when they are within the Concealing Fog.\n\nMegaera's Frozen Heads channel a beam of ice at a random player, inflicting $139889s3 Frost damage at the point of contact every $139890t1 sec. for $139866d. The beam freezes the ground in its wake, creating Icy Ground for $139870d.\n\nIn addition, the Torrent of Ice beam will douse any pools of Cinders that it comes into contact with."},
			{id=7257,title="Icy Ground",body="The frozen ground inflicts $139909s1 Frost damage every second to all players who touch it, reducing their movement speed by $139922s1%. The snare effect of Icy Ground stacks up to $139922U times.$[!5,6\n\nIn Heroic Difficulty, Icy Ground grows to twice its original size over $139870d.$]"},
			{id=7009,title="Arctic Freeze",body="Megaera's Frozen Heads breathe ice on all players in front of her, inflicting $139842s1 Frost damage every second for $139841d. Players hit by Arctic Freeze begin to freeze solid and are stunned for $139844d. if they reach $139843U stacks of Arctic Freeze."},
			{id=7004,title="Venomous Head"},
			{id=7011,title="Acid Rain",body="Megaera's Venomous Heads use this ability when they are within the Concealing Fog.\n\nMegaera's Venomous Heads spit a globule of acid at a random player, inflicting $139850s1 Nature damage to all players upon impact. The damage of Acid Rain is reduced the farther players are from the point of impact.$[!5,6\n\nIn Heroic Difficulty, Megaera's Venomous Heads spit three globules of acid at a time.$]"},
			{id=7012,title="Rot Armor",body="Megaera's Venomous Heads breathe corrosive gas on all players in front of her, inflicting $139839s1 Nature damage every second for $139838d. Players hit by Rot Armor take $139840s1% increased damage from all sources for $139840d. This effect stacks."},
			{id=7005,title="Arcane Head",difficultyIDs={5,6}},
			{id=7810,title="Nether Tear",body="Megaera's Arcane Heads use this ability when they are within the Concealing Fog.\n\nMegaera's Arcane Heads open a tear into the nether, releasing a Nether Wyrm every $140138t1 sec. for $140138d.",difficultyIDs={5,6}},
			{id=7816,title="Nether Wyrm",difficultyIDs={5,6}},
			{id=7817,title="Nether Spike",body="Nether Wyrms blast a random player with nether energy, inflicting $140178s1 Arcane damage.",difficultyIDs={5,6}},
			{id=7818,title="Suppression",body="Nether Wyrms channel nether energy into a random player's mind, stunning them for $140179d.",difficultyIDs={5,6}},
			{id=7015,title="Diffusion",body="Megaera's Arcane Heads breathe arcane energy on all players in front of her, inflicting $139992s1 Arcane damage every second for $139991d. Players hit by Diffusion redirect $139993s1% of all healing received to allies within $139994A1 yards that are not afflicted with Diffusion. This effect stacks.",difficultyIDs={5,6}},
		},
	},
	[824]={
		encounterID=824,
		instanceID=362,
		order=9,
		name="Dark Animus",
		lore="During his reign, Lei Shen labored to build a mechanical servant that would defend his citadel without fear. When his first attempt failed, rage took hold of the Thunder King. He poured this negative emotion into his next, and most successful, creation: the Dark Animus. To this day, the ornate construct observes its duty, empowered by the mysterious substance at the heart of all mogu flesh-shaping experiments.",
