		sections={
			{id=7774,title="Powered by Anima",body="Anima Golems cannot act or use abilities without Anima. Anima capacity is limited by the size of the golem; larger golems can hold more. The Dark Animus has the largest capacity, but cannot use most of its abilities until it reaches specific Anima levels.\n\nDefeating any size Anima Golem will cause the Anima that was powering it to transfer to a random golem with enough available capacity.",difficultyIDs={7}},
			{id=7837,title="Powered by Anima",body="Anima Golems cannot act or use abilities without Anima. Anima capacity is limited by the size of the golem; larger golems can hold more. The Dark Animus has the largest capacity, but cannot use most of its abilities until it reaches specific Anima levels.\n\nDefeating any size Anima Golem will cause the Anima that was powering it to transfer to the nearest golem with enough available capacity.",difficultyIDs={3,4,5,6}},
			{id=7775,title="Critically Damaged",body="Some of the Anima Golems found in 10 player difficulties have sustained severe damage. These golems can still absorb Anima, but cannot act or use abilities.",difficultyIDs={3,5}},
			{id=7758,title="Anima Golem"},
			{id=7765,title="Acceleration Link",body="Anima Golems in close proximity link together, increasing each golem's attack speed by $138453s1% and damage by $138453s2%. In addition, linked golems gain $138453s3% movement speed and immunity to movement slowing effects.",difficultyIDs={3,4,5,6}},
			{id=7860,title="Evasive",body="Anima Golems take $140759s1% reduced damage from area-of-effect sources.",difficultyIDs={3,4,5,6}},
			{id=7759,title="Large Anima Golem"},
			{id=7768,title="Crimson Wake",body="Anima repeatedly explodes upward from the ground in a line that accelerates toward a random target. Crimson Wake will pursue the target for up to 30 seconds. Enemy targets hit by the explosions suffer $138485s1 Fire damage."},
			{id=7760,title="Massive Anima Golem"},
			{id=7761,title="Matter Swap",body="Dematrixes the target enemy's matter. When this effect is removed, the target swaps places with its most distant ally and Arcane damage equal to the target's maximum health is split between them. The portion of the total damage shifted to the target's ally increases each second."},
			{id=7770,title="Explosive Slam",body="The golem slams the ground, inflicting $138569s1 Fire damage to enemies within $138569A1 yards of his target. Enemies struck are seared, increasing the damage of subsequent Explosive Slams for $138569d."},
			{id=7762,title="Dark Animus"},
			{id=7806,title="Activation Sequence",body="The Dark Animus must run through its activation sequence before it can attack or use abilities. This process takes $139537d.",difficultyIDs={7}},
			{id=7772,title="Siphon Anima",body="The Dark Animus periodically drains Anima from its minions. $138644s1 Anima is drained from each golem."},
			{id=7776,title="Touch of the Animus",body="The Dark Animus periodically corrupts a random target, inflicting $138659s1 Fire damage every $138659t1 seconds for the remainder of the encounter."},
			{id=7769,title="Empower Golem",body="The Dark Animus targets the active golem with the least health, healing it by $138780s1% and increasing all damage it deals by $138780s2% for the remainder of the encounter.",difficultyIDs={5,6}},
			{id=7127,title="Anima Ring",body="Upon reaching 25 Anima, the Dark Animus gains the ability to form several spheres in a circle around the target. The spheres move toward the center of the circle. Enemy targets that touch a sphere will consume it, increasing the damage they take from melee attacks by $136962s1% for $136962d. This effect stacks.$[!5,6\n\nIn Heroic Difficulty each sphere also inflicts $136962o2 Fire damage over the duration.$]"},
			{id=7767,title="Anima Font",body="Upon reaching 50 Anima, the Dark Animus gains the ability to further corrupt a target already afflicted by Touch of the Animus, causing them to spew Anima bolts at nearby locations every $138691t1 sec. Enemies struck by the bolts suffer $138707s1 Fire damage."},
			{id=7863,title="Interrupting Jolt",body="Upon reaching 75 Anima, the Dark Animus gains the ability to release a burst of energy, inflicting $139869s1 Nature damage and interrupting the spellcasts of all players.",difficultyIDs={7}},
			{id=7771,title="Interrupting Jolt",body="Upon reaching 75 Anima, the Dark Animus gains the ability to release a burst of energy, inflicting $138763s1 Nature damage and interrupting the spellcasts of all players.",difficultyIDs={3,4}},
			{id=7864,title="Interrupting Jolt",body="Upon reaching 75 Anima, the Dark Animus gains the ability to release a burst of energy, inflicting $139867s1 Nature damage and interrupting the spellcasts of all players.",difficultyIDs={5,6}},
			{id=7773,title="FULL POWER",body="Upon reaching 100 Anima, the Dark Animus gains the ability to unleash a torrent of Anima bolts that strike at random targets. Each bolt inflicts $138738s1 Fire damage to enemies within $138738A1 yds. of the impact point.",difficultyIDs={3,4,5,6}},
		},
	},
