			{id=7146,title="Crush",body="Oondasta crushes his current target, inflicting $137504s1 Physical damage and reducing armor by $137504s2% for $137504d. This effect stacks."},
			{id=7723,title="Alpha Male",body="Oondasta seeks only the most hearty challengers, making him immune to taunts, but also increasing tank-specced players' threat against him by $138390s1%."},
			{id=7147,title="Frill Blast",body="Oondasta's armor is more than just for decoration, and can charge up this powerful blast that inflicts $137505s1 Fire damage to all players in a $137505a1-yard hemisphere in front of Oondasta."},
			{id=7148,title="Growing Fury",body="Oondasta's rage grows as the fight progresses, increasing all damage by $137502s1%. This effect stacks."},
			{id=7149,title="Piercing Roar",body="Oondasta unleashes a piercing roar, inflicting $137457s2 Physical damage to all players and interrupting spell-casting, preventing spells of that school from being cast for $137457d."},
