		sections={
			{id=7747,title="Thundering Throw",body="Jin'rokh the Breaker throws his current target at a distant Mogu statue, breaking the statue and inflicting $137370s2 Physical damage. The thrown player then crashes into the ground, inflicting an additional $137167s1 Nature damage to other players within $137167A1 yards of the point of impact, stunning them for $137371d.\n\nConductive Water erupts from the broken statue, forming a pool on the ground."},
			{id=7822,title="Conductive Water",body="When Jin'rokh destroys a statue with Thundering Throw, water pours forth, forming a growing pool at its feet. These pools are essential to the battle, empowering players with Fluidity, but also making them particularly susceptible to Nature damage through Conduction."},
			{id=7735,title="Fluidity",body="All players standing in Conductive Water receive Fluidity, granting $138002s1% increased healing and inflicting $138002s2% increased damage. However, all players standing in Conductive Water also take $138470s1% increased Nature damage."},
			{id=7740,title="Conduction",body="Many of Jin'rokh the Breaker's abilities travel through Conductive Water, inflicting Nature damage to all players in that Conductive Water."},
			{id=7738,title="Static Burst",body="Jin'rokh the Breaker performs a quick strike, inflicting $137162s1 Nature damage to all players. After $137162D., this applies 10 Static Wound stacks to his current target."},
			{id=7739,title="Static Wound",body="Jin'rokh the Breaker statically constricts the target, inflicting $138349s1 Nature damage per stack when taking melee attacks. Additionally inflicts a third of that damage to other players. This effect stacks, but decreases in potency over time."},
			{id=7741,title="Focused Lightning",body="Jin'rokh the Breaker creates an orb of Focused Lightning, which fixates on a player. The Focused Lightning detonates upon reaching that player, inflicting $137374s1 Nature damage to all players within $137374A1 yards.\n\nThis orb also pulses $137423s1 Nature damage every half second to other players within $137429A1 yards."},
			{id=7754,title="Conduction",body="Focused Lightning Detonation damage travels through Conductive Water, inflicting $137530s1 Nature damage to players standing in Conductive Water."},
			{id=7743,title="Lightning Fissure",body="If the Focused Lightning detonates outside of Conductive Water, a Lightning Fissure forms. This field of unstable energy inflicts $137485s1 Nature damage every $137484T1 second to players within $137485R yards."},
			{id=7753,title="Conduction",body="A Lightning Fissure contacts a Conductive Water, removing the Lightning Fissure and inflicting $138133s2 Nature damage to players standing in that Conductive Water."},
			{id=7744,title="Implosion",body="A Lightning Fissure implodes upon contact with another Focused Lightning, inflicting $137507s1 Nature damage to all players.\n\nThis effect leaves targets vulnerable, increasing damage taken from Implosion by $137507s2%."},
			{id=7766,title="Violent Detonation",body="The Focused Lightning detonates violently inside Electrified Water, inflicting $138990s1 Nature damage to all players within $138990A1 yards."},
			{id=7748,title="Lightning Storm",body="Jin'rokh the Breaker commands a fierce Lightning Storm, inflicting $137261s1 Nature damage to all players every second for $137313d.\n\nFurthermore, the Lightning Storm electrifies Conductive Water."},
			{id=7749,title="Lightning Strike",body="Lightning Strikes multiple locations throughout the room during Lightning Storm, inflicting $137647s1 Nature damage to nearby players. Each Lightning Strike diffuses, inflicting $137905s1 Nature damage to all players in a line.",difficultyIDs={5,6}},
			{id=7737,title="Electrified Waters",body="Jin'rokh the Breaker's Lightning Storm permanently infuses the Conductive Water with storm energies, removing Fluidity and inflicting $138006s1 Nature damage every second to all players remaining in the Conductive Water.\n\nAll players standing in Conductive Water still take $138470s1% increased Nature damage."},
			{id=7763,title="Ionization",body="Jin'rokh the Breaker ionizes enemy players, attracting storm energies over $138732d. Inflicts $138743s1 Nature damage to players within $138733A1 yards when dispelled or duration expires.",difficultyIDs={5,6}},
			{id=7764,title="Conduction",body="Ionization damage travels through Conductive Water, inflicting $138733s1 Nature damage to players standing in Conductive Water.",difficultyIDs={5,6}},
		},
	},
