		sections={
			{id=7237,title="Lightning Conduits",body="While Lei Shen is in range of a Lightning Conduit he powers it, granting him an additional ability specific to that Lightning Conduit. The energy level of the Conduit increases the longer Lei Shen charges it, increasing damage dealt by the granted ability. \n\nWhen the Conduit's power reaches 100 energy, it will increase the level of the Conduit, and the Conduit's power will reset to 0."},
			{id=7238,title="North Conduit: Static Shock",body="Lei Shen charges the target with Static Shock. After $135695d, Static Shock inflicts $135703s1 Nature damage, divided among all players within $135703A1 yards.\n\nAs the level of the Static Shock Conduit increases, the number of targets Lei Shen afflicts with Static Shock will also increase.\n$[!3,4,5,6,7\nDamage of Static Shock increases as the Power and Level of the North Conduit increases.$]"},
			{id=7239,title="East Conduit: Diffusion Chain",body="Lei Shen zaps a player, inflicting $135991s1 Nature damage. This attack chains to nearby enemies, inflicting increased damage to each successive target. Each time Diffusion Chain strikes an enemy, a Diffused Lightning spawns at that location.\n\nAs the level of the Diffusion Chain Conduit increases, the spawned Diffused Lightning elementals grow more powerful.\n$[!3,4,5,6,7\nDamage of Diffusion Chain increases as the Power and Level of the East Conduit increases.$]"},
			{id=7240,title="Diffused Lightning",body="Diffusion Chain creates a Diffused Lightning for every target it strikes. Diffused Lightning's attacks cause Chain Lightning.\n$[!5,6\nIn Heroic difficulty, the Diffused Lightning will fixate on the player that it spawned from.$]"},
			{id=7241,title="South Conduit: Overcharge",body="Lei Shen Overcharges a target player. The player becomes rooted and after $136295d causes Overcharge to burst, creating a torus of electric energy around the target that quickly expands to create a ring with a safe area in the center. This burst inflicts $136326s1 Nature damage, stunning affected targets for $136326d.\n\nAs the level of the Overcharge Conduit increases, the number of targets Lei Shen afflicts with Overcharge also increases.\n$[!3,4,5,6,7\nDamage of Overcharge increases as the Power and Level of the South Conduit increases.$]"},
			{id=7242,title="West Conduit: Bouncing Bolt",body="Lei Shen conjures Bouncing Bolts that target random locations on the ground. Each Bolt inflicts $136366s1 Nature damage split among players within $136366A1 yards. If the Bouncing Bolt does not impact with a player, an Unharnessed Power forms, and the Bouncing Bolt bounces again.\n\nAs the level of the Bouncing Bolt Conduit increases, the number of Bouncing Bolts that Lei Shen conjures also increases.\n$[!3,4,5,6,7\nDamage of Bouncing Bolt increases as the Power and Level of the West Conduit increases.$]"},
			{id=7243,title="Unharnessed Power",body="Each time a Bouncing Bolt impacts the ground and is not absorbed by a player, an Unharnessed Power forms."},
			{id=7178,title="Stage One: Thunderstruck!",body="Lei Shen equips his Axe, Thunder, which he can throw with deadly accuracy and cause lightning to strike the ground wherever it lands. Lei Shen will charge any Conduit that he is near."},
			{id=7179,title="Discharged Energy",body="If Lei Shen is not charging a Conduit, he will Discharge electricity, inflicting increasing Nature damage to all players every $134821t1 sec."},
			{id=7181,title="Decapitate",body="Lei Shen throws his axe with supernatural force, inflicting $134916s1 Physical damage and inflicting Decapitate, increasing Physical damage taken by $134916s2% for $134916d. The damage inflicted decreases the farther away the target is from Lei Shen."},
			{id=7182,title="Thunderstruck",body="Lei Shen winds up to hurl his axe at a target location, inflicting $135096s1 Nature damage to nearby enemies. The damage inflicted decreases the farther away an enemy is from the impact point."},
			{id=7245,title="Crashing Thunder",body="Lei Shen calls down Thunder rapidly on targets every $135143t1 sec causing a Lightning Crash. Crashing Thunder inflicts $135153s1 Nature damage every $135153t1 sec for $135150d."},
			{id=7186,title="Intermission: Supercharge Conduits!",body="When he has 65% health remaining, Lei Shen casts Supercharge Conduits, becoming invulnerable and activating all four Conduits at once, supercharging them and increasing their level by one. Lei Shen can only maintain Supercharge Conduits for 45 seconds."},
			{id=7191,title="Overloaded Circuits",body="The Conduit with the highest charge after Supercharge Conduits expires becomes Overloaded, disabling the Conduit. An Overloaded Conduit inflicts $137176s1 Nature damage every $137176t1 sec to that quadrant of the room.\n$[!5,6\nIn Heroic difficulty, instead of the Overloaded Conduit becoming disabled, it remains active for the remainder of the fight, granting Lei Shen that ability.$]"},
			{id=7814,title="Helm of Command",body="Lei Shen forces the target off the platform by using his Helm of Command. Inflicts $139011s1 Nature damage every $139011t1 sec for $139011d.",difficultyIDs={5,6}},
			{id=7192,title="Stage Two: Lightning Will End You!",body="Lei Shen equips his Polearm, Lightning, allowing him to call lightning from the sky. Lei Shen will charge any Conduit that he is near."},
			{id=7193,title="Discharged Energy",body="If Lei Shen is not charging a Conduit, he will Discharge electricity, inflicting increasing Nature damage every $134821t1 sec."},
			{id=7195,title="Fusion Slash",body="Lei Shen slashes at the target with his polearm, inflicting $136478s1 Nature damage, knocking the target back and increasing damage taken from Fusion Slash by $136478s3% for $136478d."},
			{id=7196,title="Summon Ball Lightning",body="Summon several Ball Lightning elementals at the feet of random targets, inflicting $136543s1 Nature damage to players within $136543A1 yards of each elemental's creation."},
			{id=7247,title="Ball Lightning",body="The Ball Lightning periodically rushes towards a random player, inflicting $136620s2 Nature damage to that target.\n\n$[!5,6\nIn Heroic difficulty, Ball Lightning inflicts damage to enemies within $136620A2 yards.$]"},
			{id=7197,title="Lightning Whip",body="Lei Shen cracks a Lightning Whip across the floor, inflicting $136850s1 Nature damage to enemies in front of him, creating a Lightning Bolt on the ground."},
			{id=7248,title="Lightning Bolt",body="Lightning Bolt inflicts $136853s1 Nature damage every $136853t1 sec. Lightning Bolt can be avoided by jumping over it."},
			{id=7202,title="Intermission: Supercharge Conduits!",body="When he has 30% health remaining, Lei Shen casts Supercharge Conduits, becoming invulnerable and activating all four Conduits at once, supercharging them and increasing their level by one. Lei Shen can only maintain Supercharge Conduits for 45 seconds.\n\n$[!5,6\nIn Heroic difficulty, instead of the Overloaded Conduit becoming disabled, it remains active for the remainder of the fight, granting Lei Shen the ability.$]"},
			{id=7203,title="Overloaded Circuits",body="The Conduit with the highest charge after Supercharge Conduits expires becomes Overloaded, disabling the Conduit. An Overloaded Conduit inflicts $137176s1 Nature damage every $137176t1 sec to that quadrant of the room.\n\n$[!5,6\nIn Heroic difficulty, instead of the Overloaded Conduit becoming disabled, it remains active for the remainder of the fight, granting Lei Shen that ability.$]"},
			{id=7815,title="Helm of Command",body="Lei Shen forces the target off the platform by using his Helm of Command. Inflicts $139011s1 Nature damage every $139011t1 sec for $139011d.",difficultyIDs={5,6}},
			{id=7209,title="Stage Three: Master of Thunder and Lightning",body="Lei Shen equips both his Axe and Polearm, wielding Thunder and Lightning in unision against his enemies. Lei Shen casts Overwhelming Power and consumes all electricity from the Throne of Thunder, destroying any remaining functional Conduits, preventing their further activation."},
			{id=7210,title="Overwhelming Power",body="Lei Shen absorbs all of the electrical power from the Throne of Thunder, destroying any remaining functional Conduits, preventing their further activation. Overwhelming Power causes Lei Shen's melee attacks to inflict $136914s1 Nature damage every $136914t1 sec for $136914d."},
			{id=7249,title="Violent Gale Winds",body="Lei Shen causes the walls of his chamber to open, unleashing the force of Violent Gale Winds. The winds push players in a direction, inflicting $136889s1 Nature damage every $136889t1 sec and causing Windburn."},
			{id=7871,title="Windburn",body="Increases damage taken by Violent Gale Winds by $140208s1%. Stacks."},
			{id=7212,title="Thunderstruck",body="Lei Shen winds up to hurl his axe at a target location, inflicting $135096s1 Nature damage to nearby enemies. The damage inflicted decreases the farther away an enemy is from the impact point."},
			{id=7214,title="Summon Ball Lightning",body="Summon several Ball Lightning elementals at the feet of random targets, inflicting $136543s1 Nature damage to players within $136543A1 yards of each elemental's creation."},
			{id=7215,title="Ball Lightning",body="The Ball Lightning periodically rushes towards a random player, inflicting $136620s2 Nature damage to that target.\n\n$[!5,6\nIn Heroic difficulty, Ball Lightning inflicts damage to enemies within $136620A2 yards.$]"},
			{id=7220,title="Lightning Whip",body="Lei Shen cracks a Lightning Whip across the floor, inflicting $136850s1 Nature damage to enemies in front of him, creating a Lightning Bolt on the ground."},
			{id=7250,title="Lightning Bolt",body="Lightning Bolt inflicts $136853s1 Nature damage every $136853t1 sec. Lightning Bolt can be avoided by jumping over it."},
		},
	},
	[846]={
		encounterID=846,
		instanceID=369,
		order=9,
		name="Malkorok",
		lore="Malkorok has been Garrosh's most loyal and trusted lieutenant throughout the Pandaria campaign. When the Warchief needed a volunteer to infuse with the power of Y'Shaarj, it was only natural that Malkorok would offer without hesitation.",
		dungeonEncounterID=1595,
		uiMapID=563,
		pin={x=0.4165,y=0.4239},
		difficultyIDs={14,15,16,17,241},
		npcIDs={71454},
		displayIDs={49070},
		loot={
			{itemID=112792,diffs={},faction=-1},
			{itemID=112793,diffs={},faction=-1},
			{itemID=112794,diffs={},faction=-1},
			{itemID=112795,diffs={},faction=-1},
			{itemID=112796,diffs={},faction=-1},
			{itemID=112797,diffs={},faction=-1},
			{itemID=112803,diffs={},faction=-1},
			{itemID=112804,diffs={},faction=-1},
			{itemID=112805,diffs={},faction=-1},
			{itemID=112806,diffs={},faction=-1},
			{itemID=112807,diffs={},faction=-1},
			{itemID=112808,diffs={},faction=-1},
			{itemID=112813,diffs={},faction=-1},
			{itemID=112814,diffs={},faction=-1},
			{itemID=112815,diffs={},faction=-1},
			{itemID=112816,diffs={},faction=-1},
			{itemID=112817,diffs={},faction=-1},
			{itemID=112818,diffs={},faction=-1},
			{itemID=112819,diffs={},faction=-1},
			{itemID=112820,diffs={},faction=-1},
			{itemID=112821,diffs={},faction=-1},
			{itemID=112823,diffs={},faction=-1},
		},
		sections={
			{id=10217,title="Overview",body="Malkorok's platform begins covered with a dark miasma that absorbs all healing done to players, converting it into an absorption shield instead. Malkorok strikes the ground with a large cone smash three times in sequence, and then causes the same three areas struck to erupt simultaneously with dark energy.\n\nMalkorok draws in the miasma, entering a Blood Rage and empowering his melee attacks but allowing players to heal normally for a time. Malkorok then exhales the dark energy, and the cycle repeats until he is defeated."},
			{id=10218,title="Damage Dealers",body="$bullet;Be mindful of the locations of Malkorok's |cFF2959D3|Hspell:142826|h[Arcing Smashes]|h|r and avoid those locations when he casts |cFF2959D3|Hspell:142842|h[Breath of Y'Shaarj]|h|r.\n$bullet;If you have a strong absorption shield, stand in |cFF2959D3|Hspell:142986|h[Imploding Energy]|h|r to prevent raidwide damage.\n$bullet;Move away from allies if afflicted with |cFF2959D3|Hspell:142913|h[Displaced Energy]|h|r.\n$bullet;Clump to split the damage from Malkorok's attacks during his |cFF2959D3|Hspell:142879|h[Blood Rage]|h|r."},
			{id=10219,title="Healers",body="$bullet;Heal aggressively to keep allies' Ancient Barrier maximized while |cFF2959D3|Hspell:142861|h[Ancient Miasma]|h|r is active.\n$bullet;Be mindful of the locations of Malkorok's |cFF2959D3|Hspell:142826|h[Arcing Smashes]|h|r and avoid those locations when he casts |cFF2959D3|Hspell:142842|h[Breath of Y'Shaarj]|h|r.\n$bullet;If you have a strong absorption shield, stand in |cFF2959D3|Hspell:142986|h[Imploding Energy]|h|r to prevent heavy raidwide damage.\n$bullet;Dispel |cFF2959D3|Hspell:142913|h[Displaced Energy]|h|r once allies are clear of the raid."},
			{id=10220,title="Tanks",body="$bullet;Take turns tanking Malkorok to allow |cFF2959D3|Hspell:142990|h[Fatal Strikes]|h|r to reset.\n$bullet;Clump to split the damage from Malkorok's attacks during his |cFF2959D3|Hspell:142879|h[Blood Rage]|h|r."},
			{id=7872,title="Ancient Miasma",body="An Ancient Miasma fills the room, absorbing all healing received but creating an Ancient Barrier that absorbs damage equal to the amount of healing absorbed, up to a cap of 100% of maximum health. In addition, the Miasma inflicts $142906s1 Shadow damage every $142906t1 sec."},
			{id=7873,title="Ancient Barrier",body="Whenever Ancient Miasma absorbs healing it creates an Ancient Barrier on the player, absorbing damage equal to the amount of healing absorbed. The damage absorbed from Ancient Barrier cannot be greater than 100% of the player's maximum health.\n\nThis effect is able to absorb damage taken from falling."},
			{id=7950,title="Essence of Y'Shaarj",body="The Ancient Miasma forms orbs of corruption every $143846t1 seconds, which persist for the remainder of the fight. \n\nIf a player comes into contact with an orb, it is consumed, removing Ancient Barrier and inflicting $143857s1 Shadow damage to them.",difficultyIDs={16}},
			{id=7874,title="Endless Rage",body="Malkorok gains Rage over time whenever he is not in a Blood Rage.\n\nWhen Malkorok reaches 100 Rage, he absorbs the Ancient Miasma and enters a Blood Rage."},
			{id=7875,title="Blood Rage",body="When Malkorok reaches 100 Rage, he enters a Blood Rage, causing each melee attack to inflict $142890s1 Physical damage, split among all enemies hit. Blood Rage causes Malkorok to lose $142879s1 Rage every second and ends when he no longer has any Rage.\n\nWhen Blood Rage expires, Malkorok expels the Ancient Miasma from his body."},
			{id=7882,title="Displaced Energy",body="While in a Blood Rage, energy arcs off of Malkorok's body, afflicting players with Displaced Energy. This effect inflicts $142913s1 Shadow damage every $142913t1 sec for $142913d. \n\nWhen Displaced Energy expires, the energy explodes outward, inflicting $142928s1 Shadow damage to all allies within $142928A1 yards who are not afflicted with Displaced Energy.$[!16\n\nIn Mythic Difficulty, Displaced Energy roots the target in place.$]"},
			{id=7898,title="Relentless Assault",body="When Blood Rage expires, Malkorok gains Relentless Assault, increasing all damage done by $143261s1%. This effect stacks."},
			{id=7896,title="Might of the Kor'kron"},
			{id=7883,title="Arcing Smash",body="Malkorok faces a random player and unleashes a devastating overhead attack, inflicting $142815s1 Physical damage to all players within a $142815A1 yard cone in front of him."},
			{id=7884,title="Seismic Slam",body="Malkorok slams the ground, inflicting $142849s2 Physical damage in a $142849A1-yard radius around a random player, knocking all injured targets into the air."},
			{id=7952,title="Living Corruption",body="Seismic Slam causes Living Corruption to ooze out of the ground and attack players.",difficultyIDs={16}},
			{id=7953,title="Languish",body="Living Corruption weakens all players within 8 yards of them, reducing movement speed and spell casting speed by $143919s1%.",difficultyIDs={16}},
			{id=7895,title="Breath of Y'Shaarj",body="Malkorok channels the power of Y'Shaarj, causing the areas recently hit by Arcing Smash to explode, inflicting $142816s1 Shadow damage."},
			{id=7897,title="Imploding Energy",body="Malkorok's corruption opens tears of dark energy that inflict $142986s1 Shadow damage to all players within $142986A1 yards after $144069d.\n\nIf an implosion of energy does not hit a player, it instead inflicts $142987s1 Shadow damage to all players."},
			{id=7899,title="Fatal Strike",body="Malkorok's melee attacks fatally wound his target, increasing their damage taken by $142990s2% for $142990d."},
			{id=7951,title="Eradicate",body="Malkorok kills all players if he is not defeated within $143916s1 minutes."},
		},
	},
	[849]={
		encounterID=849,
		instanceID=369,
		order=2,
		name="The Fallen Protectors",
		lore="The Golden Lotus and Shado-Pan guardians of the Vale of Eternal Blossoms were caught in the epicenter of the devastating blast that scarred the Vale, and torn apart by the dark energies. Their spirits linger in the place they once protected, confused and tormented by their failure.",
		dungeonEncounterID=1598,
		uiMapID=556,
		pin={x=0.258,y=0.1876},
		difficultyIDs={14,15,16,17,241},
		npcIDs={66057,66059},
		displayIDs={48917,48918,48919},
		loot={
			{itemID=112476,diffs={},faction=-1},
			{itemID=112477,diffs={},faction=-1},
			{itemID=112478,diffs={},faction=-1},
			{itemID=112479,diffs={},faction=-1},
			{itemID=112480,diffs={},faction=-1},
			{itemID=112481,diffs={},faction=-1},
			{itemID=112482,diffs={},faction=-1},
			{itemID=112483,diffs={},faction=-1},
			{itemID=112484,diffs={},faction=-1},
			{itemID=112485,diffs={},faction=-1},
			{itemID=112486,diffs={},faction=-1},
			{itemID=112487,diffs={},faction=-1},
			{itemID=112488,diffs={},faction=-1},
			{itemID=112489,diffs={},faction=-1},
			{itemID=112490,diffs={},faction=-1},
			{itemID=112491,diffs={},faction=-1},
			{itemID=112492,diffs={},faction=-1},
