			{itemID=112764,diffs={},faction=-1},
			{itemID=112765,diffs={},faction=-1},
			{itemID=112766,diffs={},faction=-1},
			{itemID=112767,diffs={},faction=-1},
			{itemID=105741,diffs={110},faction=-1},
			{itemID=105742,diffs={110},faction=-1},
			{itemID=105743,diffs={110},faction=-1},
			{itemID=105744,diffs={110},faction=-1},
			{itemID=105745,diffs={110},faction=-1},
			{itemID=105746,diffs={110},faction=-1},
			{itemID=105747,diffs={110},faction=-1},
			{itemID=105748,diffs={110},faction=-1},
			{itemID=105751,diffs={110},faction=-1},
		},
		sections={
			{id=10209,title="Overview",body="Haromm and Kardris begin the encounter fighting alongside their vicious war wolves. The two powerful Dark Shaman share health, and they drop corrupted totems that grant them each different abilities as they sustain damage."},
			{id=10210,title="Damage Dealers",body="$bullet;If targeted by Haromm's |cFF2959D3|Hspell:144090|h[Foul Stream]|h|r, aim the blast away from other raid members.\n$bullet;Keep away from |cFF2959D3|Hspell:144070|h[Ashen Walls]|h|r and Foul Slimes, which damage anyone near them."},
			{id=10211,title="Healers",body="$bullet;If targeted by Haromm's |cFF2959D3|Hspell:144090|h[Foul Stream]|h|r, aim the blast away from your allies.\n$bullet;Keep away from |cFF2959D3|Hspell:144070|h[Ashen Walls]|h|r and Foul Slimes, which damage anyone near them.\n$bullet;When |cFF2959D3|Hspell:143987|h[Falling Ash]|h|r strikes the ground, the blast deals heavy damage to the entire raid."},
			{id=10212,title="Tanks",body="$bullet;Take turns tanking Haromm in order to allow the effects of his |cFF2959D3|Hspell:144215|h[Froststorm Strike]|h|r to dissipate.\n$bullet;Position Haromm's |cFF2959D3|Hspell:144070|h[Ashen Walls]|h|r carefully to avoid limiting your allies' movement.\n$bullet;Keep the Foul Slimes spawned by |cFF2959D3|Hspell:143990|h[Foul Geyser]|h|r away from your allies."},
			{id=8119,title="Spirit Link",body="Damage dealt is shared between Earthbreaker Haromm and Wavebinder Kardris."},
			{id=8120,title="Bloodlust",body="When the Dark Shaman reach 25% health remaining, they will go into a blood frenzy, increasing all damage dealt by $144302s1% and haste by $144302s2%."},
			{id=8121,title="Darkfang and Bloodclaw",body="The riding wolves of the Dark Shaman, Darkfang and Bloodclaw will viciously defend their masters."},
			{id=8122,title="Swipe",body="Inflicts $144303s1 Physical damage to targets in a $144303a1-yard cone in front of the caster."},
			{id=8123,title="Rend",body="Viciously rends a player, causing them to bleed for $144304s1 Physical damage every $144304t1 sec. for $144304d. This effect stacks."},
			{id=8124,title="Totems",body="The Dark Shaman will drop Totems during the fight that grant them new abilities."},
			{id=8125,title="Poisonmist Totem",body="Poisonmist Totem grants Earthbreaker Haromm the Toxic Mist ability, and grants Wavebinder Kardris the Toxic Storm ability. The Dark Shaman drop Poisonmist Totems upon reaching 85% health."},
			{id=8126,title="Foulstream Totem",body="Foulstream Totem grants Earthbreaker Haromm the Foul Stream ability, and grants Wavebinder Kardris the Foul Geyser ability. The Dark Shaman drop Foulstream Totems upon reaching 65% health."},
			{id=8127,title="Ashflare Totem",body="Ashflare Totem grants Earthbreaker Haromm the Ashen Wall ability, and grants Wavebinder Kardris the Falling Ash ability. The Dark Shaman drop Ashflare Totems upon reaching 50% health."},
			{id=8142,title="Rusted Iron Totem",body="Rusted Iron Totem grants Earthbreaker Haromm the Iron Tomb ability, and grants Wavebinder Kardris the Iron Prison ability. The Dark Shaman drop Rusted Iron Totems upon reaching 95% health.",difficultyIDs={16}},
			{id=8128,title="Earthbreaker Haromm"},
			{id=8129,title="Froststorm Strike",body="Strikes a player with frost-lined weapons, inflicting $144215s1 Frost damage and causing the player to take $144215s2% additional damage from Froststorm Strike for $144215d. This effect stacks."},
			{id=8130,title="Toxic Mist",body="Injects several players with a toxic mist, inflicting $144089s2 Nature damage every $144089t2 sec. for $144089d and causing growing Toxicity. Due to the internal nature of the corruption, Toxic Mist pierces all immunities. This ability is granted by Poisonmist Totem."},
			{id=8131,title="Toxicity",body="Increases Nature damage taken by $144107s1% per stack."},
			{id=8132,title="Foul Stream",body="A stream of foul liquid inflicts $144090s2 Nature damage to all enemies on a line. This ability is granted by Foulstream Totem."},
			{id=8133,title="Ashen Wall",body="Summons a line of stationary Ash Elementals that will attack any nearby enemies. This ability is granted by Ashflare Totem."},
			{id=8143,title="Iron Tomb",body="Inflicts $144334s2 Physical damage to players within $144334A2 yards and creates an Iron Tomb. This ability is granted by Rusted Iron Totem.",difficultyIDs={16}},
			{id=8134,title="Wavebinder Kardris"},
			{id=8135,title="Froststorm Bolt",body="Fires a bolt of bitter frost, inflicting $144214s1 Frost damage."},
			{id=8136,title="Toxic Storm",body="Summons a powerful toxic storm that inflicts $144017s1 Nature damage to players within $144017A1 yards every $144006t2 sec. and periodically creates Toxic Tornadoes. The storm will move around and lasts for $144005d. This ability is granted by Poisonmist Totem."},
			{id=8137,title="Toxic Tornado",body="Toxic winds inflict $144030s1 Nature damage to players within $144030A1 yards every $144029t2 sec. and knock them up."},
			{id=8138,title="Foul Geyser",body="Conjure foul water that inflicts $143993s1 Nature damage to players within $143993A1 yards every $143990t2 sec. for $143990d. Each splash creates a Foul Slime. This ability is granted by Foulstream Totem."},
			{id=8139,title="Foul Slime",body="Foul Slimes are coated in Foulness."},
			{id=8140,title="Foulness",body="Inflicts $144066s1 Nature damage to players within $144066A1 yards every $144064t1 sec."},
			{id=8141,title="Falling Ash",body="Summons a core of smouldering ash that will fall over $143986s1 sec. Inflicts $143987s1 Fire damage to players within $143987A1 yards and $143987s2 Fire damage to all players on impact. This ability is granted by Ashflare Totem."},
			{id=8144,title="Iron Prison",body="Encases the player in a prison of iron that slowly asphyxiates them, inflicting $144331s1% of maximum health as Physical damage after $144330d. This ability is granted by Rusted Iron Totem.",difficultyIDs={16}},
		},
	},
	[857]={
		encounterID=857,
		instanceID=322,
		order=5,
		name="Chi-Ji, The Red Crane",
		lore="The trial of Chi-Ji is a test of hope. Uncertain of the future of his people, Emperor Shaohao sought out the great Red Crane. The Great Crane challenged Shaohao to find the hope within himself, and cast off his uncertainty. Once the Sha of Doubt was vanquished, the Emperor became a beacon of hope for his people. To pass the trial of the Crane, warriors must believe in hope, even in the darkest of days.",
		uiMapID=554,
		pin={x=0.3555,y=0.4824},
		difficultyIDs={3,4,5,6,7},
		npcIDs={71952},
		displayIDs={49237},
