	[864]={
		encounterID=864,
		instanceID=369,
		order=6,
		name="Iron Juggernaut",
		lore="This mechanical terror, designed nearly as much for intimidation as destruction, is the centerpiece of Garrosh's siege weaponry. Crafted in the image of the mighty Kor'kron war scorpion, the Iron Juggernaut guards the gates of Orgrimmar, crushing any who would rise up to challenge Garrosh's True Horde.",
		dungeonEncounterID=1600,
		uiMapID=559,
		pin={x=0.3063,y=0.3855},
		difficultyIDs={14,15,16,17,241},
		npcIDs={71466},
		displayIDs={49844},
		loot={
			{itemID=112946,diffs={},faction=-1},
			{itemID=112729,diffs={},faction=-1},
			{itemID=112731,diffs={},faction=-1},
			{itemID=112732,diffs={},faction=-1},
			{itemID=112733,diffs={},faction=-1},
			{itemID=112734,diffs={},faction=-1},
			{itemID=112735,diffs={},faction=-1},
			{itemID=112736,diffs={},faction=-1},
			{itemID=112739,diffs={},faction=-1},
			{itemID=112740,diffs={},faction=-1},
			{itemID=112741,diffs={},faction=-1},
			{itemID=112742,diffs={},faction=-1},
			{itemID=112743,diffs={},faction=-1},
			{itemID=112744,diffs={},faction=-1},
			{itemID=112745,diffs={},faction=-1},
			{itemID=112746,diffs={},faction=-1},
			{itemID=112747,diffs={},faction=-1},
			{itemID=112748,diffs={},faction=-1},
			{itemID=112749,diffs={},faction=-1},
			{itemID=112750,diffs={},faction=-1},
			{itemID=112751,diffs={},faction=-1},
			{itemID=112752,diffs={},faction=-1},
			{itemID=140783,diffs={109},faction=-1},
		},
		sections={
			{id=10205,title="Overview",body="The Iron Juggernaut gathers energy as it assaults players with an array of cannons, lasers, and explosive attacks. Upon reaching full energy, the Juggernaut engages its Siege Mode, digging its claws into the ground and becoming sessile while employing new countermeasures. The Juggernaut cycles between these two phases until defeated."},
			{id=10206,title="Damage Dealers",body="$bullet;Position yourself carefully to control where |cFF2959D3|Hspell:144485|h[Shock Pulse]|h|r launches you.\n$bullet;If targeted with |cFF2959D3|Hspell:144918|h[Cutter Laser]|h|r, avoid leading it across patches of |cFF2959D3|Hspell:144498|h[Explosive Tar]|h|r."},
			{id=10207,title="Healers",body="$bullet;Position yourself carefully to control where |cFF2959D3|Hspell:144485|h[Shock Pulse]|h|r launches you.\n$bullet;During Siege Mode, the Juggernaut deals sustained raidwide damage with |cFF2959D3|Hspell:144484|h[Seismic Activity]|h|r."},
			{id=10208,title="Tanks",body="$bullet;Take turns tanking the Juggernaut to allow the effects of |cFF2959D3|Hspell:144464|h[Flame Vents]|h|r to dissipate.\n$bullet;While not tanking, jump on burrowed Crawler Mines to prevent them from damaging the raid.\n$bullet;Position yourself carefully to control where |cFF2959D3|Hspell:144485|h[Shock Pulse]|h|r launches you."},
			{id=8177,title="Pressing the Attack: Assault Mode",body="The Iron Juggernaut is freely mobile while in Assault mode."},
			{id=8179,title="Borer Drill",body="The Iron Juggernaut bores its drill arm into the ground, causing the earth to crack and shatter. This effect ripples out into many directions, inflicting $144218s1 Physical damage to those caught within its effect."},
			{id=8182,title="Laser Burn",body="The Iron Juggernaut's tail cannon now focuses briefly on random players.\n\nInflicts $144459s1 Fire damage to random players, and sears their flesh for an additional $144459s2 Fire damage every $144459t2 seconds."},
			{id=8188,title="Mortar Cannon",body="The Iron Juggernaut's top cannon launches shrapnel and explosives at a random player, inflicting $144316s1 Fire damage to enemies within $144316A1 yards of the blast."},
			{id=8183,title="Crawler Mines",body="The Iron Juggernaut releases several Crawler Mines that scurry in the direction of random players, burying themselves partially into the ground. Once they burrow, they begin a detonation sequence. At the end of the sequence, they will detonate for $144766s1 Physical damage to all players.\n\nA particularly brave player may stomp a burrowed Mine into the ground, stifling the explosion but causing a localized detonation at their feet. This explosion inflicts $144791s1 Physical damage and knocks the player high into the air."},
			{id=8181,title="Ricochet",body="The Iron Juggernaut launches the sawblade from its arm, causing $144327s1 Physical damage to players that come into contact with the blade as it whirls and ricochets between distant players.",difficultyIDs={16}},
			{id=8185,title="Flame Vents",body="The Iron Juggernaut emits flame from its frontal vents, inflicting $144464s1 Fire damage in a frontal cone. This effect applies Ignite Armor, which increases damage taken by Fire effects by $144467s1% sears the target's flesh for for $144467s2 damage every $144467t2 second. This effect stacks."},
			{id=8178,title="Breaking the Defense: Siege Mode",body="The Iron Juggernaut plants itself in its current position, boring deep into the ground. It will no longer focus on a single target.\n$[!16\nDuring Siege mode, the Iron Juggernaut releases crawler mines at an increased rate.$]"},
			{id=8187,title="Seismic Activity",body="The Iron Juggernaut's drills deep into the earth, causing a violent earthquake. This earthquake inflicts $144484s1 Nature damage every $144483t1 second to all players. The seismic activity causes intermittent Shock Pulses."},
			{id=8189,title="Shock Pulse",body="Shock Pulse causes a wave of force that knocks players back significantly."},
			{id=8180,title="Demolisher Cannons",body="The shoulder-mounted turrets of the Iron Juggernaut fire high into the sky over random players, inflicting $144154s1 Fire damage to players within $144154A1 yards of each blast."},
			{id=8190,title="Cutter Laser",body="The Iron Juggernaut's tail cannon now traces the ground as it chases each target.\n\nThe laser inflicts $144918s1 Fire damage every $144918t1 sec to players with which it comes into contact."},
			{id=8191,title="Explosive Tar",body="The Iron Juggernaut spews tar in all directions. Standing in tar deals $144498s1 Nature damage every $144498t1 second and reduces movement speed by $144498s2%.\n\nIf a tar puddle comes into contact with the flames of the cutter laser, the puddle will explode, inflicting $144919s1 Fire damage to all players."},
			{id=8192,title="Mortar Barrage",body="The Iron Juggernaut's top cannon rapidly fires numerous Mortar Blasts towards one of the Iron Juggernaut's sides, dealing $144556s1 Fire damage to players within $144556A1 yards of each blast.",difficultyIDs={16}},
		},
	},
	[865]={
		encounterID=865,
		instanceID=369,
		order=12,
		name="Siegecrafter Blackfuse",
		lore="Helix Blackfuse was the only goblin with the combination of engineering prowess, professionalism, and ruthlessness to satisfy Garrosh in his search for the engineer of the True Horde. A mercenary at heart, Blackfuse's love for his creations (and the gold they fetch) has forever linked his fate with that of his patron and Warchief.",
		dungeonEncounterID=1601,
		uiMapID=565,
		pin={x=0.5879,y=0.4653},
		difficultyIDs={14,15,16,17,241},
		npcIDs={71504,72694},
		displayIDs={51657},
		loot={
