		sections={
			{id=10221,title="Overview",body="The fight against Blackfuse unfolds amidst a weapons manufacturing assembly line. Each time the conveyor belts activate, three disassembled weapons of various types roll out, and players may access the assembly line by jumping into nearby pipes, to destroy one of the three. The remaining two will be activated and assault the raid until they slide out of view."},
			{id=10222,title="Damage Dealers",body="$bullet;Take turns going onto the Assembly Line to destroy one Disassembled Weapon per wave.\n$bullet;Automated Shredders' |cFF2959D3|Hspell:143387|h[Reactive Armor]|h|r makes normal attacks ineffective against them.\n$bullet;Destroy Crawler Mines before they can reach their targets."},
			{id=10223,title="Healers",body="$bullet;When an Electromagnet activates, |cFF2959D3|Hspell:144466|h[Magnetic Crush]|h|r deals sustained raidwide damage.\n$bullet;Automated Shredders deal increasing amounts of raidwide damage with |cFF2959D3|Hspell:145444|h[Overload]|h|r the longer they are alive."},
			{id=10224,title="Tanks",body="$bullet;Blackfuse heals any nearby Automated Shredders with his |cFF2959D3|Hspell:144213|h[Automatic Repair Beam]|h|r.\n$bullet;As you gain applications of Blackfuse's |cFF2959D3|Hspell:143385|h[Electrostatic Charge]|h|r, you can more effectively damage Automatic Shredders through their |cFF2959D3|Hspell:143387|h[Reactive Armor]|h|r."},
			{id=8194,title="Siegecrafter Blackfuse"},
			{id=8195,title="Launch Sawblade",body="Siegecrafter Blackfuse launches a magnetized sawblade at a random player. The sawblade will hover in place until it is removed by an Activated Electromagnet."},
			{id=8196,title="Serrated Slash",body="Sawblades inflict $143327s1 Physical damage to any players or Automated Shredders with which they come into contact, knocking back any affected players."},
			{id=8303,title="Protective Frenzy",body="When one of his creations is destroyed, Siegecrafter Blackfuse enters a frenzy, increasing his attack speed by $145365s1% for $145365d."},
			{id=8197,title="Electrostatic Charge",body="Siegecrafter Blackfuse charges his target with static electricity, inflicting $143385s1 Nature damage. \n\nElectrostatic Charge also leaves a lingering effect increasing the damage taken from Electrostatic Charge by $143385s2% increasing damage dealt to targets with Reactive Armor by $143385s3%.\n\nThis effect stacks up to 10 times."},
			{id=8198,title="Automatic Repair Beam",body="Siegecrafter Blackfuse's suit is fitted with an Automatic Repair Beam, which will detect any damaged Automated Shredders within 35 yards, and heal them for $144213s1% of their maximum health every $144213t1 sec.",difficultyIDs={14,15,16}},
			{id=8408,title="Overcharge",body="When activated weapons arrive on the assembly line, Siegecrafter Blackfuse will Overcharge one of them, increasing its power and effectiveness.",difficultyIDs={16}},
			{id=8476,title="Energized Defensive Matrix",body="If three weapons make it through the Assembly Line and into Blackfuse's assembly machine, the machine will become overcharged and use the excess energy to power the defensive systems on Blackfuse's suit, granting him $148990s1% reduced damage for $148990d.",difficultyIDs={14,15,16}},
			{id=8199,title="Automated Shredders",body="Siegecrafter Blackfuse will periodically call in Automated Shredders to join the fight."},
			{id=8200,title="Reactive Armor",body="Automated Shredders have been retrofitted with Reactive Armor, reducing damage taken by $143387s1%.\n\nAutomated Shredders can also be damaged by Serrated Slash, Shockwave Missile, Detonate! and Superheated."},
			{id=8201,title="Death from Above",body="The Automated Shredder propels itself into the air and then slams back into the ground, dealing $144210s1 damage to players within $144210A1 yards of the point of impact.\n\nAfter landing, the Shredder is stunned and takes $144210s4% additional damage for $144210d."},
			{id=8286,title="Overload",body="The Automated Shredder will periodically cast Overload, dealing $145444s1 damage to raid members not currently on the conveyor belt, and increasing its damage dealt by $145444s2%."},
			{id=8202,title="The Assembly Line",body="Periodically, Siegecrafter Blackfuse will initiate fabrication of a set of weapons on the assembly line in his workshop.\n\nDisassembled weapons are brought in via conveyor belts along the northwest side of his room. They then pass through an assembly machine on the northeast wall of his room. Finally, they emerge completed on conveyor belts along the southeast wall of his room, where they attack players.\n\nPlayers can use Transport Pipes to reach the conveyor belt along the northwest side of his room, where they can attack and destroy the disassembled weapons. After players destroy a weapon, the remaining weapons become shielded and cannot be damaged."},
			{id=8206,title="Transport Pipes",body="Transport Pipes line the western edge of Siegecrafter Blackfuse's workshop. Players can jump into these pipes to reach the conveyor belt along the northwest side of the workshop."},
			{id=8207,title="Pattern Recognition",body="After using the transport pipes to reach the conveyor belt, the assembly line recognizes a player's biological signature and will reject further attempts to use them for $144236d.",difficultyIDs={14,15,16}},
			{id=8203,title="Matter Purification Beam",body="Matter Purification Beams line the platform, inflicting $144335s1 Fire damage to any players that come into contact with them."},
			{id=8204,title="Shockwave Missile Turret"},
			{id=8205,title="Shockwave Missile",body="The Shockwave Missile turret launches a drill-tipped Shockwave Missile into the ground, sending a barrage of drills that ripple out from the impact location and create rings of seismic energy.\n\nEach ring of seismic energy inflicts $144658s2 Nature damage to all players caught within it."},
			{id=8409,title="Overcharged Missile Turret",body="When Overcharged, the Shockwave Missile Turret will fire Shockwave Missiles which persist and continuously barrage the platform with drills and seismic energy until destroyed by players.",difficultyIDs={16}},
			{id=8208,title="Laser Turret"},
			{id=8209,title="Superheated",body="The ground hit by a Laser Turret's beam burns any players or Automated Shredders who step on it, inflicting $143856s1 Fire damage each second for $143856d.\n\nThis effect stacks every second that a player or Automated Shredder remains on Superheated ground, and can stack up to 20 times."},
			{id=8410,title="Overcharged Laser Turret",body="When Overcharged, Siegecrafter Blackfuse's laser turrets will fire a split beam, creating three concentric arcs of Superheated ground.",difficultyIDs={16}},
			{id=8210,title="Electromagnet"},
			{id=8211,title="Magnetic Crush",body="When activated, the electromagnet will begin to magnetically crush all players on the platform, inflicting $144466s1 Physical damage each second and pulling them towards the electromagnet.\n\nThe force of the electromagnet will also pull all sawblades on the platform towards it and off the platform, causing them to damage any players or Automated Shredders in the path of the blades."},
			{id=8411,title="Overcharged Electromagnet",body="When Overcharged, the Electromagnet will periodically reverse polarities, pushing both players and sawblades in and out from the magnet.",difficultyIDs={16}},
			{id=8212,title="Crawler Mine",body="Assembled Crawler Mines leap down from the conveyor belt, fixating on a random player."},
			{id=8213,title="Detonate!",body="When a Crawler Mine reaches its target it will self-destruct, inflicting $143002s1 Fire damage to players within $143002A1 yards and knocking them into the air."},
			{id=8214,title="Break-in Period",body="Crawler mines are vulnerable to roots, snares and stuns for $145269d after joining the battle."},
			{id=8287,title="Ready to Go!",body="After their Break-in Period expires, Crawler Mines lose their vulnerability to stuns, roots and snares, and their speed increases."},
			{id=8412,title="Overcharged Crawler Mines",body="When Overcharged, Crawler Mines activate a construction matrix within their machinery. This construction matrix enables them to create two new Crawler Mines when they are destroyed.",difficultyIDs={16}},
		},
	},
	[866]={
		encounterID=866,
		instanceID=369,
		order=3,
		name="Norushen",
		lore="Some say that the mogu race was created in the image of this titanic construct, left deep beneath Pandaria to watch over and guard the continent's darkest and most dangerous secret.",
		dungeonEncounterID=1624,
		uiMapID=558,
		pin={x=0.5426,y=0.5923},
		difficultyIDs={14,15,16,17,241},
		npcIDs={71965,72276},
		displayIDs={48860,49360},
		loot={
			{itemID=112545,diffs={},faction=-1},
			{itemID=112546,diffs={},faction=-1},
			{itemID=112547,diffs={},faction=-1},
			{itemID=112548,diffs={},faction=-1},
			{itemID=112549,diffs={},faction=-1},
			{itemID=112550,diffs={},faction=-1},
			{itemID=112551,diffs={},faction=-1},
			{itemID=112552,diffs={},faction=-1},
			{itemID=112553,diffs={},faction=-1},
			{itemID=112554,diffs={},faction=-1},
			{itemID=112555,diffs={},faction=-1},
			{itemID=112556,diffs={},faction=-1},
			{itemID=112557,diffs={},faction=-1},
			{itemID=112558,diffs={},faction=-1},
			{itemID=112559,diffs={},faction=-1},
			{itemID=112560,diffs={},faction=-1},
			{itemID=112561,diffs={},faction=-1},
			{itemID=112562,diffs={},faction=-1},
			{itemID=112563,diffs={},faction=-1},
			{itemID=112564,diffs={},faction=-1},
			{itemID=112565,diffs={},faction=-1},
			{itemID=112503,diffs={},faction=-1},
		},
		sections={
			{id=10139,title="Overview",body="Norushen seals all players inside a Quarantine Zone and extracts a portion of each player's corruption to form an Amalgam of Corruption. The object of the encounter is to destroy this creature.\n\nPlayers must reduce their personal level of Corruption in order to inflict full damage to the Amalgam. Players can accomplish this by interacting with the nodes of Purifying Light that active around the room, which will pull them into another phase where they must face a role-specific challenge. Overcoming this challenge will Purify the player and allow them to inflict full damage to the Amalgam."},
			{id=10140,title="Damage Dealers",body="$bullet;Interact with a Purifying Light orb to enter the Test of Serenity and defeat the enemies inside to rid yourself of Corruption.\n$bullet;All damage dealt to Manifestations of Corruption and Essences of Corruption in the normal realm is copied to the boss Amalgam.\n$bullet;Rotate around the Amalgam to avoid |cFF2959D3|Hspell:145227|h[Blind Hatred]|h|r."},
			{id=10141,title="Healers",body="$bullet;Interact with a Purifying Light orb to enter the Test of Reliance; inside, keep your allies at full health to maximize their damage to the Greater Corruption and complete the trial.\n$bullet;Rotate around the Amalgam to avoid |cFF2959D3|Hspell:145227|h[Blind Hatred]|h|r."},
			{id=10142,title="Tanks",body="$bullet;Interact with a Purifying Light orb to enter the Test of Confidence; avoid and weather the Titanic Corruption's attacks to rid yourself of Corruption.\n$bullet;Rotate around the Amalgam to avoid |cFF2959D3|Hspell:145227|h[Blind Hatred]|h|r.\n$bullet;Take turns tanking the Amalgam to allow |cFF2959D3|Hspell:146124|h[Self Doubt]|h|r to fade."},
			{id=8215,title="Norushen's Trial",body="Norushen traps players in a Quarantine Zone and challenges them to face and overcome their own Corruption if they wish to proceed deeper into the vault."},
			{id=8252,title="Corruption",body="Players start the encounter with 75 points of Corruption. The more corrupt a player is the less damage they will inflict to the Amalgam of Corruption."},
			{id=8253,title="Purified",body="Players who reach 0 Corruption become Purified. Healers who are Purified gain bonus healing, tanks who are Purified take less damage, and damage dealers inflict greater damage by virtue of having less Corruption.\n\nPurified persists until the player is once again Corrupted."},
			{id=8401,title="Quarantine Measures",body="If the Amalgam of Corruption proves too dangerous, Norushen will have no choice but to activate the zone's safety measures and destroy all life within."},
			{id=8216,title="Amalgam of Corruption"},
			{id=8218,title="Unleashed Anger",body="The Amalgam slashes at its current tank target, inflicting $145212s1 Physical damage."},
			{id=8440,title="Self Doubt",body="The Amalgam inflicts doubt on its current tank target. Self Doubt increases the damage of Unleashed Anger by $146124s1% per application."},
			{id=8219,title="Blind Hatred",body="The Amalgam creates a zone of corruption that extends outward and slowly turns in place. All players caught in the path of the corruption suffer $145227s1 Shadow damage every second."},
			{id=8241,title="Fusion",body="Every Expelled Corruption that reaches the Amalgam of Corruption will increase the damage the Amalgam inflicts by $145132s1% for $145132d."},
			{id=8333,title="Icy Fear",body="The Amalgam inflicts $145735s1 Frost damage to all players every $145733t1 sec. This damage increases as the Amalgam loses health."},
			{id=8413,title="Frayed",body="When the Amalgam reaches 50% health remaining, and for every 10% health lost thereafter, the Amalgam spawns an Unleashed Manifestation of Corruption."},
			{id=8220,title="Look Within",body="Players can interact with Purifying Light to Look Within. Doing so transports the player to their own realm where they face a personal challenge based on their role. Successfully completing the challenge will return the player to the normal realm with zero Corruption.\n\nPlayers cannot Look Within while under the effects of Purified.\n\n$[!17 In Raid Finder Difficulty, players are automatically selected to Look Within. There are no Purifying Light objects to interact with.$]"},
			{id=8221,title="Test of Serenity",body="Players of the DPS role face the Test of Serenity. To complete this challenge, players must defeat the elements of corruption present. Whenever one of these elements of corruption is defeated, it will be unleashed into the normal realm.\n\nFailure to complete the challenge will unleash all remaining elements of corruption to the normal realm at once."},
			{id=8224,title="Manifestation of Corruption",body="These sha creatures repeatedly cast Tear Reality, which inflict Shadow damage to all enemies in a cone in front of the caster."},
			{id=8225,title="Essence of Corruption",body="These lesser sha creatures repeatedly cast Expel Corruption, which fires a ball of corrupted energies in a straight line, dealing $144480s1 Shadow damage to anyone it strikes."},
			{id=8222,title="Test of Reliance",body="Players of the Healer role face the Test of Reliance. To complete this challenge, players must defeat a Greater Corruption. Healers are aided by several allies while Looking Within.\n\nFailure to complete the challenge will unleash a Manifestation of Corruption to the normal realm. Success returns the player to the normal realm cleansed of all Corruption."},
			{id=8227,title="Greater Corruption"},
			{id=8238,title="Disheartening Laugh",body="Inflicts Shadow damage to all enemies over $146707d."},
			{id=8402,title="Pit of Despair",body="Inflicts $146703s1 Shadow damage every second to all enemies within the area."},
			{id=8239,title="Lingering Corruption",body="Inflicts $144514s1 Shadow damage if not dispelled from the victim within $144514d."},
			{id=8223,title="Test of Confidence",body="Players of the Tank role face the Test of Confidence. To complete this challenge, the tank must survive for $144851d against a Titanic Corruption.\n\nSuccess returns the player to the normal realm with zero corruption."},
			{id=8230,title="Titanic Corruption"},
			{id=8242,title="Titanic Smash",body="Inflicts $144628s2 Shadow damage to anyone in a cone in front of the caster."},
			{id=8243,title="Corruption",body="Every successful strike received from the Titanic Corruption inflicts the victim with a stack of Corruption, inflicting $144639s1 Shadow damage per application every second."},
			{id=8244,title="Hurl Corruption",body="The caster hurls a ball of corruption at their target, inflicting $144649s1 Shadow damage."},
			{id=8245,title="Burst of Corruption",body="Inflicts $144654s1 Shadow damage to all enemies."},
			{id=8246,title="Piercing Corruption",body="Inflicts $144657s1 Physical damage to the target. This attack cannot be absorbed."},
			{id=8231,title="Unleashed Corruption",body="Whenever players successfully defeat an element of corruption during the Test of Serenity it will be unleashed in the normal realm."},
			{id=8482,title="Foul Link",body="The creatures released from the Test of Serenity copy their damage to the Amalgam of Corruption."},
			{id=8232,title="Manifestation of Corruption"},
			{id=8403,title="Burst of Anger",body="Inflicts $147082s1 Shadow damage to all players within the Quarantine Zone."},
			{id=8248,title="Residual Corruption",body="When an Unleashed Manifestation of Corruption dies, it leaves behind a small amount of corruption that will periodically inflict $145073s1 Shadow damage to all players in the Quarantine Zone until it is picked up. Players are unable to pick up the Residual Corruption unless they have removed sufficient corruption of their own first.\n\nResidual Corruption gives the player 25 Corruption."},
			{id=8233,title="Essence of Corruption"},
			{id=8249,title="Expel Corruption",body="A ball of corrupted energy travels outward from the caster, inflicting $145134s1 Shadow damage to the first enemy in its path. Every Expelled Corruption that reaches the Amalgam of Corruption will increase the damage the Amalgam inflicts by $145132s1% for $145132d."},
		},
	},
	[867]={
		encounterID=867,
		instanceID=369,
		order=4,
		name="Sha of Pride",
		lore="The seventh sha, the Sha of Pride, was the final burden to which Emperor Shaohao clung, shrouding the land in mist and biding its time for millennia. When Garrosh awakened the Heart of Y'Shaarj, the force of his arrogance caused this dark energy to coalesce in the chamber where the Heart was unearthed.",
		dungeonEncounterID=1604,
		uiMapID=558,
		pin={x=0.2935,y=0.6691},
		difficultyIDs={14,15,16,17,241},
		npcIDs={71734},
		displayIDs={49098},
		loot={
			{itemID=104162,diffs={14,15,16,17},faction=-1},
			{itemID=104163,diffs={14,17},faction=-1},
			{itemID=99714,diffs={16},faction=-1},
			{itemID=99715,diffs={16},faction=-1},
			{itemID=99716,diffs={16},faction=-1},
			{itemID=99677,diffs={17},faction=-1},
			{itemID=99742,diffs={14},faction=-1},
			{itemID=99678,diffs={17},faction=-1},
			{itemID=99743,diffs={14},faction=-1},
			{itemID=99679,diffs={17},faction=-1},
			{itemID=99744,diffs={14},faction=-1},
			{itemID=99686,diffs={15},faction=-1},
			{itemID=99691,diffs={15},faction=-1},
			{itemID=99696,diffs={15},faction=-1},
			{itemID=112947,diffs={},faction=-1},
			{itemID=112948,diffs={},faction=-1},
			{itemID=112949,diffs={},faction=-1},
			{itemID=112950,diffs={},faction=-1},
			{itemID=112951,diffs={},faction=-1},
			{itemID=112952,diffs={},faction=-1},
			{itemID=112953,diffs={},faction=-1},
			{itemID=112954,diffs={},faction=-1},
			{itemID=112955,diffs={},faction=-1},
			{itemID=112702,diffs={},faction=-1},
		},
		sections={
			{id=10143,title="Overview",body="Players gain 5 Pride when hit by any ability from the Sha of Pride or its minions, though Norushen periodically protects several players at a time from this effect. The Sha of Pride's abilities trigger increasingly dangerous effects on players the more Pride they have. \n\nWhen the Sha of Pride reaches 30% health remaining, it destroys Norushen, who purifies the raid of their Pride with his final action. From that point, players must defeat the Sha before their Pride overwhelms them."},
			{id=10144,title="Damage Dealers",body="$bullet;Quickly defeat Manifestations of Pride and interrupt their |cFF2959D3|Hspell:144379|h[Mocking Blast]|h|r to avoid gaining Pride.\n$bullet;When allies are trapped by |cFF2959D3|Hspell:144574|h[Corrupted Prison]|h|r, stand on the locks beside the prison to free them.\n$bullet;If your Pride is between 50 and 74 when the Sha casts |cFF2959D3|Hspell:144400|h[Swelling Pride]|h|r, stand in your nearby |cFF2959D3|Hspell:145320|h[Projection]|h|r to prevent a raidwide explosion."},
			{id=10145,title="Healers",body="$bullet;Dispel allies' |cFF2959D3|Hspell:144351|h[Mark of Arrogance]|h|r when you have |cFF2959D3|Hspell:146594|h[Gift of the Titans]|h|r to avoid gaining Pride.\n$bullet;When allies are trapped by |cFF2959D3|Hspell:144574|h[Corrupted Prison]|h|r, stand on the locks beside the prison to free them.\n$bullet;The Sha casts |cFF2959D3|Hspell:144400|h[Swelling Pride]|h|r upon reaching 100 Energy, dealing heavy raidwide damage.\n$bullet;If your Pride is between 50 and 74 when the Sha casts |cFF2959D3|Hspell:144400|h[Swelling Pride]|h|r, stand in your nearby |cFF2959D3|Hspell:145320|h[Projection]|h|r to prevent a raidwide explosion."},
			{id=10146,title="Tanks",body="$bullet;Immediately taunt the Sha whenever your fellow tank if afflicted by |cFF2959D3|Hspell:144358|h[Wounded Pride]|h|r.\n$bullet;When allies are trapped by |cFF2959D3|Hspell:144574|h[Corrupted Prison]|h|r, stand on the locks beside the prison to free them.\n$bullet;If your Pride is between 50 and 74 when the Sha casts |cFF2959D3|Hspell:144400|h[Swelling Pride]|h|r, stand in your nearby |cFF2959D3|Hspell:145320|h[Projection]|h|r to prevent a raidwide explosion."},
			{id=8255,title="Pride",body="Players start the encounter with 0 points of Pride. Whenever hit by an ability from the Sha of Pride or one of its minions, players gain 5 Pride.\n\nAs a player's Pride increases to 25, 50, 75 and 100, Swelling Pride will inflict additional effects on that player."},
			{id=8268,title="Gift of the Titans",body="Norushen periodically grants players immunity to Pride for $146594d. In addition, if all players with Gift of the Titans stand within $144363A1 yards of each other, they gain Power of the Titans."},
			{id=8269,title="Power of the Titans",body="If all players with Gift of the Titans stand within $144363A1 yards of each other, they gain Power of the Titans for $144364d.\n\nPower of the Titans increases haste and all damage and healing done by $144364s1%."},
			{id=8256,title="Swelling Pride",body="When the Sha of Pride reaches 100 energy, it releases a wave of dark energy, inflicting $144400s1 Shadow damage to all players, giving them 5 Pride.\n\nIn addition, Swelling Pride will trigger a secondary effect on any player with 25 or more Pride."},
			{id=8257,title="Bursting Pride",body="When Swelling Pride hits a player that has 25 to 49 Pride, it creates a mass of Sha corruption at their location. After 3 seconds, the corruption explodes, inflicting $144911s1 Shadow damage to all players within $144911A1 yards.\n\nAny player damaged by this explosion gains 5 Pride."},
			{id=8258,title="Projection",body="When Swelling Pride hits a player that has 50 to 74 Pride, a projection forms 15 yards from their current location. Projections explode after 6 seconds, inflicting $145320s1 Shadow damage to all players, unless the projection's creator is standing within it.\n\nAny player damaged by a projection's explosion gains 5 Pride."},
			{id=8400,title="Aura of Pride",body="When Swelling Pride hits a player that has 75 to 99 Pride, it afflicts them with Aura of Pride for $146817d. This effect causes the player to inflict $146818s1 Shadow damage to allies within $146818A1 yards every $146817t1 sec.\n\nAny player damaged by Aura of Pride gains 5 Pride."},
			{id=8270,title="Overcome",body="When players reach 100 Pride, they are Overcome, increasing their damage and healing done by $144843s2%.\n\nPlayers hit by Swelling Pride while Overcome are permanently mind controlled and have their health increased by $144863s3%."},
			{id=8260,title="Mark of Arrogance",body="The Sha of Pride marks 2 players, inflicting $144351s1 Shadow damage every $144351t2 sec, for the remainder of the encounter. This effect stacks.\n\nThis effect is only removed by single target dispels and gives the dispeller 5 Pride when removed."},
			{id=8261,title="Wounded Pride",body="The Sha of Pride wounds his current target for $144358d. Wounded players gain 5 Pride whenever they suffer melee damage from the Sha of Pride.",difficultyIDs={14,15,16}},
			{id=8262,title="Manifestation of Pride",body="The Sha of Pride periodically summons Manifestations of Pride to attack players."},
			{id=8263,title="Mocking Blast",body="Manifestations of Pride blast a random player, inflicting $144379s1 Shadow damage, giving them 5 Pride."},
			{id=8271,title="Last Word",body="When a Manifestation of Pride dies, it gives 5 Pride to the 2 closest players."},
			{id=8265,title="Self-Reflection",body="The Sha of Pride causes up to 5 players to reflect on their actions, creating a Reflection of Pride at their location. With each tick of Self-Reflection, the Sha focuses on players with higher levels of Pride, only targeting those with 25, 50, and then 75 Pride."},
			{id=8272,title="Reflection",body="Reflections explode out of the ground at a player's location after 2 sec, inflicting $144788s1 Shadow damage to all players within $144788A1 yards.\n\nAny player damaged by this explosion gains 5 Pride."},
			{id=8266,title="Corrupted Prison",body="The Sha of Pride activates 2 titan prisons, trapping a player inside each. As the prison activates, it releases a burst of Sha energy that inflicts $144615s2 Shadow damage to all players within $144615A1 yards, knocking them back and giving them 5 Pride.\n\nImprisoned players are stunned, suffer $144574s3 Shadow damage, and gain 5 Pride every second while they remain imprisoned. \n\nPlayers remain stunned until all titan locks surrounding the prison have been activated. Titan locks are activated by having a player stand within the lock's rune and remain there until the prison is deactivated."},
			{id=8259,title="Banishment",body="The Sha of Pride banishes random players to the corrupted Sha Realm. Banished players leave behind a physical form of their pride and remain banished until it is destroyed.\n\nPlayers within the Sha realm move 50% faster and are compelled to continually run forward, unable to stop. Additionally, coming into contact with corruption within the Sha realm inflicts $145219s1 Shadow damage every second.\n\nAny player damaged by the Sha realm gains 5 Pride.",difficultyIDs={16}},
			{id=8281,title="Orb of Light",body="Orbs of Light form within the corrupted Sha realm that heal players for $149008s1% of the maximum health and weaken their corrupt image left behind in the corporeal world. Each orb increases the physical form's damage taken by $145345s1%. This effect stacks."},
			{id=8480,title="Ethereal Corruption",body="Ethereal Corruption lurks within the corrupted Sha realm, instantly killing any player it comes into contact with."},
			{id=8433,title="Unstable Corruption",body="The Sha's energy tears open Rifts of Corruption every $147183t1 sec. Each rift launches a bolt of corruption at a random player's location every $147389t1 sec. Players struck by the bolts suffer $147198s1 Shadow damage and gain 5 Pride.\n\nPlayers can close the rifts, causing them to explode, inflicting $147388s1 Shadow damage to all players within $147388A1 yards.\n\nClosing a rift afflicts players with Weakened Resolve, preventing them from closing another rift for $147207d.",difficultyIDs={16}},
			{id=8282,title="Reaching Attack",body="The Sha of Pride strikes at a distant target, inflicting $144774s1% of weapon damage as Shadow and increasing Shadow damage taken by $144774s2% for $144774d. The Sha uses this ability when no targets are in melee range."},
			{id=8267,title="Unleashed",body="When the Sha of Pride reaches 30% health remaining, it becomes Unleashed. With its unleashed power, the Sha focuses on Norushen, instantly killing him.\n\nThe remaining power of the unleashed Sha inflicts $144836s1 Shadow damage every $144832t2 seconds for the remainder of the encounter. \n\nPlayers gain 5 Pride each time they are damaged by Unleashed."},
			{id=8349,title="Final Gift",body="As Norushen dies, he purifies all players, reducing their Pride to zero."},
		},
	},
	[868]={
		encounterID=868,
		instanceID=369,
		order=5,
		name="Galakras",
		lore="Warlord Zaela formed a close bond with Garrosh during events in the Twilight Highlands, and she and her Dragonmaw orcs have pledged loyalty to Garrosh's cause. Riding atop the fearsome Galakras, a direct descendant of the cataclysmic progenitor of all dragonkind, Zaela oversees the naval defense of Orgrimmar.",
		dungeonEncounterID=1622,
		uiMapID=559,
		pin={x=0.772,y=0.2969},
		difficultyIDs={14,15,16,17,241},
		npcIDs={72249},
		displayIDs={49337},
		loot={
			{itemID=112703,diffs={},faction=-1},
			{itemID=112704,diffs={},faction=-1},
			{itemID=112705,diffs={},faction=-1},
			{itemID=112706,diffs={},faction=-1},
			{itemID=112707,diffs={},faction=-1},
			{itemID=112709,diffs={},faction=-1},
			{itemID=112710,diffs={},faction=-1},
			{itemID=112711,diffs={},faction=-1},
			{itemID=112712,diffs={},faction=-1},
			{itemID=112713,diffs={},faction=-1},
			{itemID=112714,diffs={},faction=-1},
			{itemID=112715,diffs={},faction=-1},
			{itemID=112716,diffs={},faction=-1},
			{itemID=112717,diffs={},faction=-1},
			{itemID=112718,diffs={},faction=-1},
			{itemID=112719,diffs={},faction=-1},
			{itemID=112721,diffs={},faction=-1},
			{itemID=112723,diffs={},faction=-1},
			{itemID=112725,diffs={},faction=-1},
			{itemID=112726,diffs={},faction=-1},
			{itemID=112727,diffs={},faction=-1},
			{itemID=112728,diffs={},faction=-1},
		},
		sections={
			{id=10195,title="Overview",body="Players assault fortified towers as waves of Kor'kron troops rush forth to repel them, and Warlord Zaela circles overhead on her fearsome proto-drake, Galakras. Meanwhile, allied demolitionists work to breach the doors to the nearby guard towers, allowing a strike team to enter the tower and capture it. Once both towers have been captured, the anti-air guns atop each may be used to bring Galakras down to the ground for a final battle."},
			{id=10196,title="Damage Dealers",body="$bullet;Quickly destroy Healing Tide Totems and War Banners.\n$bullet;Interrupt Tidal Shamans' |cFF2959D3|Hspell:146757|h[Chain Heal]|h|r.\n$bullet;If targeted by Galakras's |cFF2959D3|Hspell:146992|h[Flames of Galakrond]|h|r, lead it through your allies to diminish its potency."},
			{id=10197,title="Healers",body="$bullet;When Korgra the Snake reaches 50% health remaining, her |cFF2959D3|Hspell:147713|h[Venom Bolt Volley]|h|r will deal heavy raidwide damage.\n$bullet;If targeted by Galakras's |cFF2959D3|Hspell:146992|h[Flames of Galakrond]|h|r, lead it through your allies to diminish its potency."},
			{id=10198,title="Tanks",body="$bullet;Interrupt Tidal Shamans' |cFF2959D3|Hspell:146757|h[Chain Heal]|h|r.\n$bullet;When a tower is breached, one tank must lead a small group of players to clear out remaining Kor'kron."},
			{id=8417,title="Stage One: Bring Her Down!",body="Warlord Zaela sends her finest Dragonmaw soldiers to battle. Two guardians keep watch over the Towers above, protecting the Anti-Air turrets. Defeating these guardians will give players access to the Anti-Air turrets.\n\nTwo well-timed Anti-Air turret shots will send Galakras spiraling towards the ground."},
			{id=8421,title="Ranking Officials"},
			{id=8422,title="Master Cannoneer Dagryn"},
			{id=8446,title="Shoot",body="Dagryn shoots at random players nearby, inflicting heavy damage."},
			{id=8447,title="Muzzle Spray",body="Dagryn unleashes a muzzle flare, inflicting $147824s1 Physical damage multiple times per second, and knocking players back with each hit."},
			{id=8423,title="Lieutenant General Krugruk"},
			{id=8448,title="Thunder Clap",body="With a mighty stomp Krugruk shatters the ground, slowing nearby players' movement speed. This effect stacks."},
			{id=8449,title="Arcing Smash",body="Krugruk rears back his mighty spear, inflicting $147688s1 Physical damage to players in a frontal cone and knocking them back."},
			{id=8424,title="High Enforcer Thranok"},
			{id=8444,title="Shattering Cleave",body="With a mighty swing, Thranok inflicts $146849s1% normal damage to his primary target and additional nearby targets."},
			{id=8445,title="Crusher's Call",body="High Enforcer Thranok lashes out with chains, hooking 5 random players within $146769A1 yards and pulls them to his feet. $[!4, 6, 7\n\nIn 25 player mode, High Enforcer Thranok hooks 10 random players.$]\n\nAfterwards, Thranok rears back to execute his savage attack, Skull Cracker, that inflicts $146848s2 Physical damage to all players within $146848A2 yards."},
			{id=8425,title="Korgra the Snake"},
			{id=8441,title="Poison-Tipped Blades",body="Korgra's poison-tipped dagger inflicts $146902s1 Nature damage every $146902t1 sec.  to her primary target. This effect stacks."},
			{id=8442,title="Poison Cloud",body="Korgra shatters a vial of poison, causing a smoky poison cloud to coalesce at her feet. This poison cloud inflicts $147705s1 Nature damage every $147705t1 second to players standing within."},
			{id=8443,title="Curse of Venom",body="When her health falls low, Korgra's Curse of Venom takes effect. She will take the form of a snake, casting a deadly poison bolt volley until she is defeated."},
			{id=8426,title="Dragonmaw Ebon Stalker",body="Upon Korgra's command, these stealthed units will emerge from the shadows behind a random target, stabbing wildly. Any victims standing within range of the blows will suffer critical Physical damage."},
			{id=8427,title="Foot Soldiers"},
			{id=8428,title="Dragonmaw Bonecrusher",body="These deadly warriors will charge to a distant faction leader, stunning them. While stunned, they will perform a barrage of deadly attacks to the victim."},
			{id=8488,title="Fracture",body="The Dragonmaw Bonecrusher charges to a distant Faction Leader, stunning them and inflicting $146901s1% of the leader's health every $t1 sec."},
			{id=8431,title="Dragonmaw Tidal Shaman",body="The Dragonmaw Tidal shaman will cast healing spells on their allies, and summon violent Tidal waves to damage their enemies."},
			{id=8489,title="Healing Tide Totem",body="The Dragonmaw Tidal Shaman summons a totem at the Shaman's feet that heals nearby allies for $146755s1% of their total health every $146754t1 seconds for $146754d."},
			{id=8429,title="Dragonmaw Flameslinger",body="These deadly archers shoot fire-tipped arrows at random players. The effect inflicts Fire damage on impact, and then burns the ground and any players standing within."},
			{id=8430,title="Dragonmaw Grunt",body="Dragonmaw Grunts wade into battle, crushing their enemies with devastating blows. They will also hurl a mighty axe at distant enemies."},
			{id=8586,title="Dragonmaw Proto-Drake",body="Dragonmaw Proto-Drakes channel a frontal cone of flame on their enemies."},
			{id=8532,title="Dragonmaw Flagbearer",body="Dragonmaw Flagbearers inspire those around them, dropping a banner that increases melee, ranged, and spell casting speed by $146735s1%. It also increases damage dealt by $146735s3% for all friendly targets within 15 yards for $146735d."},
			{id=8533,title="Kor'kron Demolisher",body="Warlord Zaela turns her siege weapons against her own towers, bombarding those inside. Bombard inflicts $148311s1 Physical damage and knocks down players inside the bombarded tower."},
			{id=8484,title="Allies"},
			{id=8485,title="Lady Sylvanas Windrunner",body="Lady Sylvanas fires with precision at her enemies, occasionally awakening the dead to do her bidding."},
			{id=8486,title="Archmage Aethas Sunreaver"},
			{id=8487,title="Flamestrike",body="Aethas calls down a flamestrike that lasts $148848d., inflicting $147431s1 Fire damage every $146787t1 sec. to all enemies in a selected area."},
			{id=8490,title="Lor'themar Theron",body="Lor'themar fights with fervor charging enemies with his blade, the Great Sword of the Sin'dorei, and picking off stragglers with his enchanted bow."},
			{id=8535,title="Demolition Crew",body="The Demolition crew will attempt to breach the doors barring the Anti-Air towers. If they are not protected, then the door breaching progress will be interrupted.",difficultyIDs={16}},
			{id=8418,title="Stage Two: Galakras, The Last of His Progeny"},
			{id=8420,title="Flames of Galakrond",body="Galakras spews the raw Flames of Galakrond at a random player. Each player through which it passes will suffer $147029s1 Fire damage every $147029t1 second. However, each player it passes through will decrease the severity of the flames, reducing the damage it deals to subsequent players.\n\nWhen the ball of flame reaches its final destination it will erupt, inflicting $146992s1 Fire damage to all players. This damage is also reduced in severity for each player that diminishes the Flame."},
			{id=8419,title="Pulsing Flames",body="Galakras erupts with molten fury, inflicting $147043s1 Fire damage to all players. Each pulse increases Galakras' Fire damage dealt by $147043s2%."},
		},
	},
	[869]={
		encounterID=869,
		instanceID=369,
		order=14,
		name="Garrosh Hellscream",
		lore="Garrosh, son of Grommash Hellscream, first learned of his father's heroism when Thrall encountered the young orc in Outland. The seeds of pride were planted. Garrosh spearheaded Horde victories in Northrend and, as Warchief, consolidated Horde power amidst the chaos of the Cataclysm. But his visions of orc supremacy by any means have brought the armies of the world crashing down upon Orgrimmar... a final reckoning that Garrosh himself awaits with brutal relish.",
		dungeonEncounterID=1623,
		uiMapID=567,
		pin={x=0.4943,y=0.7134},
		difficultyIDs={14,15,16,17,241},
		npcIDs={71865},
		displayIDs={49585},
		loot={
			{itemID=104253,diffs={16},faction=-1},
			{itemID=105857,diffs={15},faction=-1},
			{itemID=105858,diffs={15},faction=-1},
			{itemID=105859,diffs={15},faction=-1},
			{itemID=105860,diffs={17},faction=-1},
			{itemID=105861,diffs={17},faction=-1},
