			{itemID=112935,diffs={15,16},faction=-1},
			{itemID=112936,diffs={},faction=-1},
			{itemID=112937,diffs={},faction=-1},
			{itemID=112938,diffs={},faction=-1},
			{itemID=112939,diffs={},faction=-1},
			{itemID=112940,diffs={},faction=-1},
			{itemID=112941,diffs={},faction=-1},
